INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u4-C1','sci',3,2,'u4',1,'색칠 놀이로 친구의 상황 짐작하기 — 숫자마다 정해진 색깔로 칠하면 숨은 그림이 나타남 · 분홍색 볼은 열, 코 밑 하늘색 줄은 콧물을 떠올리게 하는 단서 · 완성된 그림으로 친구가 감기에 걸려 놀이터에 나오지 못했다고 짐작함 · 먼저 끝내도 정답을 말하지 않고 기다리며, 사인펜은 고치기 어려워 숫자를 확인하고 칠함',ARRAY['[4과08-01] 생활 속 감염병의 예를 조사하고, 감염병이 위험한 까닭을 토의할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u4-C2','sci',3,2,'u4',1,'감기와 관련된 경험 나누기 — 감기에 걸린 경험도, 다른 사람에게서 옮은 경험도 감기와 관련된 경험 · 감기는 다른 사람에게 옮기도 함 · 넘어져 다친 일, 약속을 잊은 일은 감기와 관련 없음',ARRAY['[4과08-01] 생활 속 감염병의 예를 조사하고, 감염병이 위험한 까닭을 토의할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u4-C3','sci',3,2,'u4',2,'감염병의 뜻과 병원체 — 감염병은 병을 일으키는 병원체에 감염되어 생기는 질병 · 병원체는 병의 원인이 되는 본체로 세균, 바이러스 등을 말함',ARRAY['[4과08-01] 생활 속 감염병의 예를 조사하고, 감염병이 위험한 까닭을 토의할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u4-C4','sci',3,2,'u4',2,'생활 속 감염병의 예 — 감기, 독감, 유행성 눈병, 수족구병, 수두, 코로나바이러스감염증-19 등 · 예방접종을 한 경험도 감염병과 관련된 경험 · 감기와 독감은 서로 다른 질병이고 독감은 주로 겨울철에 걸리며 예방접종으로 어느 정도 예방함',ARRAY['[4과08-01] 생활 속 감염병의 예를 조사하고, 감염병이 위험한 까닭을 토의할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u4-C5','sci',3,2,'u4',2,'감염병이 아닌 것 — 계단에서 넘어져 뼈가 부러진 일, 뜨거운 물에 데인 일, 꽃가루 때문에 나온 재채기는 병원체에 감염되어 생긴 것이 아니라서 감염병이 아님',ARRAY['[4과08-01] 생활 속 감염병의 예를 조사하고, 감염병이 위험한 까닭을 토의할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u4-C6','sci',3,2,'u4',3,'감염병 카드 조사하기 — 감염병 카드에는 이름·증상·특징을 씀 · 증상은 병을 앓을 때 나타나는 여러 가지 상태나 모양, 언제 잘 걸리는지·예방접종이 있는지는 특징 · 믿을 수 있는 누리집에서 최신 자료를 찾고 출처를 밝힘',ARRAY['[4과08-01] 생활 속 감염병의 예를 조사하고, 감염병이 위험한 까닭을 토의할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u4-C7','sci',3,2,'u4',3,'감염병의 위험성과 토의 태도 — 감염병은 다양한 증상이 나타나 몸이 아프고, 누구나 걸릴 수 있으며, 다른 사람에게 옮아 많은 사람이 걸릴 수 있고, 치료 뒤에도 증상이 오래 남기도 함 · 증상을 외우기보다 조사한 내용으로 위험한 까닭을 토의하고 친구 의견을 존중함 · 예방접종으로 몸을 보호함',ARRAY['[4과08-01] 생활 속 감염병의 예를 조사하고, 감염병이 위험한 까닭을 토의할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u4-C8','sci',3,2,'u4',4,'크게 유행할 때 달라지는 사회 — 감염병이 널리 퍼지면 많은 사람이 걸리는 것을 막으려고 사회적 거리 두기를 함 · 집에서만 지내기, 가게·학교·공공시설이 문 닫기, 병원이 환자로 가득 차 제 역할을 하기 어려움 · 사회가 크게 달라지는 것은 감염병이 대유행했을 때이고 감염병에 걸릴 때마다 그런 것은 아님',ARRAY['[4과08-02] 감염병이 사회에 미치는 영향과 생활 습관과 감염병 유행의 관련성을 설명할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u4-C9','sci',3,2,'u4',4,'감염병으로부터 안전한 사회 — 안전한 사회에서는 함께 모여 놀고 먹고 공부하며 공공시설과 병원을 쉽게 이용함 · 과학자들은 최신 과학 기술로 감염병의 원인을 밝히고 진단·치료·예방 방법을 연구함 · 너무 겁먹기보다 안전한 사회를 만드는 데 관심을 가짐',ARRAY['[4과08-02] 감염병이 사회에 미치는 영향과 생활 습관과 감염병 유행의 관련성을 설명할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u4-C10','sci',3,2,'u4',5,'생활 습관과 감염 과정 — 손을 씻지 않고 눈을 비비면 손을 통해, 먹던 음식을 나눠 먹으면 음식에 묻은 침을 통해, 아픈데 같은 교실에 있으면 공기를 통해, 확인하지 않은 물을 마시면 오염된 물을 통해, 아무렇게나 기침하면 비말을 통해 감염될 수 있음',ARRAY['[4과08-02] 감염병이 사회에 미치는 영향과 생활 습관과 감염병 유행의 관련성을 설명할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u4-C11','sci',3,2,'u4',5,'생활 습관과 감염병 유행 — 생활 습관은 감염병 유행에 영향을 미침 · 아플 때 사람이 많은 곳에 가면 감염병을 유행시킬 수 있고, 아플 때 집에서 쉬면 다른 사람에게 옮기지 않음 · 올바른 생활 습관은 유행을 막는 데 도움이 됨',ARRAY['[4과08-02] 감염병이 사회에 미치는 영향과 생활 습관과 감염병 유행의 관련성을 설명할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u4-C12','sci',3,2,'u4',5,'감염 과정을 역할극으로 표현하기 — 생활 습관 하나를 고르고 감염 과정이 드러나게 대본을 써서 역할극을 함 · 단순한 상황극이 아니라 생활 습관과 감염 과정의 관련이 드러나야 함 · 그림이나 책 만들기로도 표현할 수 있고, 역할은 공정하게 나누어 협력함',ARRAY['[4과08-02] 감염병이 사회에 미치는 영향과 생활 습관과 감염병 유행의 관련성을 설명할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u4-C13','sci',3,2,'u4',6,'감염병 예방 수칙 — 비누로 30초 이상 흐르는 물에 손 씻기 · 기침할 때 옷소매로 입과 코 가리기(심할 때는 마스크) · 음식은 익혀 먹고 깨끗한 물 마시기 · 정해진 시기에 예방접종하기 · 아플 때 집에서 쉬고 다른 사람이 먹던 음식 먹지 않기',ARRAY['[4과08-03] 감염병 예방 수칙을 조사하여 공유하고, 생활 속에서 실천할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u4-C14','sci',3,2,'u4',6,'예방 수칙과 감염 과정 잇기, 조사와 공유 — 손 씻기는 손을 통한 감염을, 옷소매로 가리기·마스크는 비말을 통한 감염을 막음 · 유행시키는 습관을 반대로 하면 예방하는 습관이 됨 · 실천할 수 있는 구체적인 행동을 믿을 수 있는 곳에서 조사하고 출처를 밝히며, 노랫말로 바꾸어 공유함',ARRAY['[4과08-03] 감염병 예방 수칙을 조사하여 공유하고, 생활 속에서 실천할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u4-C15','sci',3,2,'u4',7,'예방 수칙 실천 계획 세우기 — 학교처럼 많은 사람이 모이는 곳에서는 수칙을 더 잘 지켜야 함 · 계획에는 실천 장소, 실천할 수칙, 실천을 돕는 방법을 담음 · 「손 씻기」보다 「흐르는 물에 비누로 30초 이상 손 씻기」처럼 구체적으로 정함',ARRAY['[4과08-03] 감염병 예방 수칙을 조사하여 공유하고, 생활 속에서 실천할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u4-C16','sci',3,2,'u4',7,'실천 기록과 서로 격려하기 — 정해진 기간 동안 실천하고 실천 기록장에 매일 기록함 · 꾸준히 잘한 수칙과 어려웠던 수칙·까닭을 스스로 점검함 · 못 지킨 친구를 비난하지 않고 까닭을 찾아 고쳐 나가도록 격려함 · 꾸미기보다 꾸준한 실천이 중요함',ARRAY['[4과08-03] 감염병 예방 수칙을 조사하여 공유하고, 생활 속에서 실천할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u4-C17','sci',3,2,'u4',8,'세계 손 씻기의 날과 손을 씻어야 할 때 — 매년 10월 15일은 국제 연합 총회에서 정한 세계 손 씻기의 날로, 손 씻기의 중요성을 알리려고 정함 · 손 씻기는 가장 간단하면서도 효과적인 예방 방법이고 그날만이 아니라 매일 실천함 · 식사 전, 음식을 할 때, 기침·재채기를 한 뒤, 코를 푼 뒤, 화장실을 사용한 뒤, 쓰레기·동물을 만진 뒤에 씻음',ARRAY['[4과08-03] 감염병 예방 수칙을 조사하여 공유하고, 생활 속에서 실천할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u4-C18','sci',3,2,'u4',8,'손 씻기 6단계 — 손바닥 → 손등 → 손가락 사이(손깍지) → 두 손 모아 → 엄지손가락 → 손톱 밑 차례로 문지름 · 비누를 사용해 흐르는 물에 30초 이상 꼼꼼히 씻음',ARRAY['[4과08-03] 감염병 예방 수칙을 조사하여 공유하고, 생활 속에서 실천할 수 있다(차시 머리 주석 기준 · 문구 W7 확인)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X01','sci',3,'u4',ARRAY['SC3-2-u4-C1']::text[],'색칠 놀이에서 숫자에 정해진 색 대신 좋아하는 색으로 칠하거나 숫자를 확인하지 않는다','숫자마다 정해진 색') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X02','sci',3,'u4',ARRAY['SC3-2-u4-C1']::text[],'완성된 그림의 단서(붉은 볼, 코 밑 하늘색 줄)를 잘못 읽어 친구의 상황을 잘못 짐작한다','볼은 열 · 줄은 콧물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X03','sci',3,'u4',ARRAY['SC3-2-u4-C1']::text[],'먼저 끝낸 사람이 정답을 외치거나 빨리 칠하는 것이 놀이의 목적이라고 여긴다','스스로 찾도록 기다려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X04','sci',3,'u4',ARRAY['SC3-2-u4-C2']::text[],'감기는 다른 사람에게 옮지 않는다고 여기거나 다친 일을 감기와 관련된 경험으로 여긴다','옮은 경험도 감기 경험') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X05','sci',3,'u4',ARRAY['SC3-2-u4-C3']::text[],'감염병의 뜻을 잘못 안다(다쳐서 생기는 병, 날씨 때문에 생기는 병 등)','병원체에 감염되어 생겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X06','sci',3,'u4',ARRAY['SC3-2-u4-C3']::text[],'병원체를 잘못 안다(햇빛, 꽃가루, 상처 등으로)','세균, 바이러스 등') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X07','sci',3,'u4',ARRAY['SC3-2-u4-C4']::text[],'생활 속 감염병의 예를 찾지 못하거나 감염병은 옛날에만 있었다고 여긴다','감기도 감염병') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X08','sci',3,'u4',ARRAY['SC3-2-u4-C4']::text[],'감기가 심해지면 독감이 된다고 여긴다','서로 다른 질병') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X09','sci',3,'u4',ARRAY['SC3-2-u4-C4']::text[],'예방접종 경험은 감염병과 관련 없다고 여기거나 경험과 감염병을 잘못 잇는다','예방접종도 관련 경험') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X10','sci',3,'u4',ARRAY['SC3-2-u4-C5']::text[],'뼈가 부러지거나 데인 일, 꽃가루 재채기를 감염병으로 여긴다','감염되어 생긴 것인가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X11','sci',3,'u4',ARRAY['SC3-2-u4-C6']::text[],'감염병 카드의 증상 칸과 특징 칸을 뒤바꾸거나 증상의 뜻을 잘못 안다','앓을 때 나타나는 상태') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X12','sci',3,'u4',ARRAY['SC3-2-u4-C6']::text[],'감염병을 조사하는 방법을 잘못 안다(아무 글이나 옮기기, 출처 쓰지 않기, 오래된 자료 고르기)','믿을 수 있는 최신 자료 · 출처') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X13','sci',3,'u4',ARRAY['SC3-2-u4-C7']::text[],'감염병이 위험한 까닭을 잘못 안다(증상이 다양해서 괜찮다, 아무에게도 옮지 않는다, 일부만 걸린다 등)','누구나 · 많은 사람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X14','sci',3,'u4',ARRAY['SC3-2-u4-C7']::text[],'감염병 공부는 증상을 모두 외우는 것이라고 여긴다','외우기보다 토의') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X15','sci',3,'u4',ARRAY['SC3-2-u4-C7']::text[],'토의할 때 친구 의견을 비웃거나 내 생각만 옳다고 우긴다','끝까지 듣고 존중') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X16','sci',3,'u4',ARRAY['SC3-2-u4-C8']::text[],'사회적 거리 두기를 한 까닭을 잘못 안다(날씨, 공사 등)','널리 퍼지지 않게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X17','sci',3,'u4',ARRAY['SC3-2-u4-C8','SC3-2-u4-C9']::text[],'감염병이 크게 유행할 때의 모습과 안전한 사회의 모습을 뒤바꾼다','모여 지낼 수 있나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X18','sci',3,'u4',ARRAY['SC3-2-u4-C8']::text[],'감염병에 걸리면 언제나 학교가 문을 닫는 등 사회가 크게 달라진다고 여긴다','대유행 때의 모습') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X19','sci',3,'u4',ARRAY['SC3-2-u4-C9']::text[],'감염병은 나와 상관없다고 여겨 안전한 사회를 만드는 데 관심을 두지 않는다','모두와 관련 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X20','sci',3,'u4',ARRAY['SC3-2-u4-C9']::text[],'과학 기술이 감염병에 하는 일을 잘못 안다(아무것도 못 한다, 사람이 모이지 못하게만 한다 등)','원인 · 진단 · 치료 · 예방') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X21','sci',3,'u4',ARRAY['SC3-2-u4-C10']::text[],'생활 습관과 감염 과정을 잘못 잇는다(먹던 음식 — 오염된 물, 기침 — 손 등)','음식은 침 · 기침은 비말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X22','sci',3,'u4',ARRAY['SC3-2-u4-C10']::text[],'감염병은 한 가지 길로만 옮는다고 여기거나 손·음식과 기침·공기 쪽을 잘못 가른다','손 · 침 · 공기 · 물 · 비말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X23','sci',3,'u4',ARRAY['SC3-2-u4-C11']::text[],'생활 습관은 감염병 유행과 관련이 없다고 여긴다(날씨나 나이만 관련 있다 등)','습관이 영향을 미쳐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X24','sci',3,'u4',ARRAY['SC3-2-u4-C11']::text[],'아플 때 사람이 많은 곳에 가도 된다거나 감염병을 유행시킬 습관을 괜찮다고 여긴다','아플 때는 집에서 쉬어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X25','sci',3,'u4',ARRAY['SC3-2-u4-C12']::text[],'역할극은 재미있게 꾸미기만 하면 되고 감염 과정이 드러나지 않아도 된다고 여긴다','습관과 감염 과정이 드러나게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X26','sci',3,'u4',ARRAY['SC3-2-u4-C12']::text[],'역할극의 차례나 참여 태도를 잘못 안다(역할을 마음대로 차지하기, 대본 없이 하기 등)','공정하게 · 협력') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X27','sci',3,'u4',ARRAY['SC3-2-u4-C13','SC3-2-u4-C18']::text[],'손을 물로만 헹구거나 손바닥만 대충, 짧게 씻어도 된다고 여긴다','비누 · 흐르는 물 · 30초') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X28','sci',3,'u4',ARRAY['SC3-2-u4-C13']::text[],'기침 예절을 잘못 안다(친구 쪽으로 하기, 손바닥으로 가린 뒤 바로 악수하기 등)','옷소매로 입과 코') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X29','sci',3,'u4',ARRAY['SC3-2-u4-C13']::text[],'음식·물·예방접종 수칙을 잘못 안다(익히지 않고 먹기, 아무 물이나 마시기, 아무 때나 접종하기)','익혀 먹고 · 정해진 시기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X30','sci',3,'u4',ARRAY['SC3-2-u4-C13','SC3-2-u4-C14']::text[],'감염병을 유행시키는 습관과 예방하는 습관을 뒤바꾼다','반대로 하면 예방 습관') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X31','sci',3,'u4',ARRAY['SC3-2-u4-C14']::text[],'예방 수칙이 어떤 감염을 막는지 잘못 잇는다(옷소매로 가리기 — 손을 통한 감염 등)','손 씻기는 손 · 소매는 비말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X32','sci',3,'u4',ARRAY['SC3-2-u4-C14']::text[],'예방 수칙을 조사하고 알리는 방법을 잘못 안다(어려운 용어만 모으기, 출처 빼기, 막연한 말로 쓰기)','실천할 수 있게 구체적으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X33','sci',3,'u4',ARRAY['SC3-2-u4-C15']::text[],'실천 계획의 칸(장소·수칙·돕는 방법)을 잘못 잇거나 수칙을 막연하게 정한다','무엇을 어떻게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X34','sci',3,'u4',ARRAY['SC3-2-u4-C15','SC3-2-u4-C16']::text[],'못 지킨 친구를 지적하고 비난하는 것을 실천을 돕는 방법으로 여긴다','확인하고 격려해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X35','sci',3,'u4',ARRAY['SC3-2-u4-C16']::text[],'실천 기록장을 마지막에 몰아 쓰거나 하루만 지키면 충분하다고 여긴다','매일 꾸준히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X36','sci',3,'u4',ARRAY['SC3-2-u4-C16']::text[],'실천이 어려운 수칙 앞에서 포기하거나 남 탓을 하거나 기록을 지어낸다','까닭을 찾아 고쳐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X37','sci',3,'u4',ARRAY['SC3-2-u4-C17']::text[],'세계 손 씻기의 날의 날짜나 정한 까닭을 잘못 알거나 그날에만 손을 씻으면 된다고 여긴다','중요성을 알리려고 · 매일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X38','sci',3,'u4',ARRAY['SC3-2-u4-C17']::text[],'손을 씻어야 할 때를 잘못 안다(깨끗해 보이면 씻지 않아도 된다 등)','병원체가 묻을 수 있는 때') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X39','sci',3,'u4',ARRAY['SC3-2-u4-C18']::text[],'손 씻기 6단계의 차례나 단계별 방법을 잘못 잇는다','손바닥부터 손톱 밑까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u4-X40','sci',3,'u4',ARRAY['SC3-2-u4-C18']::text[],'손 씻기 6단계 가운데 엄지손가락·손톱 밑 같은 단계를 빠뜨려도 된다고 여긴다','여섯 단계 모두') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_basic#1','sci',3,2,'u4','L01','g3_2_sci_u4_L01_basic','lesson_basic','SC3-2-u4-C1',1,'mc','auto','색칠 놀이를 시작하기 전에 먼저 확인할 것은 무엇인가요?',ARRAY['SC3-2-u4-X01','SC3-2-u4-X03']::text[],false,'{"seq":1,"concept":"SC3-2-u4-C1","difficulty":1,"kind":"mc","stem":"색칠 놀이를 시작하기 전에 먼저 확인할 것은 무엇인가요?","options":[{"t":"숫자마다 정해진 색깔","correct":true},{"t":"가장 좋아하는 색깔","mis":"SC3-2-u4-X01"},{"t":"친구가 칠한 그림","mis":"SC3-2-u4-X03"},{"t":"종이의 크기","mis":"SC3-2-u4-X01"}],"explanation":["칸마다 숫자가 있어요.","숫자와 색이 짝이에요.","숫자마다 정해진 색깔이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_basic#2','sci',3,2,'u4','L01','g3_2_sci_u4_L01_basic','lesson_basic','SC3-2-u4-C1',1,'sa','auto','색칠 놀이 숫자와 색깔에서 숫자 4는 무슨 색으로 칠하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u4-C1","difficulty":1,"kind":"sa","stem":"색칠 놀이 숫자와 색깔에서 숫자 4는 무슨 색으로 칠하나요? 세 글자로 쓰세요.","answer":["하늘색"],"explanation":["4를 찾아요.","코 밑 줄이에요.","하늘색이에요."],"asset":{"type":"passage","lines":["1 검은색 — 머리카락과 눈, 코, 입이 나타나요.","2 주황색 — 입 둘레가 나타나요.","3 분홍색 — 양쪽 볼이 나타나요.","4 하늘색 — 코 밑으로 줄이 나타나요.","5 살구색 — 얼굴이 나타나요.","6 노란색 — 그림의 바탕이 나타나요."],"title":"색칠 놀이 숫자와 색깔"},"mis":"SC3-2-u4-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_basic#3','sci',3,2,'u4','L01','g3_2_sci_u4_L01_basic','lesson_basic','SC3-2-u4-C2',1,'ox','auto','감기는 다른 사람에게서 옮기도 해요.',ARRAY['SC3-2-u4-X04']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C2","difficulty":1,"kind":"ox","stem":"감기는 다른 사람에게서 옮기도 해요.","answer":"O","reason_options":[{"t":"동생이나 친구에게서 감기가 옮은 경험이 있기 때문에","correct":true},{"t":"감기는 혼자서만 걸리고 옮지 않기 때문에","mis":"SC3-2-u4-X04"}],"mis":"SC3-2-u4-X04","explanation":["친구들의 경험을 떠올려요.","옮은 경험이 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_basic#4','sci',3,2,'u4','L01','g3_2_sci_u4_L01_basic','lesson_basic','SC3-2-u4-C1',1,'mc','auto','완성된 그림 속 친구는 어떤 모습인가요?',ARRAY['SC3-2-u4-X02']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C1","difficulty":1,"kind":"mc","stem":"완성된 그림 속 친구는 어떤 모습인가요?","options":[{"t":"감기에 걸려 콧물을 흘려요","correct":true},{"t":"축구를 하고 있어요","mis":"SC3-2-u4-X02"},{"t":"노래를 부르고 있어요","mis":"SC3-2-u4-X02"},{"t":"잠을 자고 있어요","mis":"SC3-2-u4-X02"}],"explanation":["하늘색 줄을 떠올려요.","코 밑에 있어요.","감기에 걸린 모습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_basic#5','sci',3,2,'u4','L01','g3_2_sci_u4_L01_basic','lesson_basic','SC3-2-u4-C1',2,'mc','auto','색칠 놀이 숫자와 색깔에서 양쪽 볼을 칠하는 숫자는 무엇인가요?',ARRAY['SC3-2-u4-X01']::text[],false,'{"seq":5,"concept":"SC3-2-u4-C1","difficulty":2,"kind":"mc","stem":"색칠 놀이 숫자와 색깔에서 양쪽 볼을 칠하는 숫자는 무엇인가요?","options":[{"t":"3","correct":true},{"t":"1","mis":"SC3-2-u4-X01"},{"t":"4","mis":"SC3-2-u4-X01"},{"t":"6","mis":"SC3-2-u4-X01"}],"explanation":["볼을 찾아요.","분홍색이에요.","3이에요."],"asset":{"type":"passage","lines":["1 검은색 — 머리카락과 눈, 코, 입이 나타나요.","2 주황색 — 입 둘레가 나타나요.","3 분홍색 — 양쪽 볼이 나타나요.","4 하늘색 — 코 밑으로 줄이 나타나요.","5 살구색 — 얼굴이 나타나요.","6 노란색 — 그림의 바탕이 나타나요."],"title":"색칠 놀이 숫자와 색깔"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_basic#6','sci',3,2,'u4','L01','g3_2_sci_u4_L01_basic','lesson_basic','SC3-2-u4-C1',2,'mc','auto','그림 속 친구의 볼이 분홍색으로 붉어진 것을 보고 짐작할 수 있는 것은 무엇인가요?',ARRAY['SC3-2-u4-X02']::text[],false,'{"seq":6,"concept":"SC3-2-u4-C1","difficulty":2,"kind":"mc","stem":"그림 속 친구의 볼이 분홍색으로 붉어진 것을 보고 짐작할 수 있는 것은 무엇인가요?","options":[{"t":"열이 나는 것 같다","correct":true},{"t":"콧물을 흘린다","mis":"SC3-2-u4-X02"},{"t":"잠이 온다","mis":"SC3-2-u4-X02"},{"t":"배가 고프다","mis":"SC3-2-u4-X02"}],"explanation":["볼이 붉어졌어요.","얼굴이 달아올랐어요.","열이 나는 것 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_basic#7','sci',3,2,'u4','L01','g3_2_sci_u4_L01_basic','lesson_basic','SC3-2-u4-C2',2,'mc','auto','친구들의 경험에서 감기와 관련 없는 경험은 무엇인가요?',ARRAY['SC3-2-u4-X04']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C2","difficulty":2,"kind":"mc","stem":"친구들의 경험에서 감기와 관련 없는 경험은 무엇인가요?","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"SC3-2-u4-X04"},{"t":"㉡","mis":"SC3-2-u4-X04"},{"t":"㉣","mis":"SC3-2-u4-X04"}],"explanation":["하나씩 읽어요.","다친 일을 찾아요.","㉢이에요."],"asset":{"type":"passage","lines":["㉠ 동생에게서 감기가 옮아 가족이 모두 아팠어요.","㉡ 환절기에 감기에 걸려 콧물이 났어요.","㉢ 뛰다가 넘어져서 무릎을 다쳤어요.","㉣ 친구와 놀다가 감기가 옮았어요."],"title":"친구들의 경험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_basic#8','sci',3,2,'u4','L01','g3_2_sci_u4_L01_basic','lesson_basic','SC3-2-u4-C1',2,'mc','auto','먼저 다 칠한 친구가 해야 할 알맞은 행동은 무엇인가요?',ARRAY['SC3-2-u4-X03']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C1","difficulty":2,"kind":"mc","stem":"먼저 다 칠한 친구가 해야 할 알맞은 행동은 무엇인가요?","options":[{"t":"정답을 말하지 않고 다른 친구가 스스로 찾도록 기다린다","correct":true},{"t":"큰 소리로 정답을 외친다","mis":"SC3-2-u4-X03"},{"t":"친구 그림을 대신 칠해 준다","mis":"SC3-2-u4-X03"},{"t":"빨리 칠했다고 자랑한다","mis":"SC3-2-u4-X03"}],"explanation":["스스로 찾게 해요.","조용히 기다려요.","정답을 말하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_basic#9','sci',3,2,'u4','L01','g3_2_sci_u4_L01_basic','lesson_basic','SC3-2-u4-C1',2,'ox','auto','사인펜으로 칠하면 지우개로 쉽게 지울 수 있으니 숫자를 확인하지 않아도 돼요.',ARRAY['SC3-2-u4-X01']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C1","difficulty":2,"kind":"ox","stem":"사인펜으로 칠하면 지우개로 쉽게 지울 수 있으니 숫자를 확인하지 않아도 돼요.","answer":"X","reason_options":[{"t":"사인펜은 한 번 칠하면 고치기 어려워 숫자를 잘 확인하고 칠해야 하기 때문에","correct":true},{"t":"틀리면 언제든 쉽게 지울 수 있기 때문에","mis":"SC3-2-u4-X01"}],"mis":"SC3-2-u4-X01","explanation":["사인펜을 떠올려요.","고치기 어려워요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_basic#10','sci',3,2,'u4','L01','g3_2_sci_u4_L01_basic','lesson_basic','SC3-2-u4-C2',3,'mc','auto','친구들의 경험을 「다른 사람에게서 옮은 경험인가?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X04']::text[],false,'{"seq":10,"concept":"SC3-2-u4-C2","difficulty":3,"kind":"mc","stem":"친구들의 경험을 「다른 사람에게서 옮은 경험인가?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"㉠, ㉣","correct":true},{"t":"㉠, ㉡","mis":"SC3-2-u4-X04"},{"t":"㉡, ㉢","mis":"SC3-2-u4-X04"},{"t":"㉢, ㉣","mis":"SC3-2-u4-X04"}],"explanation":["옮았다는 말을 찾아요.","동생, 친구예요.","㉠, ㉣이에요."],"asset":{"type":"passage","lines":["㉠ 동생에게서 감기가 옮아 가족이 모두 아팠어요.","㉡ 환절기에 감기에 걸려 콧물이 났어요.","㉢ 뛰다가 넘어져서 무릎을 다쳤어요.","㉣ 친구와 놀다가 감기가 옮았어요."],"title":"친구들의 경험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_challenge#1','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C1',2,'match','auto','숫자와 칠할 색깔을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u4-C1","difficulty":2,"kind":"match","stem":"숫자와 칠할 색깔을 알맞게 이으세요.","pairs":[{"l":"숫자 1","r":"검은색"},{"l":"숫자 3","r":"분홍색"},{"l":"숫자 4","r":"하늘색"}],"mis":"SC3-2-u4-X01","explanation":["짝을 떠올려요.","4는 코 밑 줄이에요.","1-검은색, 3-분홍색, 4-하늘색이에요."],"asset":{"type":"passage","lines":["1 검은색 — 머리카락과 눈, 코, 입이 나타나요.","2 주황색 — 입 둘레가 나타나요.","3 분홍색 — 양쪽 볼이 나타나요.","4 하늘색 — 코 밑으로 줄이 나타나요.","5 살구색 — 얼굴이 나타나요.","6 노란색 — 그림의 바탕이 나타나요."],"title":"색칠 놀이 숫자와 색깔"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_challenge#2','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C2',2,'mc','auto','친구가 놀이터에 나오지 않은 까닭을 완성된 그림으로 짐작한 것은 무엇인가요?',ARRAY['SC3-2-u4-X02','SC3-2-u4-X04']::text[],false,'{"seq":2,"concept":"SC3-2-u4-C2","difficulty":2,"kind":"mc","stem":"친구가 놀이터에 나오지 않은 까닭을 완성된 그림으로 짐작한 것은 무엇인가요?","options":[{"t":"감기에 걸려 몸이 아팠다","correct":true},{"t":"이사를 갔다","mis":"SC3-2-u4-X02"},{"t":"숙제를 하고 있었다","mis":"SC3-2-u4-X02"},{"t":"약속을 잊어버렸다","mis":"SC3-2-u4-X04"}],"explanation":["그림 속 모습을 떠올려요.","콧물이 나고 열이 나요.","감기에 걸렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_challenge#3','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C1',3,'error','auto','색칠 놀이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u4-X03','SC3-2-u4-X01','SC3-2-u4-X02']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C1","difficulty":3,"kind":"error","stem":"색칠 놀이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「가장 빨리 칠한 사람이 이기는 놀이야.」","correct":true,"mis_target":"SC3-2-u4-X03"},{"t":"친구 가 — 「숫자를 확인하고 정해진 색으로 칠하자.」","mis":"SC3-2-u4-X01"},{"t":"친구 다 — 「다 칠하면 그림 속 친구의 상황을 짐작해 보자.」","mis":"SC3-2-u4-X02"}],"explanation":["놀이의 목적을 떠올려요.","빠르기가 중요할까요?","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_challenge#4','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C1',3,'mc','auto','그림 속 단서와 짐작한 내용을 바르게 이은 것은 무엇인가요?',ARRAY['SC3-2-u4-X02']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C1","difficulty":3,"kind":"mc","stem":"그림 속 단서와 짐작한 내용을 바르게 이은 것은 무엇인가요?","options":[{"t":"붉은 볼 — 열 · 코 밑 하늘색 줄 — 콧물","correct":true},{"t":"붉은 볼 — 콧물 · 코 밑 하늘색 줄 — 열","mis":"SC3-2-u4-X02"},{"t":"붉은 볼 — 잠 · 코 밑 하늘색 줄 — 웃음","mis":"SC3-2-u4-X02"},{"t":"두 단서 모두 아무 뜻이 없다","mis":"SC3-2-u4-X02"}],"explanation":["단서를 하나씩 봐요.","볼은 달아올랐어요.","볼-열, 줄-콧물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_challenge#5','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C2',3,'mc','auto','「감기와 관련된 경험인가?」로 나누었을 때 ✕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X04']::text[],false,'{"seq":5,"concept":"SC3-2-u4-C2","difficulty":3,"kind":"mc","stem":"「감기와 관련된 경험인가?」로 나누었을 때 ✕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"넘어져 무릎을 다친 일, 약속을 잊어 놀이터에 못 간 일","correct":true},{"t":"감기가 심해져 병원에 간 일, 넘어져 무릎을 다친 일","mis":"SC3-2-u4-X04"},{"t":"친구에게서 감기가 옮은 일, 약속을 잊은 일","mis":"SC3-2-u4-X04"},{"t":"환절기에 콧물이 난 일, 감기가 심해져 병원에 간 일","mis":"SC3-2-u4-X04"}],"explanation":["감기와 상관없는 것을 찾아요.","다친 일과 잊은 일이에요.","두 가지를 묶어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_challenge#6','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C2',3,'ox','auto','감기에 걸린 경험뿐 아니라 감기가 옮은 경험도 감기와 관련된 경험이에요.',ARRAY['SC3-2-u4-X04']::text[],false,'{"seq":6,"concept":"SC3-2-u4-C2","difficulty":3,"kind":"ox","stem":"감기에 걸린 경험뿐 아니라 감기가 옮은 경험도 감기와 관련된 경험이에요.","answer":"O","reason_options":[{"t":"걸린 일도 옮은 일도 모두 감기와 관련 있기 때문에","correct":true},{"t":"내가 아팠던 일만 감기 경험이기 때문에","mis":"SC3-2-u4-X04"}],"mis":"SC3-2-u4-X04","explanation":["두 경험을 견줘요.","둘 다 감기예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_challenge#7','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C1',3,'mc','auto','색칠 놀이 숫자와 색깔에서 친구의 얼굴과 그림의 바탕을 칠하는 숫자를 차례대로 쓴 것은 무엇인가요?',ARRAY['SC3-2-u4-X01']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C1","difficulty":3,"kind":"mc","stem":"색칠 놀이 숫자와 색깔에서 친구의 얼굴과 그림의 바탕을 칠하는 숫자를 차례대로 쓴 것은 무엇인가요?","options":[{"t":"5, 6","correct":true},{"t":"6, 5","mis":"SC3-2-u4-X01"},{"t":"1, 2","mis":"SC3-2-u4-X01"},{"t":"3, 4","mis":"SC3-2-u4-X01"}],"explanation":["얼굴과 바탕을 찾아요.","살구색과 노란색이에요.","5, 6이에요."],"asset":{"type":"passage","lines":["1 검은색 — 머리카락과 눈, 코, 입이 나타나요.","2 주황색 — 입 둘레가 나타나요.","3 분홍색 — 양쪽 볼이 나타나요.","4 하늘색 — 코 밑으로 줄이 나타나요.","5 살구색 — 얼굴이 나타나요.","6 노란색 — 그림의 바탕이 나타나요."],"title":"색칠 놀이 숫자와 색깔"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_challenge#8','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C2',4,'mc','auto','친구가 「나는 감기 경험이 없어서 이야기할 게 없어.」라고 했어요. 가장 알맞게 도와준 말은 무엇인가요?',ARRAY['SC3-2-u4-X04','SC3-2-u4-X03']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C2","difficulty":4,"kind":"mc","stem":"친구가 「나는 감기 경험이 없어서 이야기할 게 없어.」라고 했어요. 가장 알맞게 도와준 말은 무엇인가요?","options":[{"t":"「가족이나 친구가 감기에 걸렸던 일, 감기가 옮았던 일도 이야기할 수 있어.」","correct":true},{"t":"「넘어져 다친 일을 감기 경험이라고 말하면 돼.」","mis":"SC3-2-u4-X04"},{"t":"「감기는 옮지 않으니 아무 경험이나 말해.」","mis":"SC3-2-u4-X04"},{"t":"「경험은 말하지 말고 그림만 빨리 칠하자.」","mis":"SC3-2-u4-X03"}],"explanation":["감기와 관련된 일을 떠올려요.","옮은 일도 돼요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_challenge#9','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C1',4,'mc','auto','친구 그림의 코 밑이 하늘색이 아니라 노란색으로 칠해졌어요. 그 까닭과 다음에 할 일로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X01','SC3-2-u4-X02','SC3-2-u4-X03']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C1","difficulty":4,"kind":"mc","stem":"친구 그림의 코 밑이 하늘색이 아니라 노란색으로 칠해졌어요. 그 까닭과 다음에 할 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"숫자 4 대신 6의 색으로 칠했으니, 다음에는 칸의 숫자를 확인하고 칠한다","correct":true},{"t":"노란색이 더 예쁘니 그대로 두면 된다","mis":"SC3-2-u4-X01"},{"t":"콧물이 노란색이라서 맞게 칠한 것이다","mis":"SC3-2-u4-X02"},{"t":"먼저 끝낸 친구가 정답을 알려 주면 된다","mis":"SC3-2-u4-X03"}],"explanation":["4는 무슨 색일까요?","노란색은 6이에요.","숫자를 확인해요."],"asset":{"type":"passage","lines":["1 검은색 — 머리카락과 눈, 코, 입이 나타나요.","2 주황색 — 입 둘레가 나타나요.","3 분홍색 — 양쪽 볼이 나타나요.","4 하늘색 — 코 밑으로 줄이 나타나요.","5 살구색 — 얼굴이 나타나요.","6 노란색 — 그림의 바탕이 나타나요."],"title":"색칠 놀이 숫자와 색깔"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L01_challenge#10','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C1',4,'essay','teacher','색칠 놀이로 완성한 그림에서 찾은 단서 두 가지를 쓰고, 친구가 놀이터에 나오지 못한 까닭을 짐작해 쓰세요. 그리고 색칠 놀이에서 지킬 약속을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u4-C1","difficulty":4,"kind":"essay","stem":"색칠 놀이로 완성한 그림에서 찾은 단서 두 가지를 쓰고, 친구가 놀이터에 나오지 못한 까닭을 짐작해 쓰세요. 그리고 색칠 놀이에서 지킬 약속을 한 가지 쓰세요.","answer_guide":{"answer":"예: 양쪽 볼이 분홍색으로 붉어져 열이 나는 것 같고, 코 밑에 하늘색 줄이 있어 콧물을 흘리는 것 같다. 그래서 친구는 감기에 걸려 몸이 아파 놀이터에 나오지 못했을 것이다. 먼저 다 칠해도 정답을 말하지 않고 친구가 스스로 찾도록 기다린다.","scoring_points":["그림 속 단서 두 가지를 썼는가","단서를 바탕으로 친구의 상황을 짐작했는가","색칠 놀이 약속을 썼는가"]},"explanation":["그림을 떠올려요.","단서를 써요.","약속을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_basic#1','sci',3,2,'u4','L02','g3_2_sci_u4_L02_basic','lesson_basic','SC3-2-u4-C3',1,'mc','auto','병원체에 감염되어 생기는 질병을 무엇이라고 하나요?',ARRAY['SC3-2-u4-X05','SC3-2-u4-X10']::text[],false,'{"seq":1,"concept":"SC3-2-u4-C3","difficulty":1,"kind":"mc","stem":"병원체에 감염되어 생기는 질병을 무엇이라고 하나요?","options":[{"t":"감염병","correct":true},{"t":"상처","mis":"SC3-2-u4-X05"},{"t":"골절","mis":"SC3-2-u4-X10"},{"t":"화상","mis":"SC3-2-u4-X10"}],"explanation":["감기, 독감을 묶어요.","감염되어 생겨요.","감염병이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_basic#2','sci',3,2,'u4','L02','g3_2_sci_u4_L02_basic','lesson_basic','SC3-2-u4-C3',1,'sa','auto','병의 원인이 되는 본체로 세균, 바이러스 등을 말하는 것을 「○○○」라고 해요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u4-C3","difficulty":1,"kind":"sa","stem":"병의 원인이 되는 본체로 세균, 바이러스 등을 말하는 것을 「○○○」라고 해요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["병원체"],"explanation":["병을 일으켜요.","병◯◯예요.","병원체예요."],"mis":"SC3-2-u4-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_basic#3','sci',3,2,'u4','L02','g3_2_sci_u4_L02_basic','lesson_basic','SC3-2-u4-C4',1,'ox','auto','독감은 생활 속에서 걸릴 수 있는 감염병이에요.',ARRAY['SC3-2-u4-X07']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C4","difficulty":1,"kind":"ox","stem":"독감은 생활 속에서 걸릴 수 있는 감염병이에요.","answer":"O","reason_options":[{"t":"병원체에 감염되어 생기는 질병이기 때문에","correct":true},{"t":"다쳐서 생기는 병이기 때문에","mis":"SC3-2-u4-X07"}],"mis":"SC3-2-u4-X07","explanation":["돌림판을 떠올려요.","겨울에 걸린 친구가 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_basic#4','sci',3,2,'u4','L02','g3_2_sci_u4_L02_basic','lesson_basic','SC3-2-u4-C5',1,'mc','auto','감염병이 아닌 것은 무엇인가요?',ARRAY['SC3-2-u4-X10']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C5","difficulty":1,"kind":"mc","stem":"감염병이 아닌 것은 무엇인가요?","options":[{"t":"뜨거운 물에 손을 데었다","correct":true},{"t":"독감에 걸렸다","mis":"SC3-2-u4-X10"},{"t":"수두에 걸렸다","mis":"SC3-2-u4-X10"},{"t":"감기에 걸렸다","mis":"SC3-2-u4-X10"}],"explanation":["감염되어 생긴 것을 빼요.","데인 것은 다친 거예요.","데인 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_basic#5','sci',3,2,'u4','L02','g3_2_sci_u4_L02_basic','lesson_basic','SC3-2-u4-C4',2,'mc','auto','돌림판 경험 모음에서 감염병과 관련된 경험끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X10']::text[],false,'{"seq":5,"concept":"SC3-2-u4-C4","difficulty":2,"kind":"mc","stem":"돌림판 경험 모음에서 감염병과 관련된 경험끼리 묶은 것은 무엇인가요?","options":[{"t":"㉠, ㉡, ㉣","correct":true},{"t":"㉠, ㉢, ㉤","mis":"SC3-2-u4-X10"},{"t":"㉡, ㉢, ㉣","mis":"SC3-2-u4-X10"},{"t":"㉢, ㉣, ㉤","mis":"SC3-2-u4-X10"}],"explanation":["하나씩 읽어요.","부러진 뼈와 꽃가루는 빼요.","㉠, ㉡, ㉣이에요."],"asset":{"type":"passage","lines":["㉠ 감기에 걸린 친구와 놀다가 나도 감기에 걸렸어요.","㉡ 올해는 독감 예방접종을 했어요.","㉢ 계단에서 넘어져 뼈가 부러졌어요.","㉣ 물놀이를 한 뒤에 유행성 눈병에 걸렸어요.","㉤ 꽃가루 때문에 재채기가 나왔어요."],"title":"돌림판 경험 모음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_basic#6','sci',3,2,'u4','L02','g3_2_sci_u4_L02_basic','lesson_basic','SC3-2-u4-C4',2,'mc','auto','「감기가 심해지면 독감이 될까요?」에 대한 알맞은 답은 무엇인가요?',ARRAY['SC3-2-u4-X08','SC3-2-u4-X07']::text[],false,'{"seq":6,"concept":"SC3-2-u4-C4","difficulty":2,"kind":"mc","stem":"「감기가 심해지면 독감이 될까요?」에 대한 알맞은 답은 무엇인가요?","options":[{"t":"아니다, 감기와 독감은 서로 다른 질병이다","correct":true},{"t":"그렇다, 감기가 심해지면 독감이 된다","mis":"SC3-2-u4-X08"},{"t":"그렇다, 독감이 나으면 감기가 된다","mis":"SC3-2-u4-X08"},{"t":"아니다, 독감은 감염병이 아니다","mis":"SC3-2-u4-X07"}],"explanation":["두 질병을 견줘요.","서로 달라요.","다른 질병이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_basic#7','sci',3,2,'u4','L02','g3_2_sci_u4_L02_basic','lesson_basic','SC3-2-u4-C4',2,'match','auto','경험과 감염병을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC3-2-u4-C4","difficulty":2,"kind":"match","stem":"경험과 감염병을 알맞게 이으세요.","pairs":[{"l":"전 세계에 유행했어요","r":"코로나바이러스감염증-19"},{"l":"예방접종을 하고 겨울을 보냈어요","r":"독감"},{"l":"물놀이 뒤에 눈병이 났어요","r":"유행성 눈병"}],"mis":"SC3-2-u4-X09","explanation":["돌림판 경험을 떠올려요.","눈병은 눈이에요.","세계-코로나19, 겨울-독감, 물놀이-눈병이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_basic#8','sci',3,2,'u4','L02','g3_2_sci_u4_L02_basic','lesson_basic','SC3-2-u4-C4',2,'ox','auto','예방접종을 한 경험은 감염병과 관련 없는 경험이에요.',ARRAY['SC3-2-u4-X09']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C4","difficulty":2,"kind":"ox","stem":"예방접종을 한 경험은 감염병과 관련 없는 경험이에요.","answer":"X","reason_options":[{"t":"예방접종은 감염병을 막으려고 하는 것이라 감염병과 관련된 경험이기 때문에","correct":true},{"t":"아프지 않았으니 감염병과 상관없기 때문에","mis":"SC3-2-u4-X09"}],"mis":"SC3-2-u4-X09","explanation":["예방접종을 왜 할까요?","감염병을 막아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_basic#9','sci',3,2,'u4','L02','g3_2_sci_u4_L02_basic','lesson_basic','SC3-2-u4-C5',2,'mc','auto','계단에서 넘어져 뼈가 부러진 것이 감염병이 아닌 까닭은 무엇인가요?',ARRAY['SC3-2-u4-X10','SC3-2-u4-X05']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C5","difficulty":2,"kind":"mc","stem":"계단에서 넘어져 뼈가 부러진 것이 감염병이 아닌 까닭은 무엇인가요?","options":[{"t":"병원체에 감염되어 생긴 질병이 아니어서","correct":true},{"t":"많이 아프지 않아서","mis":"SC3-2-u4-X10"},{"t":"어른만 걸려서","mis":"SC3-2-u4-X05"},{"t":"병원에 가지 않아서","mis":"SC3-2-u4-X10"}],"explanation":["감염병의 뜻을 떠올려요.","감염되어야 해요.","병원체 때문이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_basic#10','sci',3,2,'u4','L02','g3_2_sci_u4_L02_basic','lesson_basic','SC3-2-u4-C3',3,'mc','auto','감기, 독감, 수두를 한 낱말로 묶을 수 있는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X05','SC3-2-u4-X06','SC3-2-u4-X07']::text[],false,'{"seq":10,"concept":"SC3-2-u4-C3","difficulty":3,"kind":"mc","stem":"감기, 독감, 수두를 한 낱말로 묶을 수 있는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"모두 병원체에 감염되어 생기는 질병이라서","correct":true},{"t":"모두 다쳐서 생기는 병이라서","mis":"SC3-2-u4-X05"},{"t":"모두 햇빛 때문에 생기는 병이라서","mis":"SC3-2-u4-X06"},{"t":"모두 옛날에만 있던 병이라서","mis":"SC3-2-u4-X07"}],"explanation":["공통점을 찾아요.","감염되어 생겨요.","감염병이라서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_challenge#1','sci',3,2,'u4','L02','g3_2_sci_u4_L02_challenge','lesson_challenge','SC3-2-u4-C4',2,'sa','auto','돌림판 경험 모음 ㉣에서 물놀이를 한 뒤에 걸린 감염병의 이름을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u4-C4","difficulty":2,"kind":"sa","stem":"돌림판 경험 모음 ㉣에서 물놀이를 한 뒤에 걸린 감염병의 이름을 쓰세요.","answer":["유행성 눈병","유행성눈병"],"explanation":["㉣을 읽어요.","눈에 생겨요.","유행성 눈병이에요."],"asset":{"type":"passage","lines":["㉠ 감기에 걸린 친구와 놀다가 나도 감기에 걸렸어요.","㉡ 올해는 독감 예방접종을 했어요.","㉢ 계단에서 넘어져 뼈가 부러졌어요.","㉣ 물놀이를 한 뒤에 유행성 눈병에 걸렸어요.","㉤ 꽃가루 때문에 재채기가 나왔어요."],"title":"돌림판 경험 모음"},"mis":"SC3-2-u4-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_challenge#2','sci',3,2,'u4','L02','g3_2_sci_u4_L02_challenge','lesson_challenge','SC3-2-u4-C5',2,'mc','auto','돌림판 경험 모음에서 감염병이 아닌 경험끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X10','SC3-2-u4-X09']::text[],false,'{"seq":2,"concept":"SC3-2-u4-C5","difficulty":2,"kind":"mc","stem":"돌림판 경험 모음에서 감염병이 아닌 경험끼리 묶은 것은 무엇인가요?","options":[{"t":"㉢, ㉤","correct":true},{"t":"㉠, ㉢","mis":"SC3-2-u4-X10"},{"t":"㉡, ㉤","mis":"SC3-2-u4-X09"},{"t":"㉣, ㉤","mis":"SC3-2-u4-X10"}],"explanation":["감염되어 생긴 것인지 봐요.","뼈와 꽃가루예요.","㉢, ㉤이에요."],"asset":{"type":"passage","lines":["㉠ 감기에 걸린 친구와 놀다가 나도 감기에 걸렸어요.","㉡ 올해는 독감 예방접종을 했어요.","㉢ 계단에서 넘어져 뼈가 부러졌어요.","㉣ 물놀이를 한 뒤에 유행성 눈병에 걸렸어요.","㉤ 꽃가루 때문에 재채기가 나왔어요."],"title":"돌림판 경험 모음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_challenge#3','sci',3,2,'u4','L02','g3_2_sci_u4_L02_challenge','lesson_challenge','SC3-2-u4-C4',3,'error','auto','감염병을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u4-X08','SC3-2-u4-X07','SC3-2-u4-X10']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C4","difficulty":3,"kind":"error","stem":"감염병을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「감기가 심해지면 독감이 되는 거야.」","correct":true,"mis_target":"SC3-2-u4-X08"},{"t":"친구 가 — 「수족구병은 동생에게서 옮기도 해.」","mis":"SC3-2-u4-X07"},{"t":"친구 나 — 「꽃가루 때문에 나온 재채기는 감염병이 아니야.」","mis":"SC3-2-u4-X10"}],"explanation":["감기와 독감을 떠올려요.","서로 다른 질병이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_challenge#4','sci',3,2,'u4','L02','g3_2_sci_u4_L02_challenge','lesson_challenge','SC3-2-u4-C4',3,'mc','auto','돌림판 경험 모음을 「걸렸던 경험인가, 예방접종 경험인가?」로 나눌 때 예방접종 경험은 무엇인가요?',ARRAY['SC3-2-u4-X09','SC3-2-u4-X10']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C4","difficulty":3,"kind":"mc","stem":"돌림판 경험 모음을 「걸렸던 경험인가, 예방접종 경험인가?」로 나눌 때 예방접종 경험은 무엇인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"SC3-2-u4-X09"},{"t":"㉣","mis":"SC3-2-u4-X09"},{"t":"㉤","mis":"SC3-2-u4-X10"}],"explanation":["주사를 맞은 일을 찾아요.","독감을 막으려 했어요.","㉡이에요."],"asset":{"type":"passage","lines":["㉠ 감기에 걸린 친구와 놀다가 나도 감기에 걸렸어요.","㉡ 올해는 독감 예방접종을 했어요.","㉢ 계단에서 넘어져 뼈가 부러졌어요.","㉣ 물놀이를 한 뒤에 유행성 눈병에 걸렸어요.","㉤ 꽃가루 때문에 재채기가 나왔어요."],"title":"돌림판 경험 모음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_challenge#5','sci',3,2,'u4','L02','g3_2_sci_u4_L02_challenge','lesson_challenge','SC3-2-u4-C3',3,'mc','auto','감염병과 병원체에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC3-2-u4-X06','SC3-2-u4-X05','SC3-2-u4-X10']::text[],false,'{"seq":5,"concept":"SC3-2-u4-C3","difficulty":3,"kind":"mc","stem":"감염병과 병원체에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"병원체는 세균, 바이러스 등이고, 병원체에 감염되어 생기는 질병이 감염병이다","correct":true},{"t":"병원체는 햇빛이고, 햇볕에 타서 생기는 질병이 감염병이다","mis":"SC3-2-u4-X06"},{"t":"병원체는 상처이고, 다쳐서 생기는 질병이 감염병이다","mis":"SC3-2-u4-X05"},{"t":"병원체는 꽃가루이고, 재채기가 나면 모두 감염병이다","mis":"SC3-2-u4-X10"}],"explanation":["병원체를 떠올려요.","세균, 바이러스예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_challenge#6','sci',3,2,'u4','L02','g3_2_sci_u4_L02_challenge','lesson_challenge','SC3-2-u4-C7',3,'mc','auto','생활 속 감염병의 예로만 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X10']::text[],false,'{"seq":6,"concept":"SC3-2-u4-C7","difficulty":3,"kind":"mc","stem":"생활 속 감염병의 예로만 묶은 것은 무엇인가요?","options":[{"t":"감기, 수족구병, 수두","correct":true},{"t":"감기, 골절, 수두","mis":"SC3-2-u4-X10"},{"t":"독감, 화상, 수족구병","mis":"SC3-2-u4-X10"},{"t":"꽃가루 재채기, 독감, 감기","mis":"SC3-2-u4-X10"}],"explanation":["다친 것은 빼요.","감염되어 생긴 것만요.","감기, 수족구병, 수두예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_challenge#7','sci',3,2,'u4','L02','g3_2_sci_u4_L02_challenge','lesson_challenge','SC3-2-u4-C4',3,'ox','auto','감염병은 옛날에만 있었고 지금 우리 주변에서는 걸리지 않아요.',ARRAY['SC3-2-u4-X07']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C4","difficulty":3,"kind":"ox","stem":"감염병은 옛날에만 있었고 지금 우리 주변에서는 걸리지 않아요.","answer":"X","reason_options":[{"t":"감기, 독감, 유행성 눈병처럼 지금도 생활 속에서 걸리는 감염병이 많기 때문에","correct":true},{"t":"요즘에는 병원체가 모두 사라졌기 때문에","mis":"SC3-2-u4-X07"}],"mis":"SC3-2-u4-X07","explanation":["돌림판 경험을 떠올려요.","지난겨울에도 걸렸어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_challenge#8','sci',3,2,'u4','L02','g3_2_sci_u4_L02_challenge','lesson_challenge','SC3-2-u4-C5',4,'mc','auto','친구가 「축구하다 발목을 삐었으니 나는 감염병에 걸린 거야.」라고 말했어요. 바르게 고친 말로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X10','SC3-2-u4-X05']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C5","difficulty":4,"kind":"mc","stem":"친구가 「축구하다 발목을 삐었으니 나는 감염병에 걸린 거야.」라고 말했어요. 바르게 고친 말로 알맞은 것은 무엇인가요?","options":[{"t":"「발목을 삔 것은 다친 거라서, 병원체에 감염되어 생기는 감염병이 아니야.」","correct":true},{"t":"「발목이 많이 아프면 감염병이야.」","mis":"SC3-2-u4-X10"},{"t":"「축구를 했으니 감염병이 맞아.」","mis":"SC3-2-u4-X05"},{"t":"「병원에 가면 감염병이 되는 거야.」","mis":"SC3-2-u4-X05"}],"explanation":["감염병의 뜻을 떠올려요.","삔 것은 다친 거예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_challenge#9','sci',3,2,'u4','L02','g3_2_sci_u4_L02_challenge','lesson_challenge','SC3-2-u4-C4',4,'mc','auto','감기와 독감에 대해 바르게 정리한 것은 무엇인가요?',ARRAY['SC3-2-u4-X08','SC3-2-u4-X07','SC3-2-u4-X09']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C4","difficulty":4,"kind":"mc","stem":"감기와 독감에 대해 바르게 정리한 것은 무엇인가요?","options":[{"t":"둘은 서로 다른 감염병이고, 독감은 주로 겨울철에 걸리며 예방접종으로 어느 정도 예방할 수 있다","correct":true},{"t":"독감은 감기가 심해진 것이라 따로 예방할 수 없다","mis":"SC3-2-u4-X08"},{"t":"감기만 감염병이고 독감은 감염병이 아니다","mis":"SC3-2-u4-X07"},{"t":"독감 예방접종은 감염병과 관련 없는 경험이다","mis":"SC3-2-u4-X09"}],"explanation":["두 질병을 견줘요.","독감에는 예방접종이 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L02_challenge#10','sci',3,2,'u4','L02','g3_2_sci_u4_L02_challenge','lesson_challenge','SC3-2-u4-C3',4,'essay','teacher','감염병의 뜻을 병원체와 이어 쓰고, 생활 속 감염병의 예 두 가지와 감염병이 아닌 예 한 가지를 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u4-C3","difficulty":4,"kind":"essay","stem":"감염병의 뜻을 병원체와 이어 쓰고, 생활 속 감염병의 예 두 가지와 감염병이 아닌 예 한 가지를 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 감염병은 세균, 바이러스 같은 병원체에 감염되어 생기는 질병이다. 감기와 독감은 생활 속 감염병의 예이다. 뜨거운 물에 손을 덴 것은 병원체에 감염되어 생긴 것이 아니라서 감염병이 아니다.","scoring_points":["감염병의 뜻을 병원체와 이어 썼는가","생활 속 감염병의 예 두 가지를 썼는가","감염병이 아닌 예를 까닭과 함께 썼는가"]},"explanation":["뜻부터 써요.","예를 두 가지 써요.","아닌 예도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_basic#1','sci',3,2,'u4','L03','g3_2_sci_u4_L03_basic','lesson_basic','SC3-2-u4-C6',1,'mc','auto','병을 앓을 때 나타나는 여러 가지 상태나 모양을 무엇이라고 하나요?',ARRAY['SC3-2-u4-X11','SC3-2-u4-X12']::text[],false,'{"seq":1,"concept":"SC3-2-u4-C6","difficulty":1,"kind":"mc","stem":"병을 앓을 때 나타나는 여러 가지 상태나 모양을 무엇이라고 하나요?","options":[{"t":"증상","correct":true},{"t":"특징","mis":"SC3-2-u4-X11"},{"t":"출처","mis":"SC3-2-u4-X12"},{"t":"이름","mis":"SC3-2-u4-X11"}],"explanation":["감염병 카드 칸이에요.","앓을 때 나타나요.","증상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_basic#2','sci',3,2,'u4','L03','g3_2_sci_u4_L03_basic','lesson_basic','SC3-2-u4-C6',1,'sa','auto','어느 모둠의 감염병 카드에서 이 카드가 조사한 감염병의 이름을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u4-C6","difficulty":1,"kind":"sa","stem":"어느 모둠의 감염병 카드에서 이 카드가 조사한 감염병의 이름을 쓰세요.","answer":["유행성 눈병","유행성눈병"],"explanation":["이름 칸을 읽어요.","눈과 관련 있어요.","유행성 눈병이에요."],"asset":{"type":"passage","lines":["이름 — 유행성 눈병","㉠ — 눈이 충혈되고 간지럽고 부어요.","㉡ — 덥고 습한 여름철에 잘 걸려요.","출처 — 믿을 수 있는 누리집의 최신 자료"],"title":"어느 모둠의 감염병 카드"},"mis":"SC3-2-u4-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_basic#3','sci',3,2,'u4','L03','g3_2_sci_u4_L03_basic','lesson_basic','SC3-2-u4-C7',1,'ox','auto','감염병은 누구나 걸릴 수 있어요.',ARRAY['SC3-2-u4-X13']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C7","difficulty":1,"kind":"ox","stem":"감염병은 누구나 걸릴 수 있어요.","answer":"O","reason_options":[{"t":"감염병은 나이나 사람을 가리지 않고 걸릴 수 있기 때문에","correct":true},{"t":"어른만 걸리고 어린이는 걸리지 않기 때문에","mis":"SC3-2-u4-X13"}],"mis":"SC3-2-u4-X13","explanation":["위험성을 떠올려요.","누구나 걸려요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_basic#4','sci',3,2,'u4','L03','g3_2_sci_u4_L03_basic','lesson_basic','SC3-2-u4-C7',1,'mc','auto','사람들이 예방접종을 하는 까닭은 무엇인가요?',ARRAY['SC3-2-u4-X13']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C7","difficulty":1,"kind":"mc","stem":"사람들이 예방접종을 하는 까닭은 무엇인가요?","options":[{"t":"감염병으로부터 몸을 보호하려고","correct":true},{"t":"주사가 재미있어서","mis":"SC3-2-u4-X13"},{"t":"키가 크려고","mis":"SC3-2-u4-X13"},{"t":"학교에 늦게 가려고","mis":"SC3-2-u4-X13"}],"explanation":["감염병은 위험해요.","미리 준비해요.","몸을 보호하려고요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_basic#5','sci',3,2,'u4','L03','g3_2_sci_u4_L03_basic','lesson_basic','SC3-2-u4-C6',2,'mc','auto','어느 모둠의 감염병 카드에서 ㉠과 ㉡에 알맞은 칸 이름을 차례대로 쓴 것은 무엇인가요?',ARRAY['SC3-2-u4-X11','SC3-2-u4-X12']::text[],false,'{"seq":5,"concept":"SC3-2-u4-C6","difficulty":2,"kind":"mc","stem":"어느 모둠의 감염병 카드에서 ㉠과 ㉡에 알맞은 칸 이름을 차례대로 쓴 것은 무엇인가요?","options":[{"t":"증상, 특징","correct":true},{"t":"특징, 증상","mis":"SC3-2-u4-X11"},{"t":"이름, 출처","mis":"SC3-2-u4-X11"},{"t":"출처, 증상","mis":"SC3-2-u4-X12"}],"explanation":["㉠은 눈의 상태예요.","㉡은 언제 잘 걸리는지예요.","증상, 특징이에요."],"asset":{"type":"passage","lines":["이름 — 유행성 눈병","㉠ — 눈이 충혈되고 간지럽고 부어요.","㉡ — 덥고 습한 여름철에 잘 걸려요.","출처 — 믿을 수 있는 누리집의 최신 자료"],"title":"어느 모둠의 감염병 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_basic#6','sci',3,2,'u4','L03','g3_2_sci_u4_L03_basic','lesson_basic','SC3-2-u4-C6',2,'mc','auto','감염병을 조사할 때 알맞은 방법은 무엇인가요?',ARRAY['SC3-2-u4-X12']::text[],false,'{"seq":6,"concept":"SC3-2-u4-C6","difficulty":2,"kind":"mc","stem":"감염병을 조사할 때 알맞은 방법은 무엇인가요?","options":[{"t":"믿을 수 있는 곳에서 최신 자료를 찾고 출처를 밝힌다","correct":true},{"t":"아무 글이나 그대로 옮겨 쓴다","mis":"SC3-2-u4-X12"},{"t":"출처는 쓰지 않는다","mis":"SC3-2-u4-X12"},{"t":"오래된 자료만 고른다","mis":"SC3-2-u4-X12"}],"explanation":["올바른 정보인지 확인해요.","어디서 찾았는지 밝혀요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_basic#7','sci',3,2,'u4','L03','g3_2_sci_u4_L03_basic','lesson_basic','SC3-2-u4-C7',2,'mc','auto','감염병이 위험한 까닭 토의에서 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u4-X13']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C7","difficulty":2,"kind":"mc","stem":"감염병이 위험한 까닭 토의에서 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다","correct":true},{"t":"친구 가","mis":"SC3-2-u4-X13"},{"t":"친구 나","mis":"SC3-2-u4-X13"},{"t":"친구 라","mis":"SC3-2-u4-X13"}],"explanation":["네 의견을 읽어요.","증상이 다양하면 괜찮을까요?","친구 다예요."],"asset":{"type":"passage","lines":["친구 가 — 「여러 증상이 나타나 몸이 아파요.」","친구 나 — 「다른 사람에게 옮아 많은 사람이 걸려요.」","친구 다 — 「증상이 다양하니까 괜찮아요.」","친구 라 — 「치료 뒤에도 증상이 오래 남기도 해요.」"],"title":"감염병이 위험한 까닭 토의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_basic#8','sci',3,2,'u4','L03','g3_2_sci_u4_L03_basic','lesson_basic','SC3-2-u4-C7',2,'mc','auto','토의할 때 좋은 태도는 무엇인가요?',ARRAY['SC3-2-u4-X15']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C7","difficulty":2,"kind":"mc","stem":"토의할 때 좋은 태도는 무엇인가요?","options":[{"t":"친구 말을 끝까지 듣는다","correct":true},{"t":"친구 의견을 비웃는다","mis":"SC3-2-u4-X15"},{"t":"내 생각만 옳다고 우긴다","mis":"SC3-2-u4-X15"},{"t":"친구가 말할 때 끼어든다","mis":"SC3-2-u4-X15"}],"explanation":["서로 존중해요.","끝까지 들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_basic#9','sci',3,2,'u4','L03','g3_2_sci_u4_L03_basic','lesson_basic','SC3-2-u4-C7',2,'ox','auto','감염병 공부에서는 감염병 카드의 증상을 모두 외우는 것이 가장 중요해요.',ARRAY['SC3-2-u4-X14']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C7","difficulty":2,"kind":"ox","stem":"감염병 공부에서는 감염병 카드의 증상을 모두 외우는 것이 가장 중요해요.","answer":"X","reason_options":[{"t":"증상을 외우기보다 조사한 내용으로 위험한 까닭을 이야기하는 것이 중요하기 때문에","correct":true},{"t":"증상을 외워야만 토의할 수 있기 때문에","mis":"SC3-2-u4-X14"}],"mis":"SC3-2-u4-X14","explanation":["오늘 활동을 떠올려요.","외우기보다 토의예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_basic#10','sci',3,2,'u4','L03','g3_2_sci_u4_L03_basic','lesson_basic','SC3-2-u4-C7',3,'mc','auto','감염병이 위험한 까닭으로 알맞지 않은 것은 무엇인가요?',ARRAY['SC3-2-u4-X13']::text[],false,'{"seq":10,"concept":"SC3-2-u4-C7","difficulty":3,"kind":"mc","stem":"감염병이 위험한 까닭으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"아무에게도 옮지 않아서","correct":true},{"t":"다양한 증상이 나타나 몸이 아파서","mis":"SC3-2-u4-X13"},{"t":"많은 사람이 걸릴 수 있어서","mis":"SC3-2-u4-X13"},{"t":"치료 뒤에도 증상이 오래 남을 수 있어서","mis":"SC3-2-u4-X13"}],"explanation":["세 가지 위험성을 떠올려요.","옮지 않는다면?","「아무에게도 옮지 않아서」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_challenge#1','sci',3,2,'u4','L03','g3_2_sci_u4_L03_challenge','lesson_challenge','SC3-2-u4-C6',2,'match','auto','감염병과 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u4-C6","difficulty":2,"kind":"match","stem":"감염병과 특징을 알맞게 이으세요.","pairs":[{"l":"독감","r":"예방접종이 있어요"},{"l":"유행성 눈병","r":"덥고 습한 여름철에 잘 걸려요"},{"l":"코로나바이러스감염증-19","r":"전 세계에서 유행했어요"}],"mis":"SC3-2-u4-X11","explanation":["감염병 카드를 떠올려요.","여름철은 눈병이에요.","독감-예방접종, 눈병-여름철, 코로나19-전 세계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_challenge#2','sci',3,2,'u4','L03','g3_2_sci_u4_L03_challenge','lesson_challenge','SC3-2-u4-C7',2,'mc','auto','친구가 나와 다른 의견을 말했을 때 알맞은 행동은 무엇인가요?',ARRAY['SC3-2-u4-X15']::text[],false,'{"seq":2,"concept":"SC3-2-u4-C7","difficulty":2,"kind":"mc","stem":"친구가 나와 다른 의견을 말했을 때 알맞은 행동은 무엇인가요?","options":[{"t":"끝까지 듣고 조사한 내용을 바탕으로 내 생각을 말한다","correct":true},{"t":"그런 생각은 이상하다고 비웃는다","mis":"SC3-2-u4-X15"},{"t":"내 말만 계속 되풀이한다","mis":"SC3-2-u4-X15"},{"t":"친구 말을 막고 끼어든다","mis":"SC3-2-u4-X15"}],"explanation":["의견을 존중해요.","근거를 들어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_challenge#3','sci',3,2,'u4','L03','g3_2_sci_u4_L03_challenge','lesson_challenge','SC3-2-u4-C7',3,'error','auto','감염병이 위험한 까닭 토의를 두고 친구들이 정리했어요. 잘못 정리한 친구는 누구인가요?',ARRAY['SC3-2-u4-X13','SC3-2-u4-X14']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C7","difficulty":3,"kind":"error","stem":"감염병이 위험한 까닭 토의를 두고 친구들이 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"친구 나 — 「친구 다처럼 증상이 다양하면 위험하지 않아.」","correct":true,"mis_target":"SC3-2-u4-X13"},{"t":"친구 가 — 「널리 유행하면 수많은 사람이 피해를 입을 수 있어.」","mis":"SC3-2-u4-X13"},{"t":"친구 다 — 「증상을 외우기보다 위험한 까닭을 이야기하자.」","mis":"SC3-2-u4-X14"}],"explanation":["증상이 다양하다는 말을 봐요.","괜찮은 걸까요?","친구 나가 잘못 정리했어요."],"asset":{"type":"passage","lines":["친구 가 — 「여러 증상이 나타나 몸이 아파요.」","친구 나 — 「다른 사람에게 옮아 많은 사람이 걸려요.」","친구 다 — 「증상이 다양하니까 괜찮아요.」","친구 라 — 「치료 뒤에도 증상이 오래 남기도 해요.」"],"title":"감염병이 위험한 까닭 토의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_challenge#4','sci',3,2,'u4','L03','g3_2_sci_u4_L03_challenge','lesson_challenge','SC3-2-u4-C6',3,'mc','auto','「재채기, 코 막힘」, 「예방접종이 있어요」, 「눈이 충혈돼요」, 「여름철에 잘 걸려요」를 감염병 카드의 증상 칸에 넣을 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X11']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C6","difficulty":3,"kind":"mc","stem":"「재채기, 코 막힘」, 「예방접종이 있어요」, 「눈이 충혈돼요」, 「여름철에 잘 걸려요」를 감염병 카드의 증상 칸에 넣을 것끼리 묶은 것은 무엇인가요?","options":[{"t":"재채기·코 막힘, 눈이 충혈돼요","correct":true},{"t":"예방접종이 있어요, 여름철에 잘 걸려요","mis":"SC3-2-u4-X11"},{"t":"재채기·코 막힘, 여름철에 잘 걸려요","mis":"SC3-2-u4-X11"},{"t":"예방접종이 있어요, 눈이 충혈돼요","mis":"SC3-2-u4-X11"}],"explanation":["앓을 때 나타나는 상태예요.","언제 걸리는지는 특징이에요.","재채기·코 막힘과 충혈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_challenge#5','sci',3,2,'u4','L03','g3_2_sci_u4_L03_challenge','lesson_challenge','SC3-2-u4-C6',3,'mc','auto','어느 모둠의 감염병 카드에서 잘한 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X11','SC3-2-u4-X12']::text[],false,'{"seq":5,"concept":"SC3-2-u4-C6","difficulty":3,"kind":"mc","stem":"어느 모둠의 감염병 카드에서 잘한 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"믿을 수 있는 누리집의 최신 자료를 찾고 출처를 밝혔다","correct":true},{"t":"증상과 특징을 한 칸에 섞어 썼다","mis":"SC3-2-u4-X11"},{"t":"출처를 쓰지 않아 깔끔하게 했다","mis":"SC3-2-u4-X12"},{"t":"오래된 자료를 골라 그대로 옮겼다","mis":"SC3-2-u4-X12"}],"explanation":["출처 칸을 봐요.","최신 자료예요.","출처를 밝혔어요."],"asset":{"type":"passage","lines":["이름 — 유행성 눈병","㉠ — 눈이 충혈되고 간지럽고 부어요.","㉡ — 덥고 습한 여름철에 잘 걸려요.","출처 — 믿을 수 있는 누리집의 최신 자료"],"title":"어느 모둠의 감염병 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_challenge#6','sci',3,2,'u4','L03','g3_2_sci_u4_L03_challenge','lesson_challenge','SC3-2-u4-C7',3,'ox','auto','감염병은 널리 유행하면 수많은 사람이 피해를 입을 수 있어요.',ARRAY['SC3-2-u4-X13']::text[],false,'{"seq":6,"concept":"SC3-2-u4-C7","difficulty":3,"kind":"ox","stem":"감염병은 널리 유행하면 수많은 사람이 피해를 입을 수 있어요.","answer":"O","reason_options":[{"t":"다른 사람에게 옮아 많은 사람이 걸릴 수 있기 때문에","correct":true},{"t":"감염병은 한 사람에게만 생기고 끝나기 때문에","mis":"SC3-2-u4-X13"}],"mis":"SC3-2-u4-X13","explanation":["옮는 것을 떠올려요.","많은 사람이 걸려요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_challenge#7','sci',3,2,'u4','L03','g3_2_sci_u4_L03_challenge','lesson_challenge','SC3-2-u4-C7',3,'mc','auto','감염병 카드를 만든 뒤 가장 중요한 활동은 무엇인가요?',ARRAY['SC3-2-u4-X14','SC3-2-u4-X15']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C7","difficulty":3,"kind":"mc","stem":"감염병 카드를 만든 뒤 가장 중요한 활동은 무엇인가요?","options":[{"t":"조사한 내용으로 감염병이 위험한 까닭을 토의하기","correct":true},{"t":"카드의 증상을 모두 외우기","mis":"SC3-2-u4-X14"},{"t":"친구 카드의 틀린 곳 비웃기","mis":"SC3-2-u4-X15"},{"t":"카드를 가장 화려하게 꾸미기","mis":"SC3-2-u4-X14"}],"explanation":["오늘 활동을 떠올려요.","토의를 해요.","위험한 까닭을 토의해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_challenge#8','sci',3,2,'u4','L03','g3_2_sci_u4_L03_challenge','lesson_challenge','SC3-2-u4-C7',4,'mc','auto','친구가 「나는 건강하니까 감염병은 나와 상관없어.」라고 말했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-2-u4-X13','SC3-2-u4-X14','SC3-2-u4-X15']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C7","difficulty":4,"kind":"mc","stem":"친구가 「나는 건강하니까 감염병은 나와 상관없어.」라고 말했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「감염병은 누구나 걸릴 수 있고 다른 사람에게 옮을 수도 있어서 모두 조심해야 해.」","correct":true},{"t":"「맞아, 건강한 사람은 절대 걸리지 않아.」","mis":"SC3-2-u4-X13"},{"t":"「증상을 모두 외우면 걸리지 않아.」","mis":"SC3-2-u4-X14"},{"t":"「그런 말은 듣지 않을래.」","mis":"SC3-2-u4-X15"}],"explanation":["위험성을 떠올려요.","누구나 걸려요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_challenge#9','sci',3,2,'u4','L03','g3_2_sci_u4_L03_challenge','lesson_challenge','SC3-2-u4-C6',4,'mc','auto','감염병 카드에 쓸 내용을 조사하는 순서로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X12','SC3-2-u4-X11','SC3-2-u4-X14']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C6","difficulty":4,"kind":"mc","stem":"감염병 카드에 쓸 내용을 조사하는 순서로 가장 알맞은 것은 무엇인가요?","options":[{"t":"조사할 감염병 정하기 → 믿을 수 있는 곳에서 최신 자료 찾기 → 이름·증상·특징을 칸에 맞게 쓰고 출처 밝히기","correct":true},{"t":"아무 글이나 찾기 → 카드에 그대로 옮기기 → 출처 지우기","mis":"SC3-2-u4-X12"},{"t":"증상과 특징을 한 칸에 모두 쓰기 → 증상 외우기 → 토의하지 않기","mis":"SC3-2-u4-X11"},{"t":"오래된 자료 찾기 → 이름만 쓰기 → 증상 모두 외우기","mis":"SC3-2-u4-X14"}],"explanation":["믿을 수 있는 자료부터요.","칸에 맞게 써요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L03_challenge#10','sci',3,2,'u4','L03','g3_2_sci_u4_L03_challenge','lesson_challenge','SC3-2-u4-C7',4,'essay','teacher','감염병이 위험한 까닭을 두 가지 쓰고, 「증상이 다양하니까 괜찮아요.」라는 의견을 바르게 고쳐 쓰세요. 그리고 토의할 때 지킬 태도를 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u4-C7","difficulty":4,"kind":"essay","stem":"감염병이 위험한 까닭을 두 가지 쓰고, 「증상이 다양하니까 괜찮아요.」라는 의견을 바르게 고쳐 쓰세요. 그리고 토의할 때 지킬 태도를 한 가지 쓰세요.","answer_guide":{"answer":"예: 감염병에 걸리면 다양한 증상이 나타나 몸이 아프고, 다른 사람에게 옮아 많은 사람이 걸릴 수 있어서 위험하다. 증상이 다양하다고 괜찮은 것이 아니라, 여러 증상이 나타나 몸이 아플 수 있으니 조심해야 한다. 친구 의견을 끝까지 듣고 존중한다.","scoring_points":["감염병이 위험한 까닭 두 가지를 썼는가","잘못된 의견을 바르게 고쳤는가","토의할 때의 태도를 썼는가"]},"explanation":["위험성을 떠올려요.","의견을 고쳐요.","태도를 써요."],"asset":{"type":"passage","lines":["친구 가 — 「여러 증상이 나타나 몸이 아파요.」","친구 나 — 「다른 사람에게 옮아 많은 사람이 걸려요.」","친구 다 — 「증상이 다양하니까 괜찮아요.」","친구 라 — 「치료 뒤에도 증상이 오래 남기도 해요.」"],"title":"감염병이 위험한 까닭 토의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_basic#1','sci',3,2,'u4','L04','g3_2_sci_u4_L04_basic','lesson_basic','SC3-2-u4-C8',1,'mc','auto','사람들이 사회적 거리 두기를 한 까닭은 무엇인가요?',ARRAY['SC3-2-u4-X16']::text[],false,'{"seq":1,"concept":"SC3-2-u4-C8","difficulty":1,"kind":"mc","stem":"사람들이 사회적 거리 두기를 한 까닭은 무엇인가요?","options":[{"t":"감염병이 널리 퍼지고 있어서","correct":true},{"t":"날씨가 추워서","mis":"SC3-2-u4-X16"},{"t":"가게가 너무 많아서","mis":"SC3-2-u4-X16"},{"t":"학교 공사를 해서","mis":"SC3-2-u4-X16"}],"explanation":["많은 사람이 걸리는 것을 막아요.","모이지 않게 했어요.","감염병이 퍼지고 있어서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_basic#2','sci',3,2,'u4','L04','g3_2_sci_u4_L04_basic','lesson_basic','SC3-2-u4-C9',1,'sa','auto','「우리의 건강과 일상생활을 지키려면 감염병으로부터 (    ) 사회를 만드는 데 관심을 가져야 해요.」 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u4-C9","difficulty":1,"kind":"sa","stem":"「우리의 건강과 일상생활을 지키려면 감염병으로부터 (    ) 사회를 만드는 데 관심을 가져야 해요.」 빈칸에 알맞은 말을 쓰세요.","answer":["안전한"],"explanation":["유행하지 않는 사회예요.","안◯◯ 사회예요.","안전한이에요."],"mis":"SC3-2-u4-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_basic#3','sci',3,2,'u4','L04','g3_2_sci_u4_L04_basic','lesson_basic','SC3-2-u4-C8',1,'ox','auto','감염병이 크게 유행했을 때 학교가 문을 닫아 등교하지 못하기도 했어요.',ARRAY['SC3-2-u4-X16']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C8","difficulty":1,"kind":"ox","stem":"감염병이 크게 유행했을 때 학교가 문을 닫아 등교하지 못하기도 했어요.","answer":"O","reason_options":[{"t":"여러 사람이 한곳에 모이지 않도록 했기 때문에","correct":true},{"t":"학교에 공부할 것이 없었기 때문에","mis":"SC3-2-u4-X16"}],"mis":"SC3-2-u4-X16","explanation":["붙임쪽지를 떠올려요.","모이지 않게 했어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_basic#4','sci',3,2,'u4','L04','g3_2_sci_u4_L04_basic','lesson_basic','SC3-2-u4-C9',1,'mc','auto','감염병으로부터 안전한 사회의 모습은 무엇인가요?',ARRAY['SC3-2-u4-X17']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C9","difficulty":1,"kind":"mc","stem":"감염병으로부터 안전한 사회의 모습은 무엇인가요?","options":[{"t":"놀이터에 사람들이 많아져요","correct":true},{"t":"놀이터에 사람이 없어요","mis":"SC3-2-u4-X17"},{"t":"가게가 문을 닫아요","mis":"SC3-2-u4-X17"},{"t":"학교에 등교하지 못해요","mis":"SC3-2-u4-X17"}],"explanation":["함께 모일 수 있어요.","놀이터를 떠올려요.","사람들이 많아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_basic#5','sci',3,2,'u4','L04','g3_2_sci_u4_L04_basic','lesson_basic','SC3-2-u4-C8',2,'mc','auto','「위험」 붙임쪽지에서 병원의 모습으로 알 수 있는 것은 무엇인가요?',ARRAY['SC3-2-u4-X17','SC3-2-u4-X18']::text[],false,'{"seq":5,"concept":"SC3-2-u4-C8","difficulty":2,"kind":"mc","stem":"「위험」 붙임쪽지에서 병원의 모습으로 알 수 있는 것은 무엇인가요?","options":[{"t":"병원이 제 역할을 하기 어려웠다","correct":true},{"t":"병원이 텅 비어 한가했다","mis":"SC3-2-u4-X17"},{"t":"병원이 문을 열 필요가 없었다","mis":"SC3-2-u4-X18"},{"t":"아픈 사람이 모두 사라졌다","mis":"SC3-2-u4-X17"}],"explanation":["병원 쪽지를 읽어요.","응급실을 쓰기 어려워요.","제 역할을 하기 어려웠어요."],"asset":{"type":"passage","lines":["집 — 친구들과 만나지 못하고 집에서만 지내요.","가게 — 손님이 없어서 문을 닫아요.","학교 — 문을 닫아 등교하지 못해요.","병원 — 환자가 많아 응급실을 이용하기 어려워요."],"title":"「위험」 붙임쪽지 — 감염병이 크게 유행했을 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_basic#6','sci',3,2,'u4','L04','g3_2_sci_u4_L04_basic','lesson_basic','SC3-2-u4-C9',2,'match','auto','크게 유행할 때의 모습과 안전한 사회의 모습을 같은 장소끼리 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u4-C9","difficulty":2,"kind":"match","stem":"크게 유행할 때의 모습과 안전한 사회의 모습을 같은 장소끼리 이으세요.","pairs":[{"l":"손님이 없어 문을 닫은 가게","r":"손님들이 자유롭게 가게를 이용해요"},{"l":"환자로 가득 찬 병원","r":"아픈 사람들이 병원을 쉽게 이용해요"},{"l":"텅 빈 놀이터","r":"놀이터에 사람들이 많아져요"}],"mis":"SC3-2-u4-X17","explanation":["「위험」 쪽지의 반대 모습이에요.","같은 장소끼리 이어요.","가게-가게, 병원-병원, 놀이터-놀이터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_basic#7','sci',3,2,'u4','L04','g3_2_sci_u4_L04_basic','lesson_basic','SC3-2-u4-C8',2,'mc','auto','감염병이 크게 유행할 때의 모습이 아닌 것은 무엇인가요?',ARRAY['SC3-2-u4-X17']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C8","difficulty":2,"kind":"mc","stem":"감염병이 크게 유행할 때의 모습이 아닌 것은 무엇인가요?","options":[{"t":"모든 가게가 손님으로 붐빈다","correct":true},{"t":"공공시설을 이용하기 어렵다","mis":"SC3-2-u4-X17"},{"t":"여러 사람이 모여 생활하기 어렵다","mis":"SC3-2-u4-X17"},{"t":"병원이 제 역할을 하기 어렵다","mis":"SC3-2-u4-X17"}],"explanation":["사람들이 모이는 곳을 떠올려요.","가게에 손님이 줄어요.","붐비는 가게예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_basic#8','sci',3,2,'u4','L04','g3_2_sci_u4_L04_basic','lesson_basic','SC3-2-u4-C8',2,'ox','auto','감염병에 걸리는 사람이 있으면 언제나 학교와 가게가 모두 문을 닫아요.',ARRAY['SC3-2-u4-X18']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C8","difficulty":2,"kind":"ox","stem":"감염병에 걸리는 사람이 있으면 언제나 학교와 가게가 모두 문을 닫아요.","answer":"X","reason_options":[{"t":"사회가 크게 달라지는 것은 감염병이 대유행했을 때이기 때문에","correct":true},{"t":"감염병에 한 명만 걸려도 사회가 늘 멈추기 때문에","mis":"SC3-2-u4-X18"}],"mis":"SC3-2-u4-X18","explanation":["언제 사회가 달라졌을까요?","대유행 때예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_basic#9','sci',3,2,'u4','L04','g3_2_sci_u4_L04_basic','lesson_basic','SC3-2-u4-C9',2,'mc','auto','오늘날 과학자들이 감염병으로부터 안전한 사회를 만들려고 하는 일은 무엇인가요?',ARRAY['SC3-2-u4-X20']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C9","difficulty":2,"kind":"mc","stem":"오늘날 과학자들이 감염병으로부터 안전한 사회를 만들려고 하는 일은 무엇인가요?","options":[{"t":"최신 과학 기술로 감염병의 원인을 밝히고 예방하는 방법을 연구한다","correct":true},{"t":"사람들이 영원히 모이지 못하게 한다","mis":"SC3-2-u4-X20"},{"t":"감염병 연구를 멈춘다","mis":"SC3-2-u4-X20"},{"t":"병원 문을 모두 닫는다","mis":"SC3-2-u4-X20"}],"explanation":["과학 기술을 떠올려요.","원인·진단·치료·예방이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_basic#10','sci',3,2,'u4','L04','g3_2_sci_u4_L04_basic','lesson_basic','SC3-2-u4-C9',3,'mc','auto','안전한 사회를 위한 다짐으로 알맞은 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X19']::text[],false,'{"seq":10,"concept":"SC3-2-u4-C9","difficulty":3,"kind":"mc","stem":"안전한 사회를 위한 다짐으로 알맞은 것끼리 묶은 것은 무엇인가요?","options":[{"t":"건강을 잘 관리한다, 안전한 사회를 만드는 데 관심을 가진다","correct":true},{"t":"감염병은 나와 상관없다고 생각한다, 건강을 잘 관리한다","mis":"SC3-2-u4-X19"},{"t":"아픈데도 사람이 많은 곳에 간다, 관심을 가진다","mis":"SC3-2-u4-X19"},{"t":"감염병은 나와 상관없다고 생각한다, 아픈데도 사람이 많은 곳에 간다","mis":"SC3-2-u4-X19"}],"explanation":["유행을 막는 데 도움이 되는 것이에요.","상관없다는 생각은 빼요.","건강 관리와 관심이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_challenge#1','sci',3,2,'u4','L04','g3_2_sci_u4_L04_challenge','lesson_challenge','SC3-2-u4-C8',2,'sa','auto','많은 사람이 감염병에 걸리는 것을 막으려고 사람들이 한곳에 모이지 않도록 한 것을 「사회적 ○○ ○○」라고 해요. 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u4-C8","difficulty":2,"kind":"sa","stem":"많은 사람이 감염병에 걸리는 것을 막으려고 사람들이 한곳에 모이지 않도록 한 것을 「사회적 ○○ ○○」라고 해요. 알맞은 말을 쓰세요.","answer":["거리 두기","거리두기"],"explanation":["떨어져 앉았어요.","거◯ 두◯예요.","거리 두기예요."],"mis":"SC3-2-u4-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_challenge#2','sci',3,2,'u4','L04','g3_2_sci_u4_L04_challenge','lesson_challenge','SC3-2-u4-C9',2,'mc','auto','「위험」 붙임쪽지의 가게와 반대되는 안전한 사회의 모습은 무엇인가요?',ARRAY['SC3-2-u4-X17']::text[],false,'{"seq":2,"concept":"SC3-2-u4-C9","difficulty":2,"kind":"mc","stem":"「위험」 붙임쪽지의 가게와 반대되는 안전한 사회의 모습은 무엇인가요?","options":[{"t":"가게가 문을 열고 손님들이 자유롭게 이용한다","correct":true},{"t":"가게가 계속 문을 닫는다","mis":"SC3-2-u4-X17"},{"t":"손님이 없어 가게가 사라진다","mis":"SC3-2-u4-X17"},{"t":"가게 앞에 아무도 오지 않는다","mis":"SC3-2-u4-X17"}],"explanation":["가게 쪽지를 봐요.","반대 모습을 떠올려요.","문을 열고 자유롭게 이용해요."],"asset":{"type":"passage","lines":["집 — 친구들과 만나지 못하고 집에서만 지내요.","가게 — 손님이 없어서 문을 닫아요.","학교 — 문을 닫아 등교하지 못해요.","병원 — 환자가 많아 응급실을 이용하기 어려워요."],"title":"「위험」 붙임쪽지 — 감염병이 크게 유행했을 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_challenge#3','sci',3,2,'u4','L04','g3_2_sci_u4_L04_challenge','lesson_challenge','SC3-2-u4-C8',3,'error','auto','「위험」 붙임쪽지를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u4-X18','SC3-2-u4-X16','SC3-2-u4-X19']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C8","difficulty":3,"kind":"error","stem":"「위험」 붙임쪽지를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「감염병에 걸리면 언제나 이렇게 되니 너무 무서워.」","correct":true,"mis_target":"SC3-2-u4-X18"},{"t":"친구 나 — 「크게 유행했을 때라서 모이기 어려웠던 거야.」","mis":"SC3-2-u4-X16"},{"t":"친구 다 — 「안전한 사회를 만드는 데 관심을 가지자.」","mis":"SC3-2-u4-X19"}],"explanation":["언제의 모습일까요?","대유행 때예요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["집 — 친구들과 만나지 못하고 집에서만 지내요.","가게 — 손님이 없어서 문을 닫아요.","학교 — 문을 닫아 등교하지 못해요.","병원 — 환자가 많아 응급실을 이용하기 어려워요."],"title":"「위험」 붙임쪽지 — 감염병이 크게 유행했을 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_challenge#4','sci',3,2,'u4','L04','g3_2_sci_u4_L04_challenge','lesson_challenge','SC3-2-u4-C8',3,'mc','auto','「학교가 문을 닫아요, 친구들과 모여 놀아요, 병원이 환자로 가득 차요, 도서관을 자유롭게 이용해요」를 「크게 유행할 때의 모습인가?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X17']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C8","difficulty":3,"kind":"mc","stem":"「학교가 문을 닫아요, 친구들과 모여 놀아요, 병원이 환자로 가득 차요, 도서관을 자유롭게 이용해요」를 「크게 유행할 때의 모습인가?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"학교가 문을 닫아요, 병원이 환자로 가득 차요","correct":true},{"t":"친구들과 모여 놀아요, 도서관을 자유롭게 이용해요","mis":"SC3-2-u4-X17"},{"t":"학교가 문을 닫아요, 도서관을 자유롭게 이용해요","mis":"SC3-2-u4-X17"},{"t":"친구들과 모여 놀아요, 병원이 환자로 가득 차요","mis":"SC3-2-u4-X17"}],"explanation":["모여 생활할 수 있는지 봐요.","문 닫고 가득 찬 곳이에요.","학교와 병원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_challenge#5','sci',3,2,'u4','L04','g3_2_sci_u4_L04_challenge','lesson_challenge','SC3-2-u4-C9',3,'mc','auto','감염병으로부터 안전한 사회를 만들면 좋은 점은 무엇인가요?',ARRAY['SC3-2-u4-X17']::text[],false,'{"seq":5,"concept":"SC3-2-u4-C9","difficulty":3,"kind":"mc","stem":"감염병으로부터 안전한 사회를 만들면 좋은 점은 무엇인가요?","options":[{"t":"사람들이 함께 모여 일상생활을 즐길 수 있다","correct":true},{"t":"학교에 가지 않아도 된다","mis":"SC3-2-u4-X17"},{"t":"가게가 모두 문을 닫는다","mis":"SC3-2-u4-X17"},{"t":"혼자서만 지내야 한다","mis":"SC3-2-u4-X17"}],"explanation":["안전한 사회를 떠올려요.","함께 모여요.","일상생활을 즐길 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_challenge#6','sci',3,2,'u4','L04','g3_2_sci_u4_L04_challenge','lesson_challenge','SC3-2-u4-C9',3,'ox','auto','과거에는 감염병의 원인이나 치료 방법을 알 수 없었지만, 오늘날 과학자들은 과학 기술로 끊임없이 연구하고 있어요.',ARRAY['SC3-2-u4-X20']::text[],false,'{"seq":6,"concept":"SC3-2-u4-C9","difficulty":3,"kind":"ox","stem":"과거에는 감염병의 원인이나 치료 방법을 알 수 없었지만, 오늘날 과학자들은 과학 기술로 끊임없이 연구하고 있어요.","answer":"O","reason_options":[{"t":"과학 기술로 원인을 밝히고 진단·치료·예방 방법을 찾기 때문에","correct":true},{"t":"과학 기술은 감염병과 아무 상관이 없기 때문에","mis":"SC3-2-u4-X20"}],"mis":"SC3-2-u4-X20","explanation":["옛날과 오늘날을 견줘요.","과학자들이 연구해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_challenge#7','sci',3,2,'u4','L04','g3_2_sci_u4_L04_challenge','lesson_challenge','SC3-2-u4-C8',3,'mc','auto','감염병이 크게 유행했을 때 도서관이 문을 닫은 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X16','SC3-2-u4-X18']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C8","difficulty":3,"kind":"mc","stem":"감염병이 크게 유행했을 때 도서관이 문을 닫은 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"여러 사람이 한곳에 모이면 감염병이 더 퍼질 수 있어서","correct":true},{"t":"도서관에 책이 모두 없어져서","mis":"SC3-2-u4-X16"},{"t":"사람들이 책을 싫어하게 되어서","mis":"SC3-2-u4-X16"},{"t":"감염병과 상관없이 원래 쉬는 날이어서","mis":"SC3-2-u4-X18"}],"explanation":["공공시설이에요.","사람이 모이는 곳이에요.","모이면 더 퍼질 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_challenge#8','sci',3,2,'u4','L04','g3_2_sci_u4_L04_challenge','lesson_challenge','SC3-2-u4-C9',4,'mc','auto','친구가 「감염병 이야기는 무서우니까 아예 생각하지 않을래.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-2-u4-X19','SC3-2-u4-X18','SC3-2-u4-X20']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C9","difficulty":4,"kind":"mc","stem":"친구가 「감염병 이야기는 무서우니까 아예 생각하지 않을래.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「크게 유행했을 때의 모습이니 너무 겁먹기보다, 안전한 사회를 만드는 데 관심을 가지고 건강을 관리하자.」","correct":true},{"t":"「맞아, 감염병은 우리와 상관없어.」","mis":"SC3-2-u4-X19"},{"t":"「감염병에 걸리면 언제나 학교가 닫히니까 정말 무서워해야 해.」","mis":"SC3-2-u4-X18"},{"t":"「과학자들도 아무것도 할 수 없으니 생각해도 소용없어.」","mis":"SC3-2-u4-X20"}],"explanation":["지나치게 겁먹지 않아요.","관심을 가져요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_challenge#9','sci',3,2,'u4','L04','g3_2_sci_u4_L04_challenge','lesson_challenge','SC3-2-u4-C8',4,'mc','auto','「위험」 붙임쪽지를 보고 감염병이 크게 유행할 때 달라진 사회를 바르게 정리한 것은 무엇인가요?',ARRAY['SC3-2-u4-X17','SC3-2-u4-X18']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C8","difficulty":4,"kind":"mc","stem":"「위험」 붙임쪽지를 보고 감염병이 크게 유행할 때 달라진 사회를 바르게 정리한 것은 무엇인가요?","options":[{"t":"사람들이 모이기 어려워 일상생활이 불편해지고, 병원과 공공시설이 제 역할을 하기 어렵다","correct":true},{"t":"사람들이 더 많이 모여 일상생활이 편해진다","mis":"SC3-2-u4-X17"},{"t":"감염병이 유행해도 사회는 아무것도 달라지지 않는다","mis":"SC3-2-u4-X18"},{"t":"병원만 바빠지고 다른 곳은 모두 그대로이다","mis":"SC3-2-u4-X17"}],"explanation":["네 장소를 모두 봐요.","모이기 어려워요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["집 — 친구들과 만나지 못하고 집에서만 지내요.","가게 — 손님이 없어서 문을 닫아요.","학교 — 문을 닫아 등교하지 못해요.","병원 — 환자가 많아 응급실을 이용하기 어려워요."],"title":"「위험」 붙임쪽지 — 감염병이 크게 유행했을 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L04_challenge#10','sci',3,2,'u4','L04','g3_2_sci_u4_L04_challenge','lesson_challenge','SC3-2-u4-C9',4,'essay','teacher','「위험」 붙임쪽지의 장소 두 곳을 골라 감염병이 크게 유행했을 때의 모습과 안전한 사회의 모습을 견주어 쓰고, 안전한 사회를 만들려고 과학자들이 하는 일을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u4-C9","difficulty":4,"kind":"essay","stem":"「위험」 붙임쪽지의 장소 두 곳을 골라 감염병이 크게 유행했을 때의 모습과 안전한 사회의 모습을 견주어 쓰고, 안전한 사회를 만들려고 과학자들이 하는 일을 한 가지 쓰세요.","answer_guide":{"answer":"예: 크게 유행했을 때 학교는 문을 닫아 등교하지 못했지만, 안전한 사회에서는 학교에 가서 선생님, 친구들과 함께 공부한다. 가게는 손님이 없어 문을 닫았지만, 안전한 사회에서는 손님들이 자유롭게 이용한다. 과학자들은 과학 기술로 감염병의 원인을 밝히고 예방 방법을 연구한다.","scoring_points":["한 장소의 두 모습을 바르게 견주었는가","다른 장소의 두 모습을 바르게 견주었는가","과학자들이 하는 일을 썼는가"]},"explanation":["장소 두 곳을 골라요.","두 모습을 견줘요.","과학자의 일을 써요."],"asset":{"type":"passage","lines":["집 — 친구들과 만나지 못하고 집에서만 지내요.","가게 — 손님이 없어서 문을 닫아요.","학교 — 문을 닫아 등교하지 못해요.","병원 — 환자가 많아 응급실을 이용하기 어려워요."],"title":"「위험」 붙임쪽지 — 감염병이 크게 유행했을 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_basic#1','sci',3,2,'u4','L05','g3_2_sci_u4_L05_basic','lesson_basic','SC3-2-u4-C10',1,'mc','auto','친구가 먹던 음식을 나눠 먹고 감염병이 옮았어요. 무엇을 통해 감염된 것인가요?',ARRAY['SC3-2-u4-X21','SC3-2-u4-X22']::text[],false,'{"seq":1,"concept":"SC3-2-u4-C10","difficulty":1,"kind":"mc","stem":"친구가 먹던 음식을 나눠 먹고 감염병이 옮았어요. 무엇을 통해 감염된 것인가요?","options":[{"t":"음식에 묻은 침","correct":true},{"t":"오염된 물","mis":"SC3-2-u4-X21"},{"t":"기침할 때 나오는 비말","mis":"SC3-2-u4-X21"},{"t":"햇빛","mis":"SC3-2-u4-X22"}],"explanation":["음식을 나눠 먹었어요.","음식에 무엇이 묻었을까요?","침이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_basic#2','sci',3,2,'u4','L05','g3_2_sci_u4_L05_basic','lesson_basic','SC3-2-u4-C10',1,'sa','auto','기침이나 재채기를 할 때 입에서 튀어 나오는 아주 작은 침방울을 「○○」이라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u4-C10","difficulty":1,"kind":"sa","stem":"기침이나 재채기를 할 때 입에서 튀어 나오는 아주 작은 침방울을 「○○」이라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["비말"],"explanation":["기침할 때 나와요.","비◯이에요.","비말이에요."],"mis":"SC3-2-u4-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_basic#3','sci',3,2,'u4','L05','g3_2_sci_u4_L05_basic','lesson_basic','SC3-2-u4-C11',1,'ox','auto','나의 생활 습관이 감염병을 유행시킬 수 있어요.',ARRAY['SC3-2-u4-X23']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C11","difficulty":1,"kind":"ox","stem":"나의 생활 습관이 감염병을 유행시킬 수 있어요.","answer":"O","reason_options":[{"t":"손을 씻지 않거나 아무렇게나 기침하면 다른 사람에게 옮길 수 있기 때문에","correct":true},{"t":"생활 습관과 감염병은 아무 관련이 없기 때문에","mis":"SC3-2-u4-X23"}],"mis":"SC3-2-u4-X23","explanation":["그림 속 습관을 떠올려요.","습관 때문에 옮았어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_basic#4','sci',3,2,'u4','L05','g3_2_sci_u4_L05_basic','lesson_basic','SC3-2-u4-C11',1,'mc','auto','감염병을 유행시킬 수 있는 습관은 무엇인가요?',ARRAY['SC3-2-u4-X24']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C11","difficulty":1,"kind":"mc","stem":"감염병을 유행시킬 수 있는 습관은 무엇인가요?","options":[{"t":"화장실에 다녀온 뒤 손을 씻지 않는다","correct":true},{"t":"아플 때 집에서 쉰다","mis":"SC3-2-u4-X24"},{"t":"밥 먹기 전에 손을 씻는다","mis":"SC3-2-u4-X24"},{"t":"기침할 때 옷소매로 가린다","mis":"SC3-2-u4-X24"}],"explanation":["손을 떠올려요.","씻지 않으면?","손을 씻지 않는 습관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_basic#5','sci',3,2,'u4','L05','g3_2_sci_u4_L05_basic','lesson_basic','SC3-2-u4-C10',2,'mc','auto','그림 속 생활 습관에서 ㉣은 무엇을 통해 감염된 것인가요?',ARRAY['SC3-2-u4-X21']::text[],false,'{"seq":5,"concept":"SC3-2-u4-C10","difficulty":2,"kind":"mc","stem":"그림 속 생활 습관에서 ㉣은 무엇을 통해 감염된 것인가요?","options":[{"t":"오염된 물","correct":true},{"t":"음식에 묻은 침","mis":"SC3-2-u4-X21"},{"t":"같은 공간의 공기","mis":"SC3-2-u4-X21"},{"t":"손","mis":"SC3-2-u4-X21"}],"explanation":["㉣을 읽어요.","물을 확인하지 않았어요.","오염된 물이에요."],"asset":{"type":"passage","lines":["㉠ 손을 씻지 않고 눈을 비볐더니 눈병이 났어요.","㉡ 친구가 먹던 음식을 나눠 먹고 감염병이 옮았어요.","㉢ 아픈데도 학교에 가서 같은 교실 친구에게 옮았어요.","㉣ 확인하지 않은 물을 마시고 배탈이 났어요.","㉤ 아무렇게나 기침하는 친구와 놀고 감기가 옮았어요."],"title":"그림 속 생활 습관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_basic#6','sci',3,2,'u4','L05','g3_2_sci_u4_L05_basic','lesson_basic','SC3-2-u4-C10',2,'match','auto','생활 습관과 감염 과정을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u4-C10","difficulty":2,"kind":"match","stem":"생활 습관과 감염 과정을 알맞게 이으세요.","pairs":[{"l":"확인하지 않은 물 마시기","r":"오염된 물을 통해"},{"l":"먹던 음식 먹기","r":"음식에 묻은 침을 통해"},{"l":"아무렇게나 기침하기","r":"기침할 때 나오는 비말을 통해"}],"mis":"SC3-2-u4-X21","explanation":["그림을 떠올려요.","음식은 침이에요.","물-오염된 물, 음식-침, 기침-비말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_basic#7','sci',3,2,'u4','L05','g3_2_sci_u4_L05_basic','lesson_basic','SC3-2-u4-C11',2,'mc','auto','감염병에 걸렸을 때 사람이 많은 곳에 가면 어떻게 될 수 있나요?',ARRAY['SC3-2-u4-X24']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C11","difficulty":2,"kind":"mc","stem":"감염병에 걸렸을 때 사람이 많은 곳에 가면 어떻게 될 수 있나요?","options":[{"t":"감염병을 유행시킬 수 있다","correct":true},{"t":"감염병이 저절로 없어진다","mis":"SC3-2-u4-X24"},{"t":"아무 일도 일어나지 않는다","mis":"SC3-2-u4-X24"},{"t":"다른 사람이 더 튼튼해진다","mis":"SC3-2-u4-X24"}],"explanation":["같은 공간을 떠올려요.","다른 사람에게 옮아요.","유행시킬 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_basic#8','sci',3,2,'u4','L05','g3_2_sci_u4_L05_basic','lesson_basic','SC3-2-u4-C12',2,'ox','auto','감염 과정 역할극은 재미있게 꾸미기만 하면 돼요.',ARRAY['SC3-2-u4-X25']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C12","difficulty":2,"kind":"ox","stem":"감염 과정 역할극은 재미있게 꾸미기만 하면 돼요.","answer":"X","reason_options":[{"t":"생활 습관과 감염 과정의 관련이 드러나야 하기 때문에","correct":true},{"t":"역할극은 재미가 가장 중요하기 때문에","mis":"SC3-2-u4-X25"}],"mis":"SC3-2-u4-X25","explanation":["역할극의 목적을 떠올려요.","관련이 드러나야 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_basic#9','sci',3,2,'u4','L05','g3_2_sci_u4_L05_basic','lesson_basic','SC3-2-u4-C12',2,'mc','auto','역할극을 준비하는 차례로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X26','SC3-2-u4-X25']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C12","difficulty":2,"kind":"mc","stem":"역할극을 준비하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"생활 습관 하나 고르기 → 감염 과정이 드러나게 대본 쓰기 → 준비물을 챙겨 역할극 하기","correct":true},{"t":"역할극 하기 → 대본 쓰기 → 생활 습관 고르기","mis":"SC3-2-u4-X26"},{"t":"준비물 챙기기 → 역할극 하기 → 끝","mis":"SC3-2-u4-X25"},{"t":"대본 없이 바로 춤추며 노래하기","mis":"SC3-2-u4-X25"}],"explanation":["먼저 습관을 골라요.","그다음 대본이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_basic#10','sci',3,2,'u4','L05','g3_2_sci_u4_L05_basic','lesson_basic','SC3-2-u4-C10',3,'mc','auto','그림 속 생활 습관 ㉠~㉤ 가운데 기침이나 공기와 관련 있는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X22']::text[],false,'{"seq":10,"concept":"SC3-2-u4-C10","difficulty":3,"kind":"mc","stem":"그림 속 생활 습관 ㉠~㉤ 가운데 기침이나 공기와 관련 있는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"㉢, ㉤","correct":true},{"t":"㉠, ㉡","mis":"SC3-2-u4-X22"},{"t":"㉡, ㉣","mis":"SC3-2-u4-X22"},{"t":"㉠, ㉣","mis":"SC3-2-u4-X22"}],"explanation":["같은 공간과 기침을 찾아요.","㉢은 교실, ㉤은 기침이에요.","㉢, ㉤이에요."],"asset":{"type":"passage","lines":["㉠ 손을 씻지 않고 눈을 비볐더니 눈병이 났어요.","㉡ 친구가 먹던 음식을 나눠 먹고 감염병이 옮았어요.","㉢ 아픈데도 학교에 가서 같은 교실 친구에게 옮았어요.","㉣ 확인하지 않은 물을 마시고 배탈이 났어요.","㉤ 아무렇게나 기침하는 친구와 놀고 감기가 옮았어요."],"title":"그림 속 생활 습관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_challenge#1','sci',3,2,'u4','L05','g3_2_sci_u4_L05_challenge','lesson_challenge','SC3-2-u4-C10',2,'mc','auto','그림 속 생활 습관에서 ㉠은 무엇을 통해 감염된 것인가요?',ARRAY['SC3-2-u4-X21']::text[],false,'{"seq":1,"concept":"SC3-2-u4-C10","difficulty":2,"kind":"mc","stem":"그림 속 생활 습관에서 ㉠은 무엇을 통해 감염된 것인가요?","options":[{"t":"더러운 손","correct":true},{"t":"오염된 물","mis":"SC3-2-u4-X21"},{"t":"기침할 때 나오는 비말","mis":"SC3-2-u4-X21"},{"t":"음식에 묻은 침","mis":"SC3-2-u4-X21"}],"explanation":["㉠을 읽어요.","눈을 비볐어요.","손을 통해서예요."],"asset":{"type":"passage","lines":["㉠ 손을 씻지 않고 눈을 비볐더니 눈병이 났어요.","㉡ 친구가 먹던 음식을 나눠 먹고 감염병이 옮았어요.","㉢ 아픈데도 학교에 가서 같은 교실 친구에게 옮았어요.","㉣ 확인하지 않은 물을 마시고 배탈이 났어요.","㉤ 아무렇게나 기침하는 친구와 놀고 감기가 옮았어요."],"title":"그림 속 생활 습관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_challenge#2','sci',3,2,'u4','L05','g3_2_sci_u4_L05_challenge','lesson_challenge','SC3-2-u4-C12',2,'mc','auto','역할극을 할 때 알맞은 태도는 무엇인가요?',ARRAY['SC3-2-u4-X26']::text[],false,'{"seq":2,"concept":"SC3-2-u4-C12","difficulty":2,"kind":"mc","stem":"역할극을 할 때 알맞은 태도는 무엇인가요?","options":[{"t":"역할을 공정하게 나누고 서로 협력하며 참여한다","correct":true},{"t":"하고 싶은 역할을 혼자 다 차지한다","mis":"SC3-2-u4-X26"},{"t":"대본 없이 마음대로 한다","mis":"SC3-2-u4-X26"},{"t":"친구 역할을 놀린다","mis":"SC3-2-u4-X26"}],"explanation":["함께 하는 활동이에요.","공정하게 나눠요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_challenge#3','sci',3,2,'u4','L05','g3_2_sci_u4_L05_challenge','lesson_challenge','SC3-2-u4-C11',3,'error','auto','친구들이 자기 습관을 말했어요. 감염병에 걸리거나 유행시킬 수 있는 습관을 가진 친구는 누구인가요?',ARRAY['SC3-2-u4-X24','SC3-2-u4-X21']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C11","difficulty":3,"kind":"error","stem":"친구들이 자기 습관을 말했어요. 감염병에 걸리거나 유행시킬 수 있는 습관을 가진 친구는 누구인가요?","options":[{"t":"친구 다 — 「화장실에 다녀온 뒤 손을 씻지 않았어.」","correct":true,"mis_target":"SC3-2-u4-X24"},{"t":"친구 가 — 「수두에 걸려서 학교에 가지 않았어.」","mis":"SC3-2-u4-X24"},{"t":"친구 나 — 「열이 나는 친구가 나눠 준 빵을 먹지 않았어.」","mis":"SC3-2-u4-X21"}],"explanation":["손을 떠올려요.","화장실 뒤에는 씻어요.","친구 다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_challenge#4','sci',3,2,'u4','L05','g3_2_sci_u4_L05_challenge','lesson_challenge','SC3-2-u4-C10',3,'mc','auto','「손을 씻지 않고 눈을 비벼요, 아무렇게나 기침하는 친구와 놀아요, 친구가 먹던 음식을 먹어요, 아픈 친구와 같은 교실에 있어요」를 손이나 음식으로 감염되는 것과 기침이나 공기로 감염되는 것으로 나눌 때, 손이나 음식 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X22']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C10","difficulty":3,"kind":"mc","stem":"「손을 씻지 않고 눈을 비벼요, 아무렇게나 기침하는 친구와 놀아요, 친구가 먹던 음식을 먹어요, 아픈 친구와 같은 교실에 있어요」를 손이나 음식으로 감염되는 것과 기침이나 공기로 감염되는 것으로 나눌 때, 손이나 음식 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"손을 씻지 않고 눈을 비벼요, 친구가 먹던 음식을 먹어요","correct":true},{"t":"아무렇게나 기침하는 친구와 놀아요, 아픈 친구와 같은 교실에 있어요","mis":"SC3-2-u4-X22"},{"t":"손을 씻지 않고 눈을 비벼요, 아픈 친구와 같은 교실에 있어요","mis":"SC3-2-u4-X22"},{"t":"아무렇게나 기침하는 친구와 놀아요, 친구가 먹던 음식을 먹어요","mis":"SC3-2-u4-X22"}],"explanation":["감염 과정을 떠올려요.","눈 비비기는 손, 음식은 침이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_challenge#5','sci',3,2,'u4','L05','g3_2_sci_u4_L05_challenge','lesson_challenge','SC3-2-u4-C11',3,'mc','auto','생활 습관과 감염병 유행 사이의 관련으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X23']::text[],false,'{"seq":5,"concept":"SC3-2-u4-C11","difficulty":3,"kind":"mc","stem":"생활 습관과 감염병 유행 사이의 관련으로 알맞은 것은 무엇인가요?","options":[{"t":"생활 습관은 감염병 유행에 영향을 미친다","correct":true},{"t":"아무 관련이 없다","mis":"SC3-2-u4-X23"},{"t":"날씨만 영향을 미친다","mis":"SC3-2-u4-X23"},{"t":"나이만 영향을 미친다","mis":"SC3-2-u4-X23"}],"explanation":["다섯 가지 그림을 떠올려요.","습관 때문에 옮았어요.","영향을 미쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_challenge#6','sci',3,2,'u4','L05','g3_2_sci_u4_L05_challenge','lesson_challenge','SC3-2-u4-C10',3,'ox','auto','감염병은 손, 침, 공기, 오염된 물, 비말처럼 여러 가지 감염 과정을 통해 걸려요.',ARRAY['SC3-2-u4-X22']::text[],false,'{"seq":6,"concept":"SC3-2-u4-C10","difficulty":3,"kind":"ox","stem":"감염병은 손, 침, 공기, 오염된 물, 비말처럼 여러 가지 감염 과정을 통해 걸려요.","answer":"O","reason_options":[{"t":"그림 속 습관마다 감염된 과정이 서로 달랐기 때문에","correct":true},{"t":"감염병은 공기로만 옮기 때문에","mis":"SC3-2-u4-X22"}],"mis":"SC3-2-u4-X22","explanation":["다섯 그림을 견줘요.","과정이 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_challenge#7','sci',3,2,'u4','L05','g3_2_sci_u4_L05_challenge','lesson_challenge','SC3-2-u4-C12',3,'mc','auto','감염 과정이 드러나는 역할극 장면은 무엇인가요?',ARRAY['SC3-2-u4-X25']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C12","difficulty":3,"kind":"mc","stem":"감염 과정이 드러나는 역할극 장면은 무엇인가요?","options":[{"t":"친구에게 아무렇게나 기침해 감기가 옮는 장면","correct":true},{"t":"친구들이 춤추며 노래하는 장면","mis":"SC3-2-u4-X25"},{"t":"친구들이 공놀이를 하는 장면","mis":"SC3-2-u4-X25"},{"t":"친구들이 줄을 서서 인사하는 장면","mis":"SC3-2-u4-X25"}],"explanation":["습관과 감염병이 이어져야 해요.","옮는 장면을 찾아요.","기침으로 옮는 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_challenge#8','sci',3,2,'u4','L05','g3_2_sci_u4_L05_challenge','lesson_challenge','SC3-2-u4-C11',4,'mc','auto','열이 나고 기침이 나는데 오늘 친구 생일 잔치가 있어요. 감염병 유행을 막는 데 가장 알맞은 행동은 무엇인가요?',ARRAY['SC3-2-u4-X24','SC3-2-u4-X21','SC3-2-u4-X23']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C11","difficulty":4,"kind":"mc","stem":"열이 나고 기침이 나는데 오늘 친구 생일 잔치가 있어요. 감염병 유행을 막는 데 가장 알맞은 행동은 무엇인가요?","options":[{"t":"집에서 쉬며 친구에게 사정을 말하고 다음에 축하한다","correct":true},{"t":"마스크 없이 잔치에 가서 친구들과 음식을 나눠 먹는다","mis":"SC3-2-u4-X24"},{"t":"잔치에 가되 기침은 친구 쪽으로 한다","mis":"SC3-2-u4-X21"},{"t":"생활 습관은 상관없으니 평소처럼 간다","mis":"SC3-2-u4-X23"}],"explanation":["아플 때를 떠올려요.","사람이 모이는 곳이에요.","집에서 쉬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_challenge#9','sci',3,2,'u4','L05','g3_2_sci_u4_L05_challenge','lesson_challenge','SC3-2-u4-C12',4,'mc','auto','모둠이 「기침 예절을 지키지 않아 감기가 유행하는 장면」으로 역할극 대본을 쓰려고 해요. 가장 알맞은 대본 내용은 무엇인가요?',ARRAY['SC3-2-u4-X25','SC3-2-u4-X26']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C12","difficulty":4,"kind":"mc","stem":"모둠이 「기침 예절을 지키지 않아 감기가 유행하는 장면」으로 역할극 대본을 쓰려고 해요. 가장 알맞은 대본 내용은 무엇인가요?","options":[{"t":"한 친구가 아무렇게나 기침하자 비말을 통해 옆 친구들에게 차례로 감기가 옮는다","correct":true},{"t":"친구들이 재미있는 춤을 추며 노래한다","mis":"SC3-2-u4-X25"},{"t":"한 친구가 감기에 걸렸지만 까닭은 나오지 않는다","mis":"SC3-2-u4-X25"},{"t":"가장 재미있는 역할을 한 친구가 모두 맡는다","mis":"SC3-2-u4-X26"}],"explanation":["기침 예절이 주제예요.","감염 과정이 드러나야 해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L05_challenge#10','sci',3,2,'u4','L05','g3_2_sci_u4_L05_challenge','lesson_challenge','SC3-2-u4-C10',4,'essay','teacher','그림 속 생활 습관 ㉠~㉤ 가운데 두 가지를 골라 각각 무엇을 통해 감염되었는지 쓰고, 생활 습관과 감염병 유행의 관련을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u4-C10","difficulty":4,"kind":"essay","stem":"그림 속 생활 습관 ㉠~㉤ 가운데 두 가지를 골라 각각 무엇을 통해 감염되었는지 쓰고, 생활 습관과 감염병 유행의 관련을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: ㉡은 먹던 음식을 나눠 먹어 음식에 묻은 침을 통해 감염되었고, ㉤은 아무렇게나 기침하는 친구의 비말을 통해 감염되었다. 생활 습관에 따라 감염병이 옮거나 유행할 수 있으므로 올바른 생활 습관을 가져야 한다.","scoring_points":["한 습관의 감염 과정을 바르게 썼는가","다른 습관의 감염 과정을 바르게 썼는가","생활 습관과 감염병 유행의 관련을 썼는가"]},"explanation":["두 가지를 골라요.","감염 과정을 써요.","관련을 써요."],"asset":{"type":"passage","lines":["㉠ 손을 씻지 않고 눈을 비볐더니 눈병이 났어요.","㉡ 친구가 먹던 음식을 나눠 먹고 감염병이 옮았어요.","㉢ 아픈데도 학교에 가서 같은 교실 친구에게 옮았어요.","㉣ 확인하지 않은 물을 마시고 배탈이 났어요.","㉤ 아무렇게나 기침하는 친구와 놀고 감기가 옮았어요."],"title":"그림 속 생활 습관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_basic#1','sci',3,2,'u4','L06','g3_2_sci_u4_L06_basic','lesson_basic','SC3-2-u4-C13',1,'mc','auto','기침이 나올 때에는 어떻게 해야 하나요?',ARRAY['SC3-2-u4-X28']::text[],false,'{"seq":1,"concept":"SC3-2-u4-C13","difficulty":1,"kind":"mc","stem":"기침이 나올 때에는 어떻게 해야 하나요?","options":[{"t":"옷소매로 입과 코를 가린다","correct":true},{"t":"친구 쪽을 보고 기침한다","mis":"SC3-2-u4-X28"},{"t":"크게 소리 내어 기침한다","mis":"SC3-2-u4-X28"},{"t":"손바닥으로 가린 뒤 바로 친구와 악수한다","mis":"SC3-2-u4-X28"}],"explanation":["기침 예절이에요.","비말이 퍼지지 않게 해요.","옷소매로 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_basic#2','sci',3,2,'u4','L06','g3_2_sci_u4_L06_basic','lesson_basic','SC3-2-u4-C13',1,'sa','auto','감염병 예방 수칙 ②의 ㉠에 알맞은 말을 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u4-C13","difficulty":1,"kind":"sa","stem":"감염병 예방 수칙 ②의 ㉠에 알맞은 말을 네 글자로 쓰세요.","answer":["옷소매"],"explanation":["기침할 때예요.","옷◯◯예요.","옷소매예요."],"asset":{"type":"passage","lines":["① 비누로 30초 이상 흐르는 물에 손 씻기","② 기침할 때 ㉠로 입과 코 가리기","③ 음식은 익혀 먹고 깨끗한 물 마시기","④ 정해진 시기에 예방접종하기"],"title":"감염병 예방 수칙"},"mis":"SC3-2-u4-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_basic#3','sci',3,2,'u4','L06','g3_2_sci_u4_L06_basic','lesson_basic','SC3-2-u4-C13',1,'ox','auto','손을 씻을 때는 물로만 헹구면 충분해요.',ARRAY['SC3-2-u4-X27']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C13","difficulty":1,"kind":"ox","stem":"손을 씻을 때는 물로만 헹구면 충분해요.","answer":"X","reason_options":[{"t":"비누를 사용해 흐르는 물에 30초 이상 씻어야 하기 때문에","correct":true},{"t":"물만 닿으면 병원체가 모두 없어지기 때문에","mis":"SC3-2-u4-X27"}],"mis":"SC3-2-u4-X27","explanation":["예방 수칙 ①을 떠올려요.","비누가 필요해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_basic#4','sci',3,2,'u4','L06','g3_2_sci_u4_L06_basic','lesson_basic','SC3-2-u4-C13',1,'mc','auto','음식과 물에 대한 예방 수칙으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X29','SC3-2-u4-X30']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C13","difficulty":1,"kind":"mc","stem":"음식과 물에 대한 예방 수칙으로 알맞은 것은 무엇인가요?","options":[{"t":"음식은 익혀 먹고 깨끗한 물을 마신다","correct":true},{"t":"음식은 익히지 않고 먹는다","mis":"SC3-2-u4-X29"},{"t":"확인하지 않은 물을 마신다","mis":"SC3-2-u4-X29"},{"t":"다른 사람이 먹던 음식을 먹는다","mis":"SC3-2-u4-X30"}],"explanation":["예방 수칙 ③이에요.","익혀 먹어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_basic#5','sci',3,2,'u4','L06','g3_2_sci_u4_L06_basic','lesson_basic','SC3-2-u4-C13',2,'match','auto','예방 수칙과 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u4-C13","difficulty":2,"kind":"match","stem":"예방 수칙과 방법을 알맞게 이으세요.","pairs":[{"l":"손 씻기","r":"비누로 30초 이상 흐르는 물에"},{"l":"음식 먹기","r":"충분히 익혀 먹어요"},{"l":"예방접종","r":"정해진 시기에 해요"}],"mis":"SC3-2-u4-X29","explanation":["수칙을 떠올려요.","예방접종은 시기가 있어요.","손-비누 30초, 음식-익혀서, 접종-정해진 시기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_basic#6','sci',3,2,'u4','L06','g3_2_sci_u4_L06_basic','lesson_basic','SC3-2-u4-C13',2,'mc','auto','감염병을 예방하는 방법을 옳게 말한 것은 무엇인가요?',ARRAY['SC3-2-u4-X29','SC3-2-u4-X27']::text[],false,'{"seq":6,"concept":"SC3-2-u4-C13","difficulty":2,"kind":"mc","stem":"감염병을 예방하는 방법을 옳게 말한 것은 무엇인가요?","options":[{"t":"정해진 시기에 예방접종을 한다","correct":true},{"t":"음식은 익혀 먹지 않아도 된다","mis":"SC3-2-u4-X29"},{"t":"손바닥만 대충 씻어도 된다","mis":"SC3-2-u4-X27"},{"t":"예방접종은 아무 때나 한다","mis":"SC3-2-u4-X29"}],"explanation":["네 가지 수칙을 떠올려요.","예방접종은 정해진 시기예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_basic#7','sci',3,2,'u4','L06','g3_2_sci_u4_L06_basic','lesson_basic','SC3-2-u4-C14',2,'mc','auto','「다른 사람이 먹던 음식을 먹어요」를 예방하는 습관으로 바꾼 것은 무엇인가요?',ARRAY['SC3-2-u4-X30','SC3-2-u4-X29']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C14","difficulty":2,"kind":"mc","stem":"「다른 사람이 먹던 음식을 먹어요」를 예방하는 습관으로 바꾼 것은 무엇인가요?","options":[{"t":"다른 사람이 먹던 음식을 먹지 않는다","correct":true},{"t":"먹던 음식을 더 많이 나눠 먹는다","mis":"SC3-2-u4-X30"},{"t":"먹던 음식을 손으로 집어 먹는다","mis":"SC3-2-u4-X30"},{"t":"먹던 음식은 물로만 헹군다","mis":"SC3-2-u4-X29"}],"explanation":["반대로 해 봐요.","유행시키는 습관의 반대예요.","먹지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_basic#8','sci',3,2,'u4','L06','g3_2_sci_u4_L06_basic','lesson_basic','SC3-2-u4-C14',2,'ox','auto','기침할 때 옷소매로 입과 코를 가리는 것은 비말을 통한 감염을 막는 수칙이에요.',ARRAY['SC3-2-u4-X31']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C14","difficulty":2,"kind":"ox","stem":"기침할 때 옷소매로 입과 코를 가리는 것은 비말을 통한 감염을 막는 수칙이에요.","answer":"O","reason_options":[{"t":"기침할 때 나오는 비말이 퍼지지 않게 막기 때문에","correct":true},{"t":"손에 묻은 병원체를 씻어 내기 때문에","mis":"SC3-2-u4-X31"}],"mis":"SC3-2-u4-X31","explanation":["기침을 떠올려요.","비말을 막아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_basic#9','sci',3,2,'u4','L06','g3_2_sci_u4_L06_basic','lesson_basic','SC3-2-u4-C14',2,'mc','auto','예방 수칙을 노랫말로 만들 때 알맞은 방법은 무엇인가요?',ARRAY['SC3-2-u4-X32']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C14","difficulty":2,"kind":"mc","stem":"예방 수칙을 노랫말로 만들 때 알맞은 방법은 무엇인가요?","options":[{"t":"음악 시간에 배운 노래에 실천할 수 있는 수칙을 담아 바꾼다","correct":true},{"t":"어려운 의학 용어만 넣는다","mis":"SC3-2-u4-X32"},{"t":"수칙과 상관없는 말로 꾸민다","mis":"SC3-2-u4-X32"},{"t":"조사한 곳의 출처를 지운다","mis":"SC3-2-u4-X32"}],"explanation":["노래로 알려요.","실천할 수 있게요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_basic#10','sci',3,2,'u4','L06','g3_2_sci_u4_L06_basic','lesson_basic','SC3-2-u4-C13',3,'mc','auto','손을 씻으면 좋은 때가 아닌 것은 무엇인가요?',ARRAY['SC3-2-u4-X27']::text[],false,'{"seq":10,"concept":"SC3-2-u4-C13","difficulty":3,"kind":"mc","stem":"손을 씻으면 좋은 때가 아닌 것은 무엇인가요?","options":[{"t":"손이 깨끗해 보여서 씻지 않아도 될 때","correct":true},{"t":"외출하고 집에 돌아왔을 때","mis":"SC3-2-u4-X27"},{"t":"식사를 하기 전","mis":"SC3-2-u4-X27"},{"t":"기침을 하거나 코를 푼 뒤","mis":"SC3-2-u4-X27"}],"explanation":["병원체가 묻을 수 있는 때예요.","깨끗해 보여도 있을 수 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_challenge#1','sci',3,2,'u4','L06','g3_2_sci_u4_L06_challenge','lesson_challenge','SC3-2-u4-C13',2,'sa','auto','감염병 예방 수칙 ①에서 손을 씻는 시간은 몇 초 이상인가요? 숫자만 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u4-C13","difficulty":2,"kind":"sa","stem":"감염병 예방 수칙 ①에서 손을 씻는 시간은 몇 초 이상인가요? 숫자만 쓰세요.","answer":["30"],"explanation":["①을 읽어요.","뽀득뽀득 오래 씻어요.","30초 이상이에요."],"asset":{"type":"passage","lines":["① 비누로 30초 이상 흐르는 물에 손 씻기","② 기침할 때 ㉠로 입과 코 가리기","③ 음식은 익혀 먹고 깨끗한 물 마시기","④ 정해진 시기에 예방접종하기"],"title":"감염병 예방 수칙"},"mis":"SC3-2-u4-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_challenge#2','sci',3,2,'u4','L06','g3_2_sci_u4_L06_challenge','lesson_challenge','SC3-2-u4-C14',2,'mc','auto','모둠이 바꾼 노랫말이 알리는 예방 수칙은 무엇인가요?',ARRAY['SC3-2-u4-X31']::text[],false,'{"seq":2,"concept":"SC3-2-u4-C14","difficulty":2,"kind":"mc","stem":"모둠이 바꾼 노랫말이 알리는 예방 수칙은 무엇인가요?","options":[{"t":"비누로 흐르는 물에 30초 이상 손 씻기","correct":true},{"t":"옷소매로 입과 코 가리기","mis":"SC3-2-u4-X31"},{"t":"정해진 시기에 예방접종하기","mis":"SC3-2-u4-X31"},{"t":"음식 익혀 먹기","mis":"SC3-2-u4-X31"}],"explanation":["노랫말을 읽어요.","비누와 흐르는 물이에요.","손 씻기예요."],"asset":{"type":"passage","lines":["손을 씻어요 깨끗이 비누로 뽀득뽀득","흐르는 물에 30초 이상","잊지 말고 씻어요"],"title":"모둠이 바꾼 노랫말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_challenge#3','sci',3,2,'u4','L06','g3_2_sci_u4_L06_challenge','lesson_challenge','SC3-2-u4-C13',3,'error','auto','예방 수칙을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u4-X28','SC3-2-u4-X29']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C13","difficulty":3,"kind":"error","stem":"예방 수칙을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「기침할 때 손바닥으로 가리고 바로 친구와 악수하면 돼.」","correct":true,"mis_target":"SC3-2-u4-X28"},{"t":"친구 가 — 「기침이 심할 때는 마스크를 써.」","mis":"SC3-2-u4-X28"},{"t":"친구 다 — 「접종한 날에는 충분히 쉬어.」","mis":"SC3-2-u4-X29"}],"explanation":["기침 예절을 떠올려요.","손에 묻은 비말은요?","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_challenge#4','sci',3,2,'u4','L06','g3_2_sci_u4_L06_challenge','lesson_challenge','SC3-2-u4-C14',3,'mc','auto','「흐르는 물에 비누로 손 씻기, 옷소매로 입과 코 가리기, 외출한 뒤 손 씻기, 기침이 심할 때 마스크 쓰기」 가운데 비말을 통한 감염을 막는 수칙끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X31']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C14","difficulty":3,"kind":"mc","stem":"「흐르는 물에 비누로 손 씻기, 옷소매로 입과 코 가리기, 외출한 뒤 손 씻기, 기침이 심할 때 마스크 쓰기」 가운데 비말을 통한 감염을 막는 수칙끼리 묶은 것은 무엇인가요?","options":[{"t":"옷소매로 입과 코 가리기, 기침이 심할 때 마스크 쓰기","correct":true},{"t":"흐르는 물에 비누로 손 씻기, 외출한 뒤 손 씻기","mis":"SC3-2-u4-X31"},{"t":"흐르는 물에 비누로 손 씻기, 기침이 심할 때 마스크 쓰기","mis":"SC3-2-u4-X31"},{"t":"옷소매로 입과 코 가리기, 외출한 뒤 손 씻기","mis":"SC3-2-u4-X31"}],"explanation":["기침과 관련된 수칙이에요.","손 씻기는 손이에요.","소매와 마스크예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_challenge#5','sci',3,2,'u4','L06','g3_2_sci_u4_L06_challenge','lesson_challenge','SC3-2-u4-C13',3,'mc','auto','「다른 사람이 먹던 음식을 먹어요, 깨끗한 물을 마셔요, 아픈데도 외출해요, 아플 때 집에서 쉬어요」 가운데 예방하는 습관끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X30']::text[],false,'{"seq":5,"concept":"SC3-2-u4-C13","difficulty":3,"kind":"mc","stem":"「다른 사람이 먹던 음식을 먹어요, 깨끗한 물을 마셔요, 아픈데도 외출해요, 아플 때 집에서 쉬어요」 가운데 예방하는 습관끼리 묶은 것은 무엇인가요?","options":[{"t":"깨끗한 물을 마셔요, 아플 때 집에서 쉬어요","correct":true},{"t":"다른 사람이 먹던 음식을 먹어요, 아픈데도 외출해요","mis":"SC3-2-u4-X30"},{"t":"깨끗한 물을 마셔요, 아픈데도 외출해요","mis":"SC3-2-u4-X30"},{"t":"다른 사람이 먹던 음식을 먹어요, 아플 때 집에서 쉬어요","mis":"SC3-2-u4-X30"}],"explanation":["막는 습관을 찾아요.","물과 쉬기예요.","두 가지를 묶어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_challenge#6','sci',3,2,'u4','L06','g3_2_sci_u4_L06_challenge','lesson_challenge','SC3-2-u4-C14',3,'ox','auto','감염병 예방 수칙을 조사할 때는 어려운 의학 용어만 모으면 돼요.',ARRAY['SC3-2-u4-X32']::text[],false,'{"seq":6,"concept":"SC3-2-u4-C14","difficulty":3,"kind":"ox","stem":"감염병 예방 수칙을 조사할 때는 어려운 의학 용어만 모으면 돼요.","answer":"X","reason_options":[{"t":"생활 속에서 실천할 수 있는 구체적인 행동을 조사해야 하기 때문에","correct":true},{"t":"용어를 많이 알면 저절로 예방되기 때문에","mis":"SC3-2-u4-X32"}],"mis":"SC3-2-u4-X32","explanation":["실천할 수 있어야 해요.","손 씻기라면 방법까지요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_challenge#7','sci',3,2,'u4','L06','g3_2_sci_u4_L06_challenge','lesson_challenge','SC3-2-u4-C13',3,'mc','auto','「음식은 익혀 먹고 깨끗한 물 마시기」는 어떤 생활 습관 때문에 생기는 감염을 막나요?',ARRAY['SC3-2-u4-X31']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C13","difficulty":3,"kind":"mc","stem":"「음식은 익혀 먹고 깨끗한 물 마시기」는 어떤 생활 습관 때문에 생기는 감염을 막나요?","options":[{"t":"확인하지 않은 물을 마시거나 익히지 않은 음식을 먹는 습관","correct":true},{"t":"아무렇게나 기침하는 습관","mis":"SC3-2-u4-X31"},{"t":"손을 씻지 않고 눈을 비비는 습관","mis":"SC3-2-u4-X31"},{"t":"아픈데도 학교에 가는 습관","mis":"SC3-2-u4-X31"}],"explanation":["물과 음식이에요.","오염된 물을 떠올려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_challenge#8','sci',3,2,'u4','L06','g3_2_sci_u4_L06_challenge','lesson_challenge','SC3-2-u4-C14',4,'mc','auto','친구네 모둠이 예방 수칙 홍보지에 「건강하게 지내요」라고만 썼어요. 가장 알맞게 고친 것은 무엇인가요?',ARRAY['SC3-2-u4-X32']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C14","difficulty":4,"kind":"mc","stem":"친구네 모둠이 예방 수칙 홍보지에 「건강하게 지내요」라고만 썼어요. 가장 알맞게 고친 것은 무엇인가요?","options":[{"t":"「밖에서 돌아오면 비누로 흐르는 물에 30초 이상 손을 씻어요.」","correct":true},{"t":"「모두 아프지 말아요.」","mis":"SC3-2-u4-X32"},{"t":"「병원체를 조심해요.」","mis":"SC3-2-u4-X32"},{"t":"「건강이 최고예요.」","mis":"SC3-2-u4-X32"}],"explanation":["무엇을 어떻게 할지 써요.","구체적인 행동이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_challenge#9','sci',3,2,'u4','L06','g3_2_sci_u4_L06_challenge','lesson_challenge','SC3-2-u4-C13',4,'mc','auto','예방 수칙 네 가지를 감염 과정과 바르게 이은 것은 무엇인가요?',ARRAY['SC3-2-u4-X31','SC3-2-u4-X22','SC3-2-u4-X23']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C13","difficulty":4,"kind":"mc","stem":"예방 수칙 네 가지를 감염 과정과 바르게 이은 것은 무엇인가요?","options":[{"t":"손 씻기 — 손 · 옷소매로 가리기 — 비말 · 익혀 먹고 깨끗한 물 — 오염된 물과 음식 · 예방접종 — 미리 몸을 보호","correct":true},{"t":"손 씻기 — 비말 · 옷소매로 가리기 — 손 · 익혀 먹기 — 공기 · 예방접종 — 물","mis":"SC3-2-u4-X31"},{"t":"네 가지 모두 공기를 통한 감염만 막는다","mis":"SC3-2-u4-X22"},{"t":"네 가지 모두 감염과 상관없다","mis":"SC3-2-u4-X23"}],"explanation":["수칙마다 막는 길이 달라요.","소매는 비말이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L06_challenge#10','sci',3,2,'u4','L06','g3_2_sci_u4_L06_challenge','lesson_challenge','SC3-2-u4-C14',4,'essay','teacher','지난 시간에 배운 감염병을 유행시키는 습관 두 가지를 예방하는 습관으로 바꾸어 쓰고, 각각 어떤 감염을 막는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u4-C14","difficulty":4,"kind":"essay","stem":"지난 시간에 배운 감염병을 유행시키는 습관 두 가지를 예방하는 습관으로 바꾸어 쓰고, 각각 어떤 감염을 막는지 쓰세요.","answer_guide":{"answer":"예: 아무렇게나 기침하는 습관은 기침할 때 옷소매로 입과 코를 가리는 습관으로 바꾸어 비말을 통한 감염을 막는다. 손을 씻지 않고 눈을 비비는 습관은 비누로 흐르는 물에 30초 이상 손을 씻는 습관으로 바꾸어 손을 통한 감염을 막는다.","scoring_points":["한 습관을 예방하는 습관으로 바르게 바꾸었는가","다른 습관을 예방하는 습관으로 바르게 바꾸었는가","각각 막는 감염을 바르게 썼는가"]},"explanation":["유행시키는 습관을 떠올려요.","반대로 바꿔요.","막는 감염을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_basic#1','sci',3,2,'u4','L07','g3_2_sci_u4_L07_basic','lesson_basic','SC3-2-u4-C15',1,'mc','auto','학교에서 두 친구가 발견한 문제점은 무엇인가요?',ARRAY['SC3-2-u4-X33']::text[],false,'{"seq":1,"concept":"SC3-2-u4-C15","difficulty":1,"kind":"mc","stem":"학교에서 두 친구가 발견한 문제점은 무엇인가요?","options":[{"t":"친구들이 감염병 예방 수칙을 잘 지키지 않는다","correct":true},{"t":"급식이 맛없다","mis":"SC3-2-u4-X33"},{"t":"운동장이 좁다","mis":"SC3-2-u4-X33"},{"t":"숙제가 많다","mis":"SC3-2-u4-X33"}],"explanation":["학교에서 본 모습이에요.","손을 대충 씻었어요.","수칙을 잘 지키지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_basic#2','sci',3,2,'u4','L07','g3_2_sci_u4_L07_basic','lesson_basic','SC3-2-u4-C16',1,'sa','auto','정해진 기간 동안 실천한 결과를 매일 쓰는 것을 「실천 ○○○」이라고 해요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u4-C16","difficulty":1,"kind":"sa","stem":"정해진 기간 동안 실천한 결과를 매일 쓰는 것을 「실천 ○○○」이라고 해요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["기록장"],"explanation":["매일 써요.","기◯◯이에요.","기록장이에요."],"mis":"SC3-2-u4-X35"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_basic#3','sci',3,2,'u4','L07','g3_2_sci_u4_L07_basic','lesson_basic','SC3-2-u4-C16',1,'ox','auto','수칙을 못 지킨 친구는 지적하고 비난해야 해요.',ARRAY['SC3-2-u4-X34']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C16","difficulty":1,"kind":"ox","stem":"수칙을 못 지킨 친구는 지적하고 비난해야 해요.","answer":"X","reason_options":[{"t":"못 지킨 까닭을 찾고 고쳐 나가도록 서로 격려해야 하기 때문에","correct":true},{"t":"비난해야 다음에 잘 지키기 때문에","mis":"SC3-2-u4-X34"}],"mis":"SC3-2-u4-X34","explanation":["친구를 돕는 방법이에요.","격려해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_basic#4','sci',3,2,'u4','L07','g3_2_sci_u4_L07_basic','lesson_basic','SC3-2-u4-C16',1,'mc','auto','실천 기록장은 언제 쓰나요?',ARRAY['SC3-2-u4-X35','SC3-2-u4-X36']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C16","difficulty":1,"kind":"mc","stem":"실천 기록장은 언제 쓰나요?","options":[{"t":"실천한 결과를 매일 쓴다","correct":true},{"t":"마지막 날에 한 번에 몰아 쓴다","mis":"SC3-2-u4-X35"},{"t":"쓰지 않아도 된다","mis":"SC3-2-u4-X35"},{"t":"친구가 대신 쓴다","mis":"SC3-2-u4-X36"}],"explanation":["꾸준히 실천해요.","하교 전에 써요.","매일 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_basic#5','sci',3,2,'u4','L07','g3_2_sci_u4_L07_basic','lesson_basic','SC3-2-u4-C15',2,'match','auto','계획 칸과 예시를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u4-C15","difficulty":2,"kind":"match","stem":"계획 칸과 예시를 알맞게 이으세요.","pairs":[{"l":"실천 장소","r":"학교 안"},{"l":"실천할 수칙","r":"다른 사람이 먹던 음식 먹지 않기"},{"l":"돕는 방법","r":"서로 확인하고 격려하기"}],"mis":"SC3-2-u4-X33","explanation":["칸 이름을 봐요.","장소는 어디에서예요.","장소-학교 안, 수칙-음식, 돕는 방법-격려예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_basic#6','sci',3,2,'u4','L07','g3_2_sci_u4_L07_basic','lesson_basic','SC3-2-u4-C15',2,'mc','auto','구체적인 수칙은 무엇인가요?',ARRAY['SC3-2-u4-X33']::text[],false,'{"seq":6,"concept":"SC3-2-u4-C15","difficulty":2,"kind":"mc","stem":"구체적인 수칙은 무엇인가요?","options":[{"t":"흐르는 물에 비누로 30초 이상 손 씻기","correct":true},{"t":"손 씻기","mis":"SC3-2-u4-X33"},{"t":"건강하게 지내기","mis":"SC3-2-u4-X33"},{"t":"조심하기","mis":"SC3-2-u4-X33"}],"explanation":["무엇을 어떻게 할지 봐요.","행동이 자세해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_basic#7','sci',3,2,'u4','L07','g3_2_sci_u4_L07_basic','lesson_basic','SC3-2-u4-C15',2,'mc','auto','어느 모둠의 실천 계획 ㉠에 들어갈 수칙으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X33','SC3-2-u4-X35','SC3-2-u4-X34']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C15","difficulty":2,"kind":"mc","stem":"어느 모둠의 실천 계획 ㉠에 들어갈 수칙으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"비누로 흐르는 물에 30초 이상 손 씻기","correct":true},{"t":"운동장에서 많이 뛰기","mis":"SC3-2-u4-X33"},{"t":"기록장 예쁘게 꾸미기","mis":"SC3-2-u4-X35"},{"t":"못 지킨 친구 이름 적기","mis":"SC3-2-u4-X34"}],"explanation":["문제를 읽어요.","손을 대충 씻었어요.","손 씻기 수칙이에요."],"asset":{"type":"passage","lines":["문제 — 친구들이 손을 대충 씻고 나와요.","실천 장소 — 학교 안","실천할 수칙 — ㉠","돕는 방법 — 서로 잘 지켰는지 확인하고 격려해요.","기록 — 실천 기록장에 ㉡ 써요."],"title":"어느 모둠의 실천 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_basic#8','sci',3,2,'u4','L07','g3_2_sci_u4_L07_basic','lesson_basic','SC3-2-u4-C15',2,'ox','auto','학교처럼 많은 사람이 모이는 곳에서는 감염병 예방 수칙을 더 잘 지켜야 해요.',ARRAY['SC3-2-u4-X33']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C15","difficulty":2,"kind":"ox","stem":"학교처럼 많은 사람이 모이는 곳에서는 감염병 예방 수칙을 더 잘 지켜야 해요.","answer":"O","reason_options":[{"t":"많은 사람이 함께 있으면 감염병이 퍼지기 쉽기 때문에","correct":true},{"t":"학교에서는 감염병이 옮지 않기 때문에","mis":"SC3-2-u4-X33"}],"mis":"SC3-2-u4-X33","explanation":["많은 사람이 모여요.","퍼지기 쉬워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_basic#9','sci',3,2,'u4','L07','g3_2_sci_u4_L07_basic','lesson_basic','SC3-2-u4-C16',2,'mc','auto','실천하기 어려웠던 수칙이 있을 때 알맞은 태도는 무엇인가요?',ARRAY['SC3-2-u4-X36']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C16","difficulty":2,"kind":"mc","stem":"실천하기 어려웠던 수칙이 있을 때 알맞은 태도는 무엇인가요?","options":[{"t":"까닭을 찾고 고쳐 나간다","correct":true},{"t":"그냥 포기한다","mis":"SC3-2-u4-X36"},{"t":"친구 탓을 한다","mis":"SC3-2-u4-X36"},{"t":"기록을 지어낸다","mis":"SC3-2-u4-X36"}],"explanation":["점검은 더 잘하려고 해요.","까닭을 알면 고칠 수 있어요.","고쳐 나가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_basic#10','sci',3,2,'u4','L07','g3_2_sci_u4_L07_basic','lesson_basic','SC3-2-u4-C15',3,'mc','auto','「비누로 30초 이상 손 씻기, 서로 확인하고 격려하기, 옷소매로 가리고 기침하기, 기록장을 잘 보이는 곳에 붙이기」 가운데 실천을 돕는 방법끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X33']::text[],false,'{"seq":10,"concept":"SC3-2-u4-C15","difficulty":3,"kind":"mc","stem":"「비누로 30초 이상 손 씻기, 서로 확인하고 격려하기, 옷소매로 가리고 기침하기, 기록장을 잘 보이는 곳에 붙이기」 가운데 실천을 돕는 방법끼리 묶은 것은 무엇인가요?","options":[{"t":"서로 확인하고 격려하기, 기록장을 잘 보이는 곳에 붙이기","correct":true},{"t":"비누로 30초 이상 손 씻기, 옷소매로 가리고 기침하기","mis":"SC3-2-u4-X33"},{"t":"비누로 30초 이상 손 씻기, 서로 확인하고 격려하기","mis":"SC3-2-u4-X33"},{"t":"옷소매로 가리고 기침하기, 기록장을 잘 보이는 곳에 붙이기","mis":"SC3-2-u4-X33"}],"explanation":["수칙과 돕는 방법을 나눠요.","격려와 붙이기예요.","두 가지를 묶어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_challenge#1','sci',3,2,'u4','L07','g3_2_sci_u4_L07_challenge','lesson_challenge','SC3-2-u4-C15',2,'sa','auto','어느 모둠의 실천 계획에서 정한 실천 장소를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u4-C15","difficulty":2,"kind":"sa","stem":"어느 모둠의 실천 계획에서 정한 실천 장소를 쓰세요.","answer":["학교 안","학교안","학교"],"explanation":["장소 칸을 읽어요.","어디에서 실천할까요?","학교 안이에요."],"asset":{"type":"passage","lines":["문제 — 친구들이 손을 대충 씻고 나와요.","실천 장소 — 학교 안","실천할 수칙 — ㉠","돕는 방법 — 서로 잘 지켰는지 확인하고 격려해요.","기록 — 실천 기록장에 ㉡ 써요."],"title":"어느 모둠의 실천 계획"},"mis":"SC3-2-u4-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_challenge#2','sci',3,2,'u4','L07','g3_2_sci_u4_L07_challenge','lesson_challenge','SC3-2-u4-C16',2,'mc','auto','어느 모둠의 실천 계획 ㉡에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u4-X35','SC3-2-u4-X36']::text[],false,'{"seq":2,"concept":"SC3-2-u4-C16","difficulty":2,"kind":"mc","stem":"어느 모둠의 실천 계획 ㉡에 알맞은 말은 무엇인가요?","options":[{"t":"매일","correct":true},{"t":"마지막 날에 한 번","mis":"SC3-2-u4-X35"},{"t":"생각날 때만","mis":"SC3-2-u4-X35"},{"t":"친구가 대신","mis":"SC3-2-u4-X36"}],"explanation":["기록 칸이에요.","꾸준히 써요.","매일이에요."],"asset":{"type":"passage","lines":["문제 — 친구들이 손을 대충 씻고 나와요.","실천 장소 — 학교 안","실천할 수칙 — ㉠","돕는 방법 — 서로 잘 지켰는지 확인하고 격려해요.","기록 — 실천 기록장에 ㉡ 써요."],"title":"어느 모둠의 실천 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_challenge#3','sci',3,2,'u4','L07','g3_2_sci_u4_L07_challenge','lesson_challenge','SC3-2-u4-C16',3,'error','auto','실천 기록장 스스로 점검을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u4-X36','SC3-2-u4-X35']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C16","difficulty":3,"kind":"error","stem":"실천 기록장 스스로 점검을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「대충 씻은 날이 있으니 기록장은 이제 그만 쓰자.」","correct":true,"mis_target":"SC3-2-u4-X36"},{"t":"친구 나 — 「쉬는 시간이 짧은 게 까닭이니 미리 줄을 서 보자.」","mis":"SC3-2-u4-X36"},{"t":"친구 다 — 「급식 전에 잘 씻은 것은 칭찬할 점이야.」","mis":"SC3-2-u4-X35"}],"explanation":["어려웠던 점을 봐요.","포기해야 할까요?","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["잘한 점 — 급식 먹기 전에 손을 잘 씻었어요.","어려웠던 점 — 쉬는 시간이 짧아 손을 대충 씻었어요.","고칠 점 — ㉠","친구 응원 — 「내일은 꼭 30초 씻어 보자!」"],"title":"실천 기록장 스스로 점검"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_challenge#4','sci',3,2,'u4','L07','g3_2_sci_u4_L07_challenge','lesson_challenge','SC3-2-u4-C16',3,'mc','auto','실천 기록장 스스로 점검의 ㉠에 들어갈 고칠 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X36','SC3-2-u4-X34']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C16","difficulty":3,"kind":"mc","stem":"실천 기록장 스스로 점검의 ㉠에 들어갈 고칠 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"쉬는 시간 시작하자마자 손을 씻으러 가서 30초 이상 씻기","correct":true},{"t":"손 씻기는 어려우니 그만하기","mis":"SC3-2-u4-X36"},{"t":"대충 씻은 날도 잘 씻었다고 적기","mis":"SC3-2-u4-X36"},{"t":"손을 대충 씻는 친구 이름 적어 두기","mis":"SC3-2-u4-X34"}],"explanation":["어려웠던 까닭을 봐요.","시간이 짧았어요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["잘한 점 — 급식 먹기 전에 손을 잘 씻었어요.","어려웠던 점 — 쉬는 시간이 짧아 손을 대충 씻었어요.","고칠 점 — ㉠","친구 응원 — 「내일은 꼭 30초 씻어 보자!」"],"title":"실천 기록장 스스로 점검"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_challenge#5','sci',3,2,'u4','L07','g3_2_sci_u4_L07_challenge','lesson_challenge','SC3-2-u4-C16',3,'mc','auto','공유한 실천 결과를 평가할 기준으로 알맞지 않은 것은 무엇인가요?',ARRAY['SC3-2-u4-X35']::text[],false,'{"seq":5,"concept":"SC3-2-u4-C16","difficulty":3,"kind":"mc","stem":"공유한 실천 결과를 평가할 기준으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"기록장을 가장 화려하게 꾸몄나요?","correct":true},{"t":"실천의 중요성을 알고 있나요?","mis":"SC3-2-u4-X35"},{"t":"매일 꾸준히 실천하고 기록했나요?","mis":"SC3-2-u4-X35"},{"t":"느낀 점을 잘 표현했나요?","mis":"SC3-2-u4-X35"}],"explanation":["꾸미기보다 실천이에요.","화려함은 기준이 아니에요.","꾸미기 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_challenge#6','sci',3,2,'u4','L07','g3_2_sci_u4_L07_challenge','lesson_challenge','SC3-2-u4-C15',3,'mc','auto','「쉬는 시간마다 창문을 열어 환기해요, 친구가 먹던 음식을 나눠 먹어요, 오래된 우유는 마시지 않아요, 코를 푼 휴지를 책상 위에 둬요」 가운데 교실에서 실천할 수 있는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X30']::text[],false,'{"seq":6,"concept":"SC3-2-u4-C15","difficulty":3,"kind":"mc","stem":"「쉬는 시간마다 창문을 열어 환기해요, 친구가 먹던 음식을 나눠 먹어요, 오래된 우유는 마시지 않아요, 코를 푼 휴지를 책상 위에 둬요」 가운데 교실에서 실천할 수 있는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"쉬는 시간마다 창문을 열어 환기해요, 오래된 우유는 마시지 않아요","correct":true},{"t":"친구가 먹던 음식을 나눠 먹어요, 코를 푼 휴지를 책상 위에 둬요","mis":"SC3-2-u4-X30"},{"t":"쉬는 시간마다 창문을 열어 환기해요, 코를 푼 휴지를 책상 위에 둬요","mis":"SC3-2-u4-X30"},{"t":"친구가 먹던 음식을 나눠 먹어요, 오래된 우유는 마시지 않아요","mis":"SC3-2-u4-X30"}],"explanation":["감염을 막는 행동이에요.","휴지는 휴지통에 버려요.","환기와 우유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_challenge#7','sci',3,2,'u4','L07','g3_2_sci_u4_L07_challenge','lesson_challenge','SC3-2-u4-C16',3,'ox','auto','예방 수칙은 하루만 잘 지키면 충분해요.',ARRAY['SC3-2-u4-X35']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C16","difficulty":3,"kind":"ox","stem":"예방 수칙은 하루만 잘 지키면 충분해요.","answer":"X","reason_options":[{"t":"정해진 기간 동안 매일 꾸준히 실천해야 하기 때문에","correct":true},{"t":"하루만 지켜도 감염병이 모두 사라지기 때문에","mis":"SC3-2-u4-X35"}],"mis":"SC3-2-u4-X35","explanation":["실천 기간을 떠올려요.","매일 꾸준히예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_challenge#8','sci',3,2,'u4','L07','g3_2_sci_u4_L07_challenge','lesson_challenge','SC3-2-u4-C15',4,'mc','auto','모둠 계획의 실천할 수칙을 「기침 예절 지키기」라고 썼어요. 가장 알맞게 고친 것은 무엇인가요?',ARRAY['SC3-2-u4-X33','SC3-2-u4-X34']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C15","difficulty":4,"kind":"mc","stem":"모둠 계획의 실천할 수칙을 「기침 예절 지키기」라고 썼어요. 가장 알맞게 고친 것은 무엇인가요?","options":[{"t":"「기침할 때는 옷소매로 입과 코를 가려요.」","correct":true},{"t":"「기침하지 않기」","mis":"SC3-2-u4-X33"},{"t":"「기침을 조심하기」","mis":"SC3-2-u4-X33"},{"t":"「기침하는 친구를 혼내기」","mis":"SC3-2-u4-X34"}],"explanation":["무엇을 어떻게 할지 써요.","행동이 드러나야 해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_challenge#9','sci',3,2,'u4','L07','g3_2_sci_u4_L07_challenge','lesson_challenge','SC3-2-u4-C16',4,'mc','auto','친구가 실천 결과를 나누며 「나는 오늘 손을 대충 씻었어.」라고 했어요. 응원 댓글로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X34','SC3-2-u4-X36']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C16","difficulty":4,"kind":"mc","stem":"친구가 실천 결과를 나누며 「나는 오늘 손을 대충 씻었어.」라고 했어요. 응원 댓글로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「솔직하게 말해 줘서 고마워. 까닭을 찾아 내일은 30초 씻어 보자!」","correct":true},{"t":"「그것도 못 지키니? 정말 실망이야.」","mis":"SC3-2-u4-X34"},{"t":"「어차피 안 되니 그냥 포기해.」","mis":"SC3-2-u4-X36"},{"t":"「기록장에는 잘 씻었다고 적어 둬.」","mis":"SC3-2-u4-X36"}],"explanation":["격려하는 말이에요.","고쳐 나가도록 도와요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L07_challenge#10','sci',3,2,'u4','L07','g3_2_sci_u4_L07_challenge','lesson_challenge','SC3-2-u4-C15',4,'essay','teacher','학교 안에서 실천할 감염병 예방 수칙 계획을 실천 장소, 구체적인 수칙, 실천을 돕는 방법이 드러나게 쓰고, 친구가 수칙을 못 지켰을 때 할 일을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u4-C15","difficulty":4,"kind":"essay","stem":"학교 안에서 실천할 감염병 예방 수칙 계획을 실천 장소, 구체적인 수칙, 실천을 돕는 방법이 드러나게 쓰고, 친구가 수칙을 못 지켰을 때 할 일을 쓰세요.","answer_guide":{"answer":"예: 실천 장소는 학교 안이다. 실천할 수칙은 「흐르는 물에 비누로 30초 이상 손 씻기」이다. 실천을 돕는 방법은 모둠원끼리 서로 잘 지켰는지 확인하고 격려하는 것이다. 친구가 수칙을 못 지켰을 때는 비난하지 않고 까닭을 함께 찾아 고쳐 나가도록 응원한다.","scoring_points":["실천 장소를 썼는가","구체적인 수칙과 돕는 방법을 썼는가","비난하지 않고 격려하는 태도를 썼는가"]},"explanation":["계획 칸을 떠올려요.","구체적으로 써요.","격려를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_basic#1','sci',3,2,'u4','L08','g3_2_sci_u4_L08_basic','lesson_basic','SC3-2-u4-C17',1,'mc','auto','세계 손 씻기의 날은 언제인가요?',ARRAY['SC3-2-u4-X37']::text[],false,'{"seq":1,"concept":"SC3-2-u4-C17","difficulty":1,"kind":"mc","stem":"세계 손 씻기의 날은 언제인가요?","options":[{"t":"매년 10월 15일","correct":true},{"t":"매년 3월 1일","mis":"SC3-2-u4-X37"},{"t":"매년 5월 5일","mis":"SC3-2-u4-X37"},{"t":"매년 12월 25일","mis":"SC3-2-u4-X37"}],"explanation":["가을에 있어요.","10월이에요.","10월 15일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_basic#2','sci',3,2,'u4','L08','g3_2_sci_u4_L08_basic','lesson_basic','SC3-2-u4-C18',1,'sa','auto','손 씻기 6단계에서 1단계에 문지르는 곳을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u4-C18","difficulty":1,"kind":"sa","stem":"손 씻기 6단계에서 1단계에 문지르는 곳을 세 글자로 쓰세요.","answer":["손바닥"],"explanation":["1단계를 읽어요.","마주 대고 문질러요.","손바닥이에요."],"asset":{"type":"passage","lines":["1단계 손바닥 — 손바닥을 마주 대고 문질러요.","2단계 손등 — 손등과 손바닥을 마주 대고 문질러요.","3단계 ㉠ — 손깍지를 끼고 문질러요.","4단계 두 손 모아 — 손가락을 마주 잡고 문질러요.","5단계 엄지손가락 — 엄지손가락을 돌려 가며 문질러요.","6단계 ㉡ — 손가락을 손바닥에 놓고 문질러요."],"title":"손 씻기 6단계"},"mis":"SC3-2-u4-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_basic#3','sci',3,2,'u4','L08','g3_2_sci_u4_L08_basic','lesson_basic','SC3-2-u4-C17',1,'ox','auto','감염병 예방 방법 중 가장 간단하면서도 효과적인 방법은 손 씻기예요.',ARRAY['SC3-2-u4-X37']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C17","difficulty":1,"kind":"ox","stem":"감염병 예방 방법 중 가장 간단하면서도 효과적인 방법은 손 씻기예요.","answer":"O","reason_options":[{"t":"올바른 손 씻기만으로도 많은 감염병을 예방할 수 있기 때문에","correct":true},{"t":"손 씻기는 감염병과 상관없기 때문에","mis":"SC3-2-u4-X37"}],"mis":"SC3-2-u4-X37","explanation":["세계 손 씻기의 날을 떠올려요.","과학자들이 강조해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_basic#4','sci',3,2,'u4','L08','g3_2_sci_u4_L08_basic','lesson_basic','SC3-2-u4-C17',1,'mc','auto','손을 반드시 씻어야 하는 때는 무엇인가요?',ARRAY['SC3-2-u4-X38']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C17","difficulty":1,"kind":"mc","stem":"손을 반드시 씻어야 하는 때는 무엇인가요?","options":[{"t":"화장실을 사용한 뒤","correct":true},{"t":"잠에서 깨어 기지개를 켠 뒤","mis":"SC3-2-u4-X38"},{"t":"창밖을 바라본 뒤","mis":"SC3-2-u4-X38"},{"t":"노래를 들은 뒤","mis":"SC3-2-u4-X38"}],"explanation":["병원체가 묻을 수 있는 때예요.","화장실을 떠올려요.","화장실을 사용한 뒤예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_basic#5','sci',3,2,'u4','L08','g3_2_sci_u4_L08_basic','lesson_basic','SC3-2-u4-C18',2,'mc','auto','손 씻기 6단계의 ㉠과 ㉡에 알맞은 말을 차례대로 쓴 것은 무엇인가요?',ARRAY['SC3-2-u4-X39','SC3-2-u4-X40']::text[],false,'{"seq":5,"concept":"SC3-2-u4-C18","difficulty":2,"kind":"mc","stem":"손 씻기 6단계의 ㉠과 ㉡에 알맞은 말을 차례대로 쓴 것은 무엇인가요?","options":[{"t":"손가락 사이, 손톱 밑","correct":true},{"t":"손톱 밑, 손가락 사이","mis":"SC3-2-u4-X39"},{"t":"손등, 엄지손가락","mis":"SC3-2-u4-X39"},{"t":"손목, 팔꿈치","mis":"SC3-2-u4-X40"}],"explanation":["3단계는 손깍지예요.","6단계는 손톱이에요.","손가락 사이, 손톱 밑이에요."],"asset":{"type":"passage","lines":["1단계 손바닥 — 손바닥을 마주 대고 문질러요.","2단계 손등 — 손등과 손바닥을 마주 대고 문질러요.","3단계 ㉠ — 손깍지를 끼고 문질러요.","4단계 두 손 모아 — 손가락을 마주 잡고 문질러요.","5단계 엄지손가락 — 엄지손가락을 돌려 가며 문질러요.","6단계 ㉡ — 손가락을 손바닥에 놓고 문질러요."],"title":"손 씻기 6단계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_basic#6','sci',3,2,'u4','L08','g3_2_sci_u4_L08_basic','lesson_basic','SC3-2-u4-C18',2,'match','auto','손 씻기 단계와 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u4-C18","difficulty":2,"kind":"match","stem":"손 씻기 단계와 방법을 알맞게 이으세요.","pairs":[{"l":"1단계","r":"손바닥을 마주 대고 문질러요"},{"l":"3단계","r":"손깍지를 끼고 문질러요"},{"l":"6단계","r":"손톱 밑을 문질러요"}],"mis":"SC3-2-u4-X39","explanation":["6단계를 다시 봐요.","처음은 손바닥, 마지막은 손톱 밑이에요.","1-손바닥, 3-손깍지, 6-손톱 밑이에요."],"asset":{"type":"passage","lines":["1단계 손바닥 — 손바닥을 마주 대고 문질러요.","2단계 손등 — 손등과 손바닥을 마주 대고 문질러요.","3단계 ㉠ — 손깍지를 끼고 문질러요.","4단계 두 손 모아 — 손가락을 마주 잡고 문질러요.","5단계 엄지손가락 — 엄지손가락을 돌려 가며 문질러요.","6단계 ㉡ — 손가락을 손바닥에 놓고 문질러요."],"title":"손 씻기 6단계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_basic#7','sci',3,2,'u4','L08','g3_2_sci_u4_L08_basic','lesson_basic','SC3-2-u4-C17',2,'mc','auto','세계 손 씻기의 날을 정한 까닭은 무엇인가요?',ARRAY['SC3-2-u4-X37']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C17","difficulty":2,"kind":"mc","stem":"세계 손 씻기의 날을 정한 까닭은 무엇인가요?","options":[{"t":"손 씻기의 중요성을 알리려고","correct":true},{"t":"비누를 많이 팔려고","mis":"SC3-2-u4-X37"},{"t":"물을 아끼려고","mis":"SC3-2-u4-X37"},{"t":"손을 쉬게 하려고","mis":"SC3-2-u4-X37"}],"explanation":["기념일로 알리려 했어요.","손 씻기가 중요해요.","중요성을 알리려고요."],"asset":{"type":"passage","lines":["날짜 — 매년 10월 15일","정한 곳 — 국제 연합 총회","까닭 — 손 씻기의 중요성을 알리려고","과학자들 — 올바른 손 씻기로 많은 감염병을 예방할 수 있어요."],"title":"세계 손 씻기의 날 알아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_basic#8','sci',3,2,'u4','L08','g3_2_sci_u4_L08_basic','lesson_basic','SC3-2-u4-C17',2,'ox','auto','세계 손 씻기의 날에만 손을 잘 씻으면 돼요.',ARRAY['SC3-2-u4-X37']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C17","difficulty":2,"kind":"ox","stem":"세계 손 씻기의 날에만 손을 잘 씻으면 돼요.","answer":"X","reason_options":[{"t":"이날은 중요성을 알리려고 정한 날이고, 손 씻기는 매일 실천해야 하기 때문에","correct":true},{"t":"하루만 씻어도 일 년 내내 깨끗하기 때문에","mis":"SC3-2-u4-X37"}],"mis":"SC3-2-u4-X37","explanation":["왜 정한 날일까요?","매일 실천해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_basic#9','sci',3,2,'u4','L08','g3_2_sci_u4_L08_basic','lesson_basic','SC3-2-u4-C17',2,'mc','auto','음식과 관련된 때에 손을 씻는 경우는 무엇인가요?',ARRAY['SC3-2-u4-X38']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C17","difficulty":2,"kind":"mc","stem":"음식과 관련된 때에 손을 씻는 경우는 무엇인가요?","options":[{"t":"식사 전","correct":true},{"t":"코를 푼 뒤","mis":"SC3-2-u4-X38"},{"t":"재채기를 한 뒤","mis":"SC3-2-u4-X38"},{"t":"쓰레기를 만진 뒤","mis":"SC3-2-u4-X38"}],"explanation":["음식을 먹거나 만드는 때예요.","밥 먹기 전이에요.","식사 전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_basic#10','sci',3,2,'u4','L08','g3_2_sci_u4_L08_basic','lesson_basic','SC3-2-u4-C18',3,'mc','auto','올바르게 손을 씻은 것은 무엇인가요?',ARRAY['SC3-2-u4-X27','SC3-2-u4-X40']::text[],false,'{"seq":10,"concept":"SC3-2-u4-C18","difficulty":3,"kind":"mc","stem":"올바르게 손을 씻은 것은 무엇인가요?","options":[{"t":"비누로 흐르는 물에 30초 이상, 손톱 밑까지 씻었다","correct":true},{"t":"물만 묻히고 끝냈다","mis":"SC3-2-u4-X27"},{"t":"손바닥만 문질렀다","mis":"SC3-2-u4-X40"},{"t":"엄지손가락과 손톱 밑은 빼고 씻었다","mis":"SC3-2-u4-X40"}],"explanation":["6단계를 모두 했는지 봐요.","비누와 30초가 중요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_challenge#1','sci',3,2,'u4','L08','g3_2_sci_u4_L08_challenge','lesson_challenge','SC3-2-u4-C17',2,'sa','auto','세계 손 씻기의 날 알아보기에서 이날을 정한 곳을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u4-C17","difficulty":2,"kind":"sa","stem":"세계 손 씻기의 날 알아보기에서 이날을 정한 곳을 쓰세요.","answer":["국제 연합 총회","국제연합총회","국제 연합"],"explanation":["정한 곳 칸을 읽어요.","여러 나라가 모였어요.","국제 연합 총회예요."],"asset":{"type":"passage","lines":["날짜 — 매년 10월 15일","정한 곳 — 국제 연합 총회","까닭 — 손 씻기의 중요성을 알리려고","과학자들 — 올바른 손 씻기로 많은 감염병을 예방할 수 있어요."],"title":"세계 손 씻기의 날 알아보기"},"mis":"SC3-2-u4-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_challenge#2','sci',3,2,'u4','L08','g3_2_sci_u4_L08_challenge','lesson_challenge','SC3-2-u4-C18',2,'mc','auto','손 씻기 6단계에서 4단계 「두 손 모아」 다음에 하는 단계는 무엇인가요?',ARRAY['SC3-2-u4-X39']::text[],false,'{"seq":2,"concept":"SC3-2-u4-C18","difficulty":2,"kind":"mc","stem":"손 씻기 6단계에서 4단계 「두 손 모아」 다음에 하는 단계는 무엇인가요?","options":[{"t":"엄지손가락을 돌려 가며 문지른다","correct":true},{"t":"손바닥을 마주 대고 문지른다","mis":"SC3-2-u4-X39"},{"t":"손톱 밑을 문지른다","mis":"SC3-2-u4-X39"},{"t":"손등을 문지른다","mis":"SC3-2-u4-X39"}],"explanation":["차례를 떠올려요.","5단계예요.","엄지손가락이에요."],"asset":{"type":"passage","lines":["1단계 손바닥 — 손바닥을 마주 대고 문질러요.","2단계 손등 — 손등과 손바닥을 마주 대고 문질러요.","3단계 ㉠ — 손깍지를 끼고 문질러요.","4단계 두 손 모아 — 손가락을 마주 잡고 문질러요.","5단계 엄지손가락 — 엄지손가락을 돌려 가며 문질러요.","6단계 ㉡ — 손가락을 손바닥에 놓고 문질러요."],"title":"손 씻기 6단계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_challenge#3','sci',3,2,'u4','L08','g3_2_sci_u4_L08_challenge','lesson_challenge','SC3-2-u4-C18',3,'error','auto','세계 손 씻기의 날에 손을 씻은 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u4-X40','SC3-2-u4-X27','SC3-2-u4-X39']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C18","difficulty":3,"kind":"error","stem":"세계 손 씻기의 날에 손을 씻은 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「손톱 밑은 잘 안 보이니까 빼고 씻어도 돼.」","correct":true,"mis_target":"SC3-2-u4-X40"},{"t":"친구 가 — 「비누를 쓰고 흐르는 물에 씻었어.」","mis":"SC3-2-u4-X27"},{"t":"친구 다 — 「손바닥부터 손톱 밑까지 차례로 문질렀어.」","mis":"SC3-2-u4-X39"}],"explanation":["6단계를 모두 떠올려요.","손톱 밑도 씻어요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_challenge#4','sci',3,2,'u4','L08','g3_2_sci_u4_L08_challenge','lesson_challenge','SC3-2-u4-C17',3,'mc','auto','「식사 전, 코를 푼 뒤, 음식을 할 때, 재채기를 한 뒤」를 「기침이나 코와 관련된 때인가?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X38']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C17","difficulty":3,"kind":"mc","stem":"「식사 전, 코를 푼 뒤, 음식을 할 때, 재채기를 한 뒤」를 「기침이나 코와 관련된 때인가?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"코를 푼 뒤, 재채기를 한 뒤","correct":true},{"t":"식사 전, 음식을 할 때","mis":"SC3-2-u4-X38"},{"t":"식사 전, 코를 푼 뒤","mis":"SC3-2-u4-X38"},{"t":"음식을 할 때, 재채기를 한 뒤","mis":"SC3-2-u4-X38"}],"explanation":["코와 기침을 찾아요.","음식은 빼요.","코 풀기와 재채기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_challenge#5','sci',3,2,'u4','L08','g3_2_sci_u4_L08_challenge','lesson_challenge','SC3-2-u4-C18',3,'mc','auto','손 씻기 6단계를 차례대로 바르게 늘어놓은 것은 무엇인가요?',ARRAY['SC3-2-u4-X39','SC3-2-u4-X40']::text[],false,'{"seq":5,"concept":"SC3-2-u4-C18","difficulty":3,"kind":"mc","stem":"손 씻기 6단계를 차례대로 바르게 늘어놓은 것은 무엇인가요?","options":[{"t":"손바닥 → 손등 → 손가락 사이 → 두 손 모아 → 엄지손가락 → 손톱 밑","correct":true},{"t":"손톱 밑 → 엄지손가락 → 두 손 모아 → 손가락 사이 → 손등 → 손바닥","mis":"SC3-2-u4-X39"},{"t":"손바닥 → 손톱 밑 → 손등 → 엄지손가락 → 두 손 모아 → 손가락 사이","mis":"SC3-2-u4-X39"},{"t":"손바닥 → 손등 → 손톱 밑","mis":"SC3-2-u4-X40"}],"explanation":["처음은 손바닥이에요.","마지막은 손톱 밑이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_challenge#6','sci',3,2,'u4','L08','g3_2_sci_u4_L08_challenge','lesson_challenge','SC3-2-u4-C17',3,'ox','auto','손이 깨끗해 보이면 동물을 만진 뒤에도 씻지 않아도 돼요.',ARRAY['SC3-2-u4-X38']::text[],false,'{"seq":6,"concept":"SC3-2-u4-C17","difficulty":3,"kind":"ox","stem":"손이 깨끗해 보이면 동물을 만진 뒤에도 씻지 않아도 돼요.","answer":"X","reason_options":[{"t":"깨끗해 보여도 손에 병원체가 묻어 있을 수 있기 때문에","correct":true},{"t":"눈에 보이지 않는 것은 없는 것이기 때문에","mis":"SC3-2-u4-X38"}],"mis":"SC3-2-u4-X38","explanation":["동물을 만진 뒤예요.","보이지 않아도 있을 수 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_challenge#7','sci',3,2,'u4','L08','g3_2_sci_u4_L08_challenge','lesson_challenge','SC3-2-u4-C17',3,'mc','auto','손을 반드시 씻어야 하는 때끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X37','SC3-2-u4-X38']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C17","difficulty":3,"kind":"mc","stem":"손을 반드시 씻어야 하는 때끼리 묶은 것은 무엇인가요?","options":[{"t":"화장실을 사용한 뒤, 쓰레기를 만진 뒤, 동물을 만진 뒤","correct":true},{"t":"화장실을 사용한 뒤, 세계 손 씻기의 날에만","mis":"SC3-2-u4-X37"},{"t":"손이 깨끗해 보일 때는 빼고 쓰레기를 만진 뒤만","mis":"SC3-2-u4-X38"},{"t":"세계 손 씻기의 날에만","mis":"SC3-2-u4-X37"}],"explanation":["병원체가 묻을 수 있는 때예요.","매일 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_challenge#8','sci',3,2,'u4','L08','g3_2_sci_u4_L08_challenge','lesson_challenge','SC3-2-u4-C17',4,'mc','auto','친구가 「손을 씻는 건 귀찮으니까 물만 살짝 묻힐래.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-2-u4-X27','SC3-2-u4-X37','SC3-2-u4-X40']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C17","difficulty":4,"kind":"mc","stem":"친구가 「손을 씻는 건 귀찮으니까 물만 살짝 묻힐래.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「손 씻기는 간단하면서도 효과적인 예방 방법이야. 비누로 흐르는 물에 30초 이상 6단계로 씻자.」","correct":true},{"t":"「맞아, 물만 묻혀도 병원체가 다 없어져.」","mis":"SC3-2-u4-X27"},{"t":"「세계 손 씻기의 날에만 제대로 씻으면 돼.」","mis":"SC3-2-u4-X37"},{"t":"「손바닥만 문지르면 6단계를 다 한 거야.」","mis":"SC3-2-u4-X40"}],"explanation":["올바른 손 씻기를 떠올려요.","비누, 흐르는 물, 30초예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_challenge#9','sci',3,2,'u4','L08','g3_2_sci_u4_L08_challenge','lesson_challenge','SC3-2-u4-C18',4,'mc','auto','손 씻기 6단계 가운데 손가락 사이를 씻는 단계와 그 방법을 바르게 이은 것은 무엇인가요?',ARRAY['SC3-2-u4-X39']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C18","difficulty":4,"kind":"mc","stem":"손 씻기 6단계 가운데 손가락 사이를 씻는 단계와 그 방법을 바르게 이은 것은 무엇인가요?","options":[{"t":"3단계 — 손바닥을 마주 대고 손깍지를 끼고 문지른다","correct":true},{"t":"1단계 — 손톱 밑을 문지른다","mis":"SC3-2-u4-X39"},{"t":"6단계 — 손등과 손바닥을 마주 대고 문지른다","mis":"SC3-2-u4-X39"},{"t":"5단계 — 손가락을 마주 잡고 문지른다","mis":"SC3-2-u4-X39"}],"explanation":["손깍지를 떠올려요.","세 번째 단계예요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["1단계 손바닥 — 손바닥을 마주 대고 문질러요.","2단계 손등 — 손등과 손바닥을 마주 대고 문질러요.","3단계 ㉠ — 손깍지를 끼고 문질러요.","4단계 두 손 모아 — 손가락을 마주 잡고 문질러요.","5단계 엄지손가락 — 엄지손가락을 돌려 가며 문질러요.","6단계 ㉡ — 손가락을 손바닥에 놓고 문질러요."],"title":"손 씻기 6단계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_L08_challenge#10','sci',3,2,'u4','L08','g3_2_sci_u4_L08_challenge','lesson_challenge','SC3-2-u4-C17',4,'essay','teacher','세계 손 씻기의 날을 정한 까닭을 쓰고, 손을 씻어야 하는 때를 두 가지 쓰세요. 그리고 올바른 손 씻기 방법을 비누, 흐르는 물, 시간이 드러나게 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u4-C17","difficulty":4,"kind":"essay","stem":"세계 손 씻기의 날을 정한 까닭을 쓰고, 손을 씻어야 하는 때를 두 가지 쓰세요. 그리고 올바른 손 씻기 방법을 비누, 흐르는 물, 시간이 드러나게 쓰세요.","answer_guide":{"answer":"예: 세계 손 씻기의 날은 손 씻기의 중요성을 알리려고 정한 날이다. 식사 전과 화장실을 사용한 뒤에는 손을 씻어야 한다. 손은 비누를 사용해 흐르는 물에 30초 이상 손바닥부터 손톱 밑까지 6단계로 꼼꼼히 씻는다.","scoring_points":["세계 손 씻기의 날을 정한 까닭을 썼는가","손을 씻어야 하는 때 두 가지를 썼는가","비누·흐르는 물·30초가 드러나게 손 씻기 방법을 썼는가"]},"explanation":["까닭부터 써요.","때를 두 가지 써요.","방법을 써요."],"asset":{"type":"passage","lines":["날짜 — 매년 10월 15일","정한 곳 — 국제 연합 총회","까닭 — 손 씻기의 중요성을 알리려고","과학자들 — 올바른 손 씻기로 많은 감염병을 예방할 수 있어요."],"title":"세계 손 씻기의 날 알아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#1','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C1',1,'mc','auto','다솜반 일지 ①에서 색칠을 마치고 나타난 친구는 어떤 모습인가요?',ARRAY['SC3-2-u4-X02']::text[],false,'{"seq":1,"concept":"SC3-2-u4-C1","difficulty":1,"kind":"mc","stem":"다솜반 일지 ①에서 색칠을 마치고 나타난 친구는 어떤 모습인가요?","options":[{"t":"볼이 붉고 콧물이 난다","correct":true},{"t":"웃으며 공을 찬다","mis":"SC3-2-u4-X02"},{"t":"잠을 자고 있다","mis":"SC3-2-u4-X02"},{"t":"노래를 부른다","mis":"SC3-2-u4-X02"}],"explanation":["첫 줄을 읽어요.","볼과 코를 봐요.","볼이 붉고 콧물이 나요."],"asset":{"type":"passage","lines":["숫자에 맞게 칠했더니 볼이 붉고 콧물이 나는 친구가 나타났다.","먼저 다 칠한 친구는 정답을 말하지 않고 기다렸다.","경험 나누기 — 동생에게서 감기가 옮은 적이 있다."],"title":"다솜반 일지 ① 색칠 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#2','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C5',1,'mc','auto','다솜반 일지 ②에서 친구 가가 말한 일은 감염병인가요?',ARRAY['SC3-2-u4-X10','SC3-2-u4-X05']::text[],false,'{"seq":2,"concept":"SC3-2-u4-C5","difficulty":1,"kind":"mc","stem":"다솜반 일지 ②에서 친구 가가 말한 일은 감염병인가요?","options":[{"t":"감염병이 아니다 — 다쳐서 생긴 일이다","correct":true},{"t":"감염병이다 — 많이 아프다","mis":"SC3-2-u4-X10"},{"t":"감염병이다 — 병원에 간다","mis":"SC3-2-u4-X10"},{"t":"알 수 없다","mis":"SC3-2-u4-X05"}],"explanation":["팔이 부러졌어요.","다친 일이에요.","감염병이 아니에요."],"asset":{"type":"passage","lines":["감기, 독감, 수두는 병원체에 감염되어 생기는 병이다.","친구 가 — 「지난주에 넘어져 팔이 부러졌어.」","친구 나 — 「감기가 심해지면 독감이 되는 거야?」","선생님 — 「감기와 독감은 서로 다른 질병이에요.」"],"title":"다솜반 일지 ② 감염병 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#3','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C6',1,'mc','auto','다솜반 일지 ③의 감염병 카드에서 「입안, 손과 발에 물집이 생긴다」는 어느 칸인가요?',ARRAY['SC3-2-u4-X11','SC3-2-u4-X12']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C6","difficulty":1,"kind":"mc","stem":"다솜반 일지 ③의 감염병 카드에서 「입안, 손과 발에 물집이 생긴다」는 어느 칸인가요?","options":[{"t":"증상","correct":true},{"t":"특징","mis":"SC3-2-u4-X11"},{"t":"이름","mis":"SC3-2-u4-X11"},{"t":"출처","mis":"SC3-2-u4-X12"}],"explanation":["앓을 때 나타나는 상태예요.","물집이에요.","증상이에요."],"asset":{"type":"passage","lines":["이름 — 수족구병","증상 — 입안, 손과 발에 물집이 생긴다.","특징 — 분비물 등을 통해 옮는다.","토의 — 누구나 걸릴 수 있고 많은 사람에게 퍼질 수 있다."],"title":"다솜반 일지 ③ 감염병 카드와 토의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#4','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C8',1,'mc','auto','다솜반 일지 ④에서 크게 유행했을 때 놀이터는 어떤 모습이었나요?',ARRAY['SC3-2-u4-X17','SC3-2-u4-X18']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C8","difficulty":1,"kind":"mc","stem":"다솜반 일지 ④에서 크게 유행했을 때 놀이터는 어떤 모습이었나요?","options":[{"t":"사람이 없어 텅 비었다","correct":true},{"t":"사람들로 붐볐다","mis":"SC3-2-u4-X17"},{"t":"새로 지어졌다","mis":"SC3-2-u4-X17"},{"t":"아무것도 달라지지 않았다","mis":"SC3-2-u4-X18"}],"explanation":["둘째 줄을 읽어요.","텅 비었어요.","사람이 없었어요."],"asset":{"type":"passage","lines":["할머니 말씀 — 「크게 유행했을 때 사람들이 모이지 않았단다.」","놀이터 — 사람이 없어 텅 비었다.","도서관 — 문을 닫아 책을 빌리기 어려웠다.","과학자 — 원인을 밝히고 예방하는 방법을 연구했다."],"title":"다솜반 일지 ④ 크게 유행했던 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#5','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C10',1,'mc','auto','다솜반 일지 ⑤의 ㉣은 무엇을 통해 감염될 수 있나요?',ARRAY['SC3-2-u4-X21']::text[],false,'{"seq":5,"concept":"SC3-2-u4-C10","difficulty":1,"kind":"mc","stem":"다솜반 일지 ⑤의 ㉣은 무엇을 통해 감염될 수 있나요?","options":[{"t":"오염된 물","correct":true},{"t":"음식에 묻은 침","mis":"SC3-2-u4-X21"},{"t":"기침할 때 나오는 비말","mis":"SC3-2-u4-X21"},{"t":"같은 공간의 공기","mis":"SC3-2-u4-X21"}],"explanation":["㉣을 읽어요.","물을 확인하지 않았어요.","오염된 물이에요."],"asset":{"type":"passage","lines":["㉠ 운동장에서 놀고 손을 씻지 않은 채 간식을 먹었다.","㉡ 열이 나는데도 사람이 많은 놀이공원에 갔다.","㉢ 기침이 나서 옷소매로 입과 코를 가렸다.","㉣ 여행 중에 확인하지 않은 물을 마셨다."],"title":"다솜반 일지 ⑤ 생활 습관 돌아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#6','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C13',1,'mc','auto','다솜반 일지 ⑥의 노랫말이 알리는 예방 수칙은 무엇인가요?',ARRAY['SC3-2-u4-X31']::text[],false,'{"seq":6,"concept":"SC3-2-u4-C13","difficulty":1,"kind":"mc","stem":"다솜반 일지 ⑥의 노랫말이 알리는 예방 수칙은 무엇인가요?","options":[{"t":"기침할 때 옷소매로 가리기","correct":true},{"t":"손 씻기","mis":"SC3-2-u4-X31"},{"t":"예방접종하기","mis":"SC3-2-u4-X31"},{"t":"음식 익혀 먹기","mis":"SC3-2-u4-X31"}],"explanation":["노랫말을 읽어요.","콜록콜록이에요.","기침 예절이에요."],"asset":{"type":"passage","lines":["노랫말 — 「소매로 가려요, 콜록콜록 기침할 때」","조사 — 믿을 수 있는 누리집에서 찾고 출처를 적었다.","더 넣을 수칙 — 음식은 익혀 먹고 깨끗한 물 마시기"],"title":"다솜반 일지 ⑥ 예방 수칙 노래"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#7','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C16',1,'mc','auto','다솜반 일지 ⑦에서 실천 기록장은 언제 적었나요?',ARRAY['SC3-2-u4-X35','SC3-2-u4-X36']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C16","difficulty":1,"kind":"mc","stem":"다솜반 일지 ⑦에서 실천 기록장은 언제 적었나요?","options":[{"t":"열흘 동안 하교 전에 매일","correct":true},{"t":"마지막 날에 한 번","mis":"SC3-2-u4-X35"},{"t":"생각날 때만","mis":"SC3-2-u4-X35"},{"t":"친구가 대신","mis":"SC3-2-u4-X36"}],"explanation":["둘째 줄을 읽어요.","매일 적었어요.","하교 전에 매일이에요."],"asset":{"type":"passage","lines":["수칙 — 흐르는 물에 비누로 30초 이상 손 씻기","기록 — 열흘 동안 하교 전에 매일 적었다.","반성 — 수요일에 시간이 없어 대충 씻었다.","응원 댓글 — 「까닭을 찾았으니 내일은 잘할 거야!」"],"title":"다솜반 일지 ⑦ 실천 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#8','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C17',1,'mc','auto','다솜반 일지 ⑧에서 손 씻기 6단계를 함께 한 날은 무슨 날인가요?',ARRAY['SC3-2-u4-X37']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C17","difficulty":1,"kind":"mc","stem":"다솜반 일지 ⑧에서 손 씻기 6단계를 함께 한 날은 무슨 날인가요?","options":[{"t":"세계 손 씻기의 날","correct":true},{"t":"어린이날","mis":"SC3-2-u4-X37"},{"t":"한글날","mis":"SC3-2-u4-X37"},{"t":"설날","mis":"SC3-2-u4-X37"}],"explanation":["10월 15일이에요.","손 씻기를 알리는 날이에요.","세계 손 씻기의 날이에요."],"asset":{"type":"passage","lines":["10월 15일에 손 씻기 6단계를 함께 해 보았다.","친구 가는 손톱 밑 문지르기를 빠뜨렸다.","반 다짐 — 「이날만이 아니라 매일 올바르게 씻자.」"],"title":"다솜반 일지 ⑧ 세계 손 씻기의 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#9','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C4',2,'match','auto','감염병과 관련된 경험을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SC3-2-u4-C4","difficulty":2,"kind":"match","stem":"감염병과 관련된 경험을 알맞게 이으세요.","pairs":[{"l":"겨울에 맞은 주사","r":"독감 예방접종"},{"l":"물놀이 뒤 충혈된 눈","r":"유행성 눈병"},{"l":"입안과 손발의 물집","r":"수족구병"}],"mis":"SC3-2-u4-X09","explanation":["경험을 하나씩 떠올려요.","주사는 예방접종이에요.","주사-독감 예방접종, 눈-유행성 눈병, 물집-수족구병이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#10','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C6',2,'match','auto','감염병 카드의 내용과 칸을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u4-C6","difficulty":2,"kind":"match","stem":"감염병 카드의 내용과 칸을 알맞게 이으세요.","pairs":[{"l":"입안, 손과 발에 물집","r":"증상"},{"l":"분비물 등을 통해 옮음","r":"특징"},{"l":"믿을 수 있는 누리집","r":"출처"}],"mis":"SC3-2-u4-X11","explanation":["칸의 뜻을 떠올려요.","물집은 앓을 때 나타나요.","물집-증상, 옮음-특징, 누리집-출처예요."],"asset":{"type":"passage","lines":["이름 — 수족구병","증상 — 입안, 손과 발에 물집이 생긴다.","특징 — 분비물 등을 통해 옮는다.","토의 — 누구나 걸릴 수 있고 많은 사람에게 퍼질 수 있다."],"title":"다솜반 일지 ③ 감염병 카드와 토의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#11','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C9',2,'match','auto','다솜반 일지 ④의 장소와 안전한 사회의 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SC3-2-u4-C9","difficulty":2,"kind":"match","stem":"다솜반 일지 ④의 장소와 안전한 사회의 모습을 알맞게 이으세요.","pairs":[{"l":"놀이터","r":"사람들이 많아져요"},{"l":"도서관","r":"공공시설을 자유롭게 이용해요"},{"l":"식당","r":"여러 사람이 함께 음식을 먹어요"}],"mis":"SC3-2-u4-X17","explanation":["같은 장소의 반대 모습이에요.","도서관은 공공시설이에요.","놀이터-사람 많음, 도서관-자유롭게, 식당-함께 먹기예요."],"asset":{"type":"passage","lines":["할머니 말씀 — 「크게 유행했을 때 사람들이 모이지 않았단다.」","놀이터 — 사람이 없어 텅 비었다.","도서관 — 문을 닫아 책을 빌리기 어려웠다.","과학자 — 원인을 밝히고 예방하는 방법을 연구했다."],"title":"다솜반 일지 ④ 크게 유행했던 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#12','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C10',2,'match','auto','생활 속 상황과 감염될 수 있는 과정을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"SC3-2-u4-C10","difficulty":2,"kind":"match","stem":"생활 속 상황과 감염될 수 있는 과정을 알맞게 이으세요.","pairs":[{"l":"음식을 함께 먹을 때","r":"침을 통해"},{"l":"같은 공간에 있을 때","r":"공기를 통해"},{"l":"확인하지 않은 물을 마실 때","r":"오염된 물을 통해"}],"mis":"SC3-2-u4-X21","explanation":["감염 과정을 떠올려요.","음식은 침이에요.","음식-침, 공간-공기, 물-오염된 물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#13','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C14',2,'match','auto','예방 수칙과 막는 감염을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC3-2-u4-C14","difficulty":2,"kind":"match","stem":"예방 수칙과 막는 감염을 알맞게 이으세요.","pairs":[{"l":"흐르는 물에 비누로 손 씻기","r":"손을 통한 감염"},{"l":"옷소매로 입과 코 가리기","r":"비말을 통한 감염"},{"l":"깨끗한 물 마시기","r":"오염된 물을 통한 감염"}],"mis":"SC3-2-u4-X31","explanation":["수칙마다 막는 것이 달라요.","소매는 비말이에요.","손 씻기-손, 소매-비말, 물-오염된 물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#14','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C15',2,'match','auto','다솜반 모둠의 실천 계획 칸과 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":14,"concept":"SC3-2-u4-C15","difficulty":2,"kind":"match","stem":"다솜반 모둠의 실천 계획 칸과 내용을 알맞게 이으세요.","pairs":[{"l":"실천 장소","r":"학교 안"},{"l":"실천할 수칙","r":"흐르는 물에 비누로 30초 이상 손 씻기"},{"l":"돕는 방법","r":"기록장을 잘 보이는 곳에 붙이기"}],"mis":"SC3-2-u4-X33","explanation":["칸 이름을 봐요.","붙이기는 돕는 방법이에요.","장소-학교 안, 수칙-손 씻기, 돕는 방법-기록장 붙이기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#15','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C17',2,'match','auto','손을 씻어야 할 때와 관련된 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SC3-2-u4-C17","difficulty":2,"kind":"match","stem":"손을 씻어야 할 때와 관련된 것을 알맞게 이으세요.","pairs":[{"l":"식사 전","r":"음식과 관련된 때"},{"l":"코를 푼 뒤","r":"기침이나 코와 관련된 때"},{"l":"쓰레기를 만진 뒤","r":"더러운 것을 만진 때"}],"mis":"SC3-2-u4-X38","explanation":["때를 나눠요.","코 풀기는 코예요.","식사-음식, 코-코, 쓰레기-만진 때예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#16','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C3',2,'match','auto','단원에서 배운 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":16,"concept":"SC3-2-u4-C3","difficulty":2,"kind":"match","stem":"단원에서 배운 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"병원체","r":"세균, 바이러스 등 병의 원인이 되는 본체"},{"l":"증상","r":"병을 앓을 때 나타나는 상태나 모양"},{"l":"비말","r":"기침할 때 나오는 작은 침방울"}],"mis":"SC3-2-u4-X06","explanation":["낱말을 하나씩 떠올려요.","증상은 상태예요.","병원체-본체, 증상-상태, 비말-침방울이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#17','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C4',3,'error','auto','다솜반 일지 ②를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u4-X08','SC3-2-u4-X10','SC3-2-u4-X06']::text[],false,'{"seq":17,"concept":"SC3-2-u4-C4","difficulty":3,"kind":"error","stem":"다솜반 일지 ②를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「친구 나 말처럼 감기가 심해지면 독감이 돼.」","correct":true,"mis_target":"SC3-2-u4-X08"},{"t":"친구 라 — 「친구 가처럼 팔이 부러진 것은 감염병이 아니야.」","mis":"SC3-2-u4-X10"},{"t":"친구 마 — 「수두도 병원체에 감염되어 생겨.」","mis":"SC3-2-u4-X06"}],"explanation":["선생님 말씀을 봐요.","서로 다른 질병이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["감기, 독감, 수두는 병원체에 감염되어 생기는 병이다.","친구 가 — 「지난주에 넘어져 팔이 부러졌어.」","친구 나 — 「감기가 심해지면 독감이 되는 거야?」","선생님 — 「감기와 독감은 서로 다른 질병이에요.」"],"title":"다솜반 일지 ② 감염병 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#18','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C7',3,'error','auto','다솜반 일지 ③을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u4-X14','SC3-2-u4-X13','SC3-2-u4-X11']::text[],false,'{"seq":18,"concept":"SC3-2-u4-C7","difficulty":3,"kind":"error","stem":"다솜반 일지 ③을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「수족구병 증상을 모두 외우면 토의는 안 해도 돼.」","correct":true,"mis_target":"SC3-2-u4-X14"},{"t":"친구 가 — 「분비물로 옮으니 많은 사람이 걸릴 수 있어.」","mis":"SC3-2-u4-X13"},{"t":"친구 다 — 「물집은 증상 칸, 옮는 방법은 특징 칸이 맞아.」","mis":"SC3-2-u4-X11"}],"explanation":["외우기와 토의예요.","무엇이 중요할까요?","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["이름 — 수족구병","증상 — 입안, 손과 발에 물집이 생긴다.","특징 — 분비물 등을 통해 옮는다.","토의 — 누구나 걸릴 수 있고 많은 사람에게 퍼질 수 있다."],"title":"다솜반 일지 ③ 감염병 카드와 토의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#19','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C8',3,'error','auto','다솜반 일지 ④를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u4-X18','SC3-2-u4-X16','SC3-2-u4-X20']::text[],false,'{"seq":19,"concept":"SC3-2-u4-C8","difficulty":3,"kind":"error","stem":"다솜반 일지 ④를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「감기에 걸린 사람이 한 명만 있어도 놀이터는 늘 텅 비어.」","correct":true,"mis_target":"SC3-2-u4-X18"},{"t":"친구 나 — 「크게 유행해서 사람들이 모이지 않았던 거야.」","mis":"SC3-2-u4-X16"},{"t":"친구 다 — 「과학자들은 예방하는 방법을 연구했어.」","mis":"SC3-2-u4-X20"}],"explanation":["언제의 모습일까요?","크게 유행했을 때예요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["할머니 말씀 — 「크게 유행했을 때 사람들이 모이지 않았단다.」","놀이터 — 사람이 없어 텅 비었다.","도서관 — 문을 닫아 책을 빌리기 어려웠다.","과학자 — 원인을 밝히고 예방하는 방법을 연구했다."],"title":"다솜반 일지 ④ 크게 유행했던 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#20','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C10',3,'error','auto','다솜반 일지 ⑤를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u4-X21','SC3-2-u4-X22']::text[],false,'{"seq":20,"concept":"SC3-2-u4-C10","difficulty":3,"kind":"error","stem":"다솜반 일지 ⑤를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「㉣은 기침할 때 나오는 비말을 통해 감염될 수 있어.」","correct":true,"mis_target":"SC3-2-u4-X21"},{"t":"친구 가 — 「㉠은 손을 통해 감염될 수 있어.」","mis":"SC3-2-u4-X21"},{"t":"친구 다 — 「㉡은 같은 공간의 공기를 통해 옮길 수 있어.」","mis":"SC3-2-u4-X22"}],"explanation":["㉣은 물이에요.","오염된 물이에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 운동장에서 놀고 손을 씻지 않은 채 간식을 먹었다.","㉡ 열이 나는데도 사람이 많은 놀이공원에 갔다.","㉢ 기침이 나서 옷소매로 입과 코를 가렸다.","㉣ 여행 중에 확인하지 않은 물을 마셨다."],"title":"다솜반 일지 ⑤ 생활 습관 돌아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#21','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C14',3,'error','auto','다솜반 일지 ⑥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u4-X31','SC3-2-u4-X29']::text[],false,'{"seq":21,"concept":"SC3-2-u4-C14","difficulty":3,"kind":"error","stem":"다솜반 일지 ⑥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「옷소매로 가리는 수칙은 손을 통한 감염을 막아.」","correct":true,"mis_target":"SC3-2-u4-X31"},{"t":"친구 가 — 「소매로 가리면 비말이 덜 퍼져.」","mis":"SC3-2-u4-X31"},{"t":"친구 나 — 「익혀 먹는 수칙도 노랫말에 넣자.」","mis":"SC3-2-u4-X29"}],"explanation":["옷소매는 기침이에요.","비말을 막아요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["노랫말 — 「소매로 가려요, 콜록콜록 기침할 때」","조사 — 믿을 수 있는 누리집에서 찾고 출처를 적었다.","더 넣을 수칙 — 음식은 익혀 먹고 깨끗한 물 마시기"],"title":"다솜반 일지 ⑥ 예방 수칙 노래"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#22','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C16',3,'error','auto','다솜반 일지 ⑦을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u4-X36','SC3-2-u4-X35','SC3-2-u4-X34']::text[],false,'{"seq":22,"concept":"SC3-2-u4-C16","difficulty":3,"kind":"error","stem":"다솜반 일지 ⑦을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「수요일에 대충 씻었으니 열흘 실천은 다 소용없어.」","correct":true,"mis_target":"SC3-2-u4-X36"},{"t":"친구 나 — 「매일 기록한 것은 칭찬할 점이야.」","mis":"SC3-2-u4-X35"},{"t":"친구 다 — 「응원 댓글처럼 서로 격려하자.」","mis":"SC3-2-u4-X34"}],"explanation":["반성 줄을 봐요.","고치면 돼요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["수칙 — 흐르는 물에 비누로 30초 이상 손 씻기","기록 — 열흘 동안 하교 전에 매일 적었다.","반성 — 수요일에 시간이 없어 대충 씻었다.","응원 댓글 — 「까닭을 찾았으니 내일은 잘할 거야!」"],"title":"다솜반 일지 ⑦ 실천 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#23','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C4',4,'essay','teacher','다솜반 일지 ②를 보고 친구 가와 친구 나의 말을 감염병의 뜻에 맞게 각각 바로잡아 쓰고, 생활 속 감염병의 예를 두 가지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC3-2-u4-C4","difficulty":4,"kind":"essay","stem":"다솜반 일지 ②를 보고 친구 가와 친구 나의 말을 감염병의 뜻에 맞게 각각 바로잡아 쓰고, 생활 속 감염병의 예를 두 가지 쓰세요.","answer_guide":{"answer":"예: 친구 가처럼 넘어져 팔이 부러진 것은 병원체에 감염되어 생긴 것이 아니라서 감염병이 아니다. 친구 나의 말과 달리 감기가 심해진다고 독감이 되는 것이 아니라 감기와 독감은 서로 다른 질병이다. 생활 속 감염병에는 수두와 유행성 눈병이 있다.","scoring_points":["친구 가의 말을 감염병의 뜻과 이어 바로잡았는가","감기와 독감이 서로 다른 질병임을 썼는가","생활 속 감염병의 예 두 가지를 썼는가"]},"explanation":["두 친구 말을 읽어요.","뜻에 맞게 고쳐요.","예를 써요."],"asset":{"type":"passage","lines":["감기, 독감, 수두는 병원체에 감염되어 생기는 병이다.","친구 가 — 「지난주에 넘어져 팔이 부러졌어.」","친구 나 — 「감기가 심해지면 독감이 되는 거야?」","선생님 — 「감기와 독감은 서로 다른 질병이에요.」"],"title":"다솜반 일지 ② 감염병 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#24','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C11',4,'mc','auto','다솜반 일지 ⑤의 ㉡과 ㉢을 견주어 바르게 정리한 것은 무엇인가요?',ARRAY['SC3-2-u4-X24','SC3-2-u4-X30','SC3-2-u4-X23']::text[],false,'{"seq":24,"concept":"SC3-2-u4-C11","difficulty":4,"kind":"mc","stem":"다솜반 일지 ⑤의 ㉡과 ㉢을 견주어 바르게 정리한 것은 무엇인가요?","options":[{"t":"㉡은 공기를 통해 감염병을 유행시킬 수 있고, ㉢은 비말이 퍼지지 않게 해 유행을 막는 데 도움이 된다","correct":true},{"t":"㉡과 ㉢ 모두 유행을 막는 습관이다","mis":"SC3-2-u4-X24"},{"t":"㉡은 유행을 막고, ㉢은 유행시키는 습관이다","mis":"SC3-2-u4-X30"},{"t":"두 습관 모두 감염병과 관련이 없다","mis":"SC3-2-u4-X23"}],"explanation":["두 습관을 견줘요.","㉢은 옷소매예요.","첫 번째예요."],"asset":{"type":"passage","lines":["㉠ 운동장에서 놀고 손을 씻지 않은 채 간식을 먹었다.","㉡ 열이 나는데도 사람이 많은 놀이공원에 갔다.","㉢ 기침이 나서 옷소매로 입과 코를 가렸다.","㉣ 여행 중에 확인하지 않은 물을 마셨다."],"title":"다솜반 일지 ⑤ 생활 습관 돌아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_a#25','sci',3,2,'u4','','g3_2_sci_u4_review_a','unit_review','SC3-2-u4-C13',4,'essay','teacher','다솜반 일지 ⑥의 노랫말에 이어 넣을 예방 수칙 노랫말을 한 줄 지어 쓰고, 그 수칙이 어떤 감염을 막는지 쓰세요. 그리고 수칙을 조사할 때 지킬 점을 한 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-2-u4-C13","difficulty":4,"kind":"essay","stem":"다솜반 일지 ⑥의 노랫말에 이어 넣을 예방 수칙 노랫말을 한 줄 지어 쓰고, 그 수칙이 어떤 감염을 막는지 쓰세요. 그리고 수칙을 조사할 때 지킬 점을 한 가지 쓰세요.","answer_guide":{"answer":"예: 「밖에서 돌아오면 뽀득뽀득, 비누로 30초 손 씻어요」 이 수칙은 손을 통한 감염을 막는다. 수칙을 조사할 때는 믿을 수 있는 누리집에서 찾고 출처를 밝힌다.","scoring_points":["실천할 수 있는 수칙을 노랫말로 지었는가","그 수칙이 막는 감염을 바르게 썼는가","조사할 때 지킬 점을 썼는가"]},"explanation":["수칙을 하나 골라요.","노랫말로 바꿔요.","막는 감염을 써요."],"asset":{"type":"passage","lines":["노랫말 — 「소매로 가려요, 콜록콜록 기침할 때」","조사 — 믿을 수 있는 누리집에서 찾고 출처를 적었다.","더 넣을 수칙 — 음식은 익혀 먹고 깨끗한 물 마시기"],"title":"다솜반 일지 ⑥ 예방 수칙 노래"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#1','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C2',1,'sa','auto','다솜반 일지 ①에서 감기가 옮은 경험을 말한 친구는 누구에게서 옮았나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u4-C2","difficulty":1,"kind":"sa","stem":"다솜반 일지 ①에서 감기가 옮은 경험을 말한 친구는 누구에게서 옮았나요? 두 글자로 쓰세요.","answer":["동생"],"explanation":["셋째 줄을 읽어요.","가족이에요.","동생이에요."],"asset":{"type":"passage","lines":["숫자에 맞게 칠했더니 볼이 붉고 콧물이 나는 친구가 나타났다.","먼저 다 칠한 친구는 정답을 말하지 않고 기다렸다.","경험 나누기 — 동생에게서 감기가 옮은 적이 있다."],"title":"다솜반 일지 ① 색칠 놀이"},"mis":"SC3-2-u4-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#2','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C3',1,'sa','auto','다솜반 일지 ②에서 감기, 독감, 수두를 일으키는 것을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u4-C3","difficulty":1,"kind":"sa","stem":"다솜반 일지 ②에서 감기, 독감, 수두를 일으키는 것을 세 글자로 쓰세요.","answer":["병원체"],"explanation":["첫 줄을 읽어요.","병◯◯예요.","병원체예요."],"asset":{"type":"passage","lines":["감기, 독감, 수두는 병원체에 감염되어 생기는 병이다.","친구 가 — 「지난주에 넘어져 팔이 부러졌어.」","친구 나 — 「감기가 심해지면 독감이 되는 거야?」","선생님 — 「감기와 독감은 서로 다른 질병이에요.」"],"title":"다솜반 일지 ② 감염병 찾기"},"mis":"SC3-2-u4-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#3','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C6',1,'sa','auto','다솜반 일지 ③의 감염병 카드에 적힌 감염병 이름을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC3-2-u4-C6","difficulty":1,"kind":"sa","stem":"다솜반 일지 ③의 감염병 카드에 적힌 감염병 이름을 쓰세요.","answer":["수족구병"],"explanation":["이름 칸을 읽어요.","손, 발, 입이에요.","수족구병이에요."],"asset":{"type":"passage","lines":["이름 — 수족구병","증상 — 입안, 손과 발에 물집이 생긴다.","특징 — 분비물 등을 통해 옮는다.","토의 — 누구나 걸릴 수 있고 많은 사람에게 퍼질 수 있다."],"title":"다솜반 일지 ③ 감염병 카드와 토의"},"mis":"SC3-2-u4-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#4','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C8',1,'sa','auto','다솜반 일지 ④에서 문을 닫아 책을 빌리기 어려웠던 곳을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-2-u4-C8","difficulty":1,"kind":"sa","stem":"다솜반 일지 ④에서 문을 닫아 책을 빌리기 어려웠던 곳을 세 글자로 쓰세요.","answer":["도서관"],"explanation":["셋째 줄을 읽어요.","책을 빌려요.","도서관이에요."],"asset":{"type":"passage","lines":["할머니 말씀 — 「크게 유행했을 때 사람들이 모이지 않았단다.」","놀이터 — 사람이 없어 텅 비었다.","도서관 — 문을 닫아 책을 빌리기 어려웠다.","과학자 — 원인을 밝히고 예방하는 방법을 연구했다."],"title":"다솜반 일지 ④ 크게 유행했던 때"},"mis":"SC3-2-u4-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#5','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C10',1,'sa','auto','다솜반 일지 ⑤의 ㉠에서 간식을 먹기 전에 씻지 않은 곳을 한 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u4-C10","difficulty":1,"kind":"sa","stem":"다솜반 일지 ⑤의 ㉠에서 간식을 먹기 전에 씻지 않은 곳을 한 글자로 쓰세요.","answer":["손"],"explanation":["㉠을 읽어요.","운동장에서 놀았어요.","손이에요."],"asset":{"type":"passage","lines":["㉠ 운동장에서 놀고 손을 씻지 않은 채 간식을 먹었다.","㉡ 열이 나는데도 사람이 많은 놀이공원에 갔다.","㉢ 기침이 나서 옷소매로 입과 코를 가렸다.","㉣ 여행 중에 확인하지 않은 물을 마셨다."],"title":"다솜반 일지 ⑤ 생활 습관 돌아보기"},"mis":"SC3-2-u4-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#6','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C14',1,'sa','auto','다솜반 일지 ⑥에서 조사할 때 누리집 이름과 함께 적은 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u4-C14","difficulty":1,"kind":"sa","stem":"다솜반 일지 ⑥에서 조사할 때 누리집 이름과 함께 적은 것을 두 글자로 쓰세요.","answer":["출처"],"explanation":["둘째 줄을 읽어요.","어디서 찾았는지예요.","출처예요."],"asset":{"type":"passage","lines":["노랫말 — 「소매로 가려요, 콜록콜록 기침할 때」","조사 — 믿을 수 있는 누리집에서 찾고 출처를 적었다.","더 넣을 수칙 — 음식은 익혀 먹고 깨끗한 물 마시기"],"title":"다솜반 일지 ⑥ 예방 수칙 노래"},"mis":"SC3-2-u4-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#7','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C15',1,'sa','auto','다솜반 일지 ⑦의 수칙에서 손을 씻을 때 쓰는 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SC3-2-u4-C15","difficulty":1,"kind":"sa","stem":"다솜반 일지 ⑦의 수칙에서 손을 씻을 때 쓰는 것을 두 글자로 쓰세요.","answer":["비누"],"explanation":["첫 줄을 읽어요.","거품이 나요.","비누예요."],"asset":{"type":"passage","lines":["수칙 — 흐르는 물에 비누로 30초 이상 손 씻기","기록 — 열흘 동안 하교 전에 매일 적었다.","반성 — 수요일에 시간이 없어 대충 씻었다.","응원 댓글 — 「까닭을 찾았으니 내일은 잘할 거야!」"],"title":"다솜반 일지 ⑦ 실천 기록장"},"mis":"SC3-2-u4-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#8','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C18',1,'sa','auto','다솜반 일지 ⑧에서 친구 가가 빠뜨린 단계에서 문지르는 곳을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SC3-2-u4-C18","difficulty":1,"kind":"sa","stem":"다솜반 일지 ⑧에서 친구 가가 빠뜨린 단계에서 문지르는 곳을 쓰세요.","answer":["손톱 밑","손톱밑"],"explanation":["둘째 줄을 읽어요.","6단계예요.","손톱 밑이에요."],"asset":{"type":"passage","lines":["10월 15일에 손 씻기 6단계를 함께 해 보았다.","친구 가는 손톱 밑 문지르기를 빠뜨렸다.","반 다짐 — 「이날만이 아니라 매일 올바르게 씻자.」"],"title":"다솜반 일지 ⑧ 세계 손 씻기의 날"},"mis":"SC3-2-u4-X40"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#9','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C1',2,'mc','auto','다솜반 일지 ①의 그림에서 볼이 붉은 것과 콧물이 나는 것을 보고 짐작한 친구의 상황은 무엇인가요?',ARRAY['SC3-2-u4-X02','SC3-2-u4-X04']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C1","difficulty":2,"kind":"mc","stem":"다솜반 일지 ①의 그림에서 볼이 붉은 것과 콧물이 나는 것을 보고 짐작한 친구의 상황은 무엇인가요?","options":[{"t":"감기에 걸려 몸이 아프다","correct":true},{"t":"넘어져 다쳤다","mis":"SC3-2-u4-X02"},{"t":"약속을 잊었다","mis":"SC3-2-u4-X04"},{"t":"놀이를 하고 있다","mis":"SC3-2-u4-X02"}],"explanation":["단서를 모아요.","열과 콧물이에요.","감기에 걸렸어요."],"asset":{"type":"passage","lines":["숫자에 맞게 칠했더니 볼이 붉고 콧물이 나는 친구가 나타났다.","먼저 다 칠한 친구는 정답을 말하지 않고 기다렸다.","경험 나누기 — 동생에게서 감기가 옮은 적이 있다."],"title":"다솜반 일지 ① 색칠 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#10','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C7',2,'mc','auto','다솜반 일지 ③의 토의 내용으로 알 수 있는 감염병의 위험성은 무엇인가요?',ARRAY['SC3-2-u4-X13','SC3-2-u4-X14']::text[],false,'{"seq":10,"concept":"SC3-2-u4-C7","difficulty":2,"kind":"mc","stem":"다솜반 일지 ③의 토의 내용으로 알 수 있는 감염병의 위험성은 무엇인가요?","options":[{"t":"누구나 걸릴 수 있고 많은 사람에게 퍼질 수 있다","correct":true},{"t":"어른만 걸린다","mis":"SC3-2-u4-X13"},{"t":"아무에게도 옮지 않는다","mis":"SC3-2-u4-X13"},{"t":"물집만 외우면 걸리지 않는다","mis":"SC3-2-u4-X14"}],"explanation":["토의 줄을 읽어요.","누구나, 많은 사람이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["이름 — 수족구병","증상 — 입안, 손과 발에 물집이 생긴다.","특징 — 분비물 등을 통해 옮는다.","토의 — 누구나 걸릴 수 있고 많은 사람에게 퍼질 수 있다."],"title":"다솜반 일지 ③ 감염병 카드와 토의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#11','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C8',2,'mc','auto','다솜반 일지 ④의 할머니 말씀처럼 사람들이 모이지 않은 까닭은 무엇인가요?',ARRAY['SC3-2-u4-X16']::text[],false,'{"seq":11,"concept":"SC3-2-u4-C8","difficulty":2,"kind":"mc","stem":"다솜반 일지 ④의 할머니 말씀처럼 사람들이 모이지 않은 까닭은 무엇인가요?","options":[{"t":"많은 사람이 감염병에 걸리는 것을 막으려고","correct":true},{"t":"날씨가 너무 더워서","mis":"SC3-2-u4-X16"},{"t":"놀이터를 고치느라","mis":"SC3-2-u4-X16"},{"t":"도서관 책이 모자라서","mis":"SC3-2-u4-X16"}],"explanation":["크게 유행했어요.","퍼지지 않게 해요.","첫 번째예요."],"asset":{"type":"passage","lines":["할머니 말씀 — 「크게 유행했을 때 사람들이 모이지 않았단다.」","놀이터 — 사람이 없어 텅 비었다.","도서관 — 문을 닫아 책을 빌리기 어려웠다.","과학자 — 원인을 밝히고 예방하는 방법을 연구했다."],"title":"다솜반 일지 ④ 크게 유행했던 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#12','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C11',2,'mc','auto','다솜반 일지 ⑤의 ㉠~㉣ 가운데 감염병을 유행시킬 수 있는 습관끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X24','SC3-2-u4-X23']::text[],false,'{"seq":12,"concept":"SC3-2-u4-C11","difficulty":2,"kind":"mc","stem":"다솜반 일지 ⑤의 ㉠~㉣ 가운데 감염병을 유행시킬 수 있는 습관끼리 묶은 것은 무엇인가요?","options":[{"t":"㉠, ㉡, ㉣","correct":true},{"t":"㉠, ㉢, ㉣","mis":"SC3-2-u4-X24"},{"t":"㉡, ㉢","mis":"SC3-2-u4-X24"},{"t":"㉢만","mis":"SC3-2-u4-X23"}],"explanation":["하나씩 읽어요.","㉢은 옳은 습관이에요.","㉠, ㉡, ㉣이에요."],"asset":{"type":"passage","lines":["㉠ 운동장에서 놀고 손을 씻지 않은 채 간식을 먹었다.","㉡ 열이 나는데도 사람이 많은 놀이공원에 갔다.","㉢ 기침이 나서 옷소매로 입과 코를 가렸다.","㉣ 여행 중에 확인하지 않은 물을 마셨다."],"title":"다솜반 일지 ⑤ 생활 습관 돌아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#13','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C13',2,'mc','auto','다솜반 일지 ⑥의 노랫말에 더 넣기 알맞은 예방 수칙은 무엇인가요?',ARRAY['SC3-2-u4-X30','SC3-2-u4-X27','SC3-2-u4-X28']::text[],false,'{"seq":13,"concept":"SC3-2-u4-C13","difficulty":2,"kind":"mc","stem":"다솜반 일지 ⑥의 노랫말에 더 넣기 알맞은 예방 수칙은 무엇인가요?","options":[{"t":"정해진 시기에 예방접종하기","correct":true},{"t":"먹던 음식 나눠 먹기","mis":"SC3-2-u4-X30"},{"t":"물로만 손 헹구기","mis":"SC3-2-u4-X27"},{"t":"친구 쪽으로 기침하기","mis":"SC3-2-u4-X28"}],"explanation":["예방 수칙을 찾아요.","나머지는 유행시키는 습관이에요.","예방접종이에요."],"asset":{"type":"passage","lines":["노랫말 — 「소매로 가려요, 콜록콜록 기침할 때」","조사 — 믿을 수 있는 누리집에서 찾고 출처를 적었다.","더 넣을 수칙 — 음식은 익혀 먹고 깨끗한 물 마시기"],"title":"다솜반 일지 ⑥ 예방 수칙 노래"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#14','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C16',2,'mc','auto','다솜반 일지 ⑦의 반성 줄을 보고 할 일로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X36']::text[],false,'{"seq":14,"concept":"SC3-2-u4-C16","difficulty":2,"kind":"mc","stem":"다솜반 일지 ⑦의 반성 줄을 보고 할 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"시간이 없었던 까닭을 찾아 고쳐 나간다","correct":true},{"t":"손 씻기를 그만둔다","mis":"SC3-2-u4-X36"},{"t":"대충 씻은 날도 잘 씻었다고 고친다","mis":"SC3-2-u4-X36"},{"t":"다른 친구 탓을 한다","mis":"SC3-2-u4-X36"}],"explanation":["반성 줄을 읽어요.","까닭을 알아요.","고쳐 나가요."],"asset":{"type":"passage","lines":["수칙 — 흐르는 물에 비누로 30초 이상 손 씻기","기록 — 열흘 동안 하교 전에 매일 적었다.","반성 — 수요일에 시간이 없어 대충 씻었다.","응원 댓글 — 「까닭을 찾았으니 내일은 잘할 거야!」"],"title":"다솜반 일지 ⑦ 실천 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#15','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C18',2,'mc','auto','다솜반 일지 ⑧의 친구 가에게 알려 줄 말로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X40','SC3-2-u4-X39']::text[],false,'{"seq":15,"concept":"SC3-2-u4-C18","difficulty":2,"kind":"mc","stem":"다솜반 일지 ⑧의 친구 가에게 알려 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"「손가락을 손바닥에 놓고 손톱 밑도 문질러야 해.」","correct":true},{"t":"「손톱 밑은 안 씻어도 돼.」","mis":"SC3-2-u4-X40"},{"t":"「손바닥만 씻으면 끝이야.」","mis":"SC3-2-u4-X40"},{"t":"「손톱 밑은 1단계에 씻어.」","mis":"SC3-2-u4-X39"}],"explanation":["빠뜨린 단계예요.","6단계예요.","첫 번째예요."],"asset":{"type":"passage","lines":["10월 15일에 손 씻기 6단계를 함께 해 보았다.","친구 가는 손톱 밑 문지르기를 빠뜨렸다.","반 다짐 — 「이날만이 아니라 매일 올바르게 씻자.」"],"title":"다솜반 일지 ⑧ 세계 손 씻기의 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#16','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C13',2,'mc','auto','감염병 예방 수칙이 아닌 것은 무엇인가요?',ARRAY['SC3-2-u4-X30']::text[],false,'{"seq":16,"concept":"SC3-2-u4-C13","difficulty":2,"kind":"mc","stem":"감염병 예방 수칙이 아닌 것은 무엇인가요?","options":[{"t":"다른 사람이 먹던 음식 나눠 먹기","correct":true},{"t":"예방접종하기","mis":"SC3-2-u4-X30"},{"t":"기침 예절 지키기","mis":"SC3-2-u4-X30"},{"t":"음식을 익혀서 먹기","mis":"SC3-2-u4-X30"}],"explanation":["네 가지 수칙을 떠올려요.","침을 통해 옮을 수 있어요.","먹던 음식 나눠 먹기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#17','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C5',3,'mc','auto','「계단에서 넘어져 뼈가 부러졌어요, 독감에 걸려 집에서 쉬었어요, 꽃가루 때문에 재채기가 나왔어요, 수두에 걸려 학교에 못 갔어요」에서 감염병인 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X10']::text[],false,'{"seq":17,"concept":"SC3-2-u4-C5","difficulty":3,"kind":"mc","stem":"「계단에서 넘어져 뼈가 부러졌어요, 독감에 걸려 집에서 쉬었어요, 꽃가루 때문에 재채기가 나왔어요, 수두에 걸려 학교에 못 갔어요」에서 감염병인 것끼리 묶은 것은 무엇인가요?","options":[{"t":"독감에 걸려 집에서 쉬었어요, 수두에 걸려 학교에 못 갔어요","correct":true},{"t":"뼈가 부러졌어요, 꽃가루 때문에 재채기가 나왔어요","mis":"SC3-2-u4-X10"},{"t":"독감에 걸려 집에서 쉬었어요, 꽃가루 때문에 재채기가 나왔어요","mis":"SC3-2-u4-X10"},{"t":"뼈가 부러졌어요, 수두에 걸려 학교에 못 갔어요","mis":"SC3-2-u4-X10"}],"explanation":["감염되어 생긴 것만요.","독감과 수두예요.","두 가지를 묶어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#18','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C6',3,'mc','auto','다솜반 일지 ③의 카드에 「덥고 습한 여름철에 잘 걸려요」를 더 쓴다면 어느 칸에 써야 하나요?',ARRAY['SC3-2-u4-X11','SC3-2-u4-X12']::text[],false,'{"seq":18,"concept":"SC3-2-u4-C6","difficulty":3,"kind":"mc","stem":"다솜반 일지 ③의 카드에 「덥고 습한 여름철에 잘 걸려요」를 더 쓴다면 어느 칸에 써야 하나요?","options":[{"t":"특징","correct":true},{"t":"증상","mis":"SC3-2-u4-X11"},{"t":"이름","mis":"SC3-2-u4-X11"},{"t":"출처","mis":"SC3-2-u4-X12"}],"explanation":["언제 잘 걸리는지예요.","앓을 때의 상태가 아니에요.","특징이에요."],"asset":{"type":"passage","lines":["이름 — 수족구병","증상 — 입안, 손과 발에 물집이 생긴다.","특징 — 분비물 등을 통해 옮는다.","토의 — 누구나 걸릴 수 있고 많은 사람에게 퍼질 수 있다."],"title":"다솜반 일지 ③ 감염병 카드와 토의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#19','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C9',3,'mc','auto','다솜반 일지 ④의 놀이터와 도서관이 안전한 사회가 되면 어떻게 달라지나요?',ARRAY['SC3-2-u4-X17']::text[],false,'{"seq":19,"concept":"SC3-2-u4-C9","difficulty":3,"kind":"mc","stem":"다솜반 일지 ④의 놀이터와 도서관이 안전한 사회가 되면 어떻게 달라지나요?","options":[{"t":"놀이터에 사람들이 많아지고, 도서관을 자유롭게 이용한다","correct":true},{"t":"놀이터는 계속 비고, 도서관은 계속 문을 닫는다","mis":"SC3-2-u4-X17"},{"t":"놀이터만 열고 도서관은 영원히 닫는다","mis":"SC3-2-u4-X17"},{"t":"안전한 사회에서도 아무 곳에도 갈 수 없다","mis":"SC3-2-u4-X17"}],"explanation":["반대 모습을 떠올려요.","함께 모여요.","첫 번째예요."],"asset":{"type":"passage","lines":["할머니 말씀 — 「크게 유행했을 때 사람들이 모이지 않았단다.」","놀이터 — 사람이 없어 텅 비었다.","도서관 — 문을 닫아 책을 빌리기 어려웠다.","과학자 — 원인을 밝히고 예방하는 방법을 연구했다."],"title":"다솜반 일지 ④ 크게 유행했던 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#20','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C10',3,'mc','auto','다솜반 일지 ⑤의 ㉠~㉣을 감염 과정과 바르게 이은 것은 무엇인가요?',ARRAY['SC3-2-u4-X21','SC3-2-u4-X22']::text[],false,'{"seq":20,"concept":"SC3-2-u4-C10","difficulty":3,"kind":"mc","stem":"다솜반 일지 ⑤의 ㉠~㉣을 감염 과정과 바르게 이은 것은 무엇인가요?","options":[{"t":"㉠ 손 · ㉡ 공기 · ㉣ 오염된 물","correct":true},{"t":"㉠ 비말 · ㉡ 오염된 물 · ㉣ 손","mis":"SC3-2-u4-X21"},{"t":"㉠ 공기 · ㉡ 손 · ㉣ 침","mis":"SC3-2-u4-X21"},{"t":"셋 모두 공기","mis":"SC3-2-u4-X22"}],"explanation":["하나씩 읽어요.","㉣은 물이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["㉠ 운동장에서 놀고 손을 씻지 않은 채 간식을 먹었다.","㉡ 열이 나는데도 사람이 많은 놀이공원에 갔다.","㉢ 기침이 나서 옷소매로 입과 코를 가렸다.","㉣ 여행 중에 확인하지 않은 물을 마셨다."],"title":"다솜반 일지 ⑤ 생활 습관 돌아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#21','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C13',3,'mc','auto','「비누로 30초 이상 흐르는 물에 씻어요, 외출하고 돌아와 손을 씻어요, 손바닥만 대충 씻어요, 음식을 익히지 않고 먹어요」를 「올바른 예방 수칙인가?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X27','SC3-2-u4-X29']::text[],false,'{"seq":21,"concept":"SC3-2-u4-C13","difficulty":3,"kind":"mc","stem":"「비누로 30초 이상 흐르는 물에 씻어요, 외출하고 돌아와 손을 씻어요, 손바닥만 대충 씻어요, 음식을 익히지 않고 먹어요」를 「올바른 예방 수칙인가?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"비누로 30초 이상 흐르는 물에 씻어요, 외출하고 돌아와 손을 씻어요","correct":true},{"t":"손바닥만 대충 씻어요, 음식을 익히지 않고 먹어요","mis":"SC3-2-u4-X27"},{"t":"비누로 30초 이상 흐르는 물에 씻어요, 음식을 익히지 않고 먹어요","mis":"SC3-2-u4-X29"},{"t":"외출하고 돌아와 손을 씻어요, 손바닥만 대충 씻어요","mis":"SC3-2-u4-X27"}],"explanation":["고쳐야 할 것을 빼요.","대충, 익히지 않기는 빼요.","두 가지를 묶어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#22','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C15',3,'mc','auto','다솜반 일지 ⑦의 수칙이 잘 세운 수칙인 까닭은 무엇인가요?',ARRAY['SC3-2-u4-X33','SC3-2-u4-X34','SC3-2-u4-X35']::text[],false,'{"seq":22,"concept":"SC3-2-u4-C15","difficulty":3,"kind":"mc","stem":"다솜반 일지 ⑦의 수칙이 잘 세운 수칙인 까닭은 무엇인가요?","options":[{"t":"무엇을 어떻게 할지 구체적으로 드러나서","correct":true},{"t":"짧고 막연해서","mis":"SC3-2-u4-X33"},{"t":"못 지킨 친구를 찾기 쉬워서","mis":"SC3-2-u4-X34"},{"t":"하루만 하면 돼서","mis":"SC3-2-u4-X35"}],"explanation":["수칙을 읽어요.","비누, 30초가 있어요.","구체적이라서예요."],"asset":{"type":"passage","lines":["수칙 — 흐르는 물에 비누로 30초 이상 손 씻기","기록 — 열흘 동안 하교 전에 매일 적었다.","반성 — 수요일에 시간이 없어 대충 씻었다.","응원 댓글 — 「까닭을 찾았으니 내일은 잘할 거야!」"],"title":"다솜반 일지 ⑦ 실천 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#23','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C7',4,'essay','teacher','다솜반 일지 ③을 보고 수족구병 카드의 증상과 특징을 구별해 쓰고, 토의 내용을 바탕으로 감염병이 위험한 까닭을 두 가지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC3-2-u4-C7","difficulty":4,"kind":"essay","stem":"다솜반 일지 ③을 보고 수족구병 카드의 증상과 특징을 구별해 쓰고, 토의 내용을 바탕으로 감염병이 위험한 까닭을 두 가지 쓰세요.","answer_guide":{"answer":"예: 수족구병의 증상은 입안, 손과 발에 물집이 생기는 것이고, 특징은 분비물 등을 통해 옮는다는 것이다. 감염병은 누구나 걸릴 수 있고, 다른 사람에게 옮아 많은 사람에게 퍼질 수 있어서 위험하다.","scoring_points":["증상을 바르게 썼는가","특징을 바르게 썼는가","감염병이 위험한 까닭 두 가지를 썼는가"]},"explanation":["카드를 읽어요.","칸을 나눠요.","위험성을 써요."],"asset":{"type":"passage","lines":["이름 — 수족구병","증상 — 입안, 손과 발에 물집이 생긴다.","특징 — 분비물 등을 통해 옮는다.","토의 — 누구나 걸릴 수 있고 많은 사람에게 퍼질 수 있다."],"title":"다솜반 일지 ③ 감염병 카드와 토의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#24','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C14',4,'mc','auto','친구가 「예방 수칙은 외워만 두면 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-2-u4-X32','SC3-2-u4-X35','SC3-2-u4-X34']::text[],false,'{"seq":24,"concept":"SC3-2-u4-C14","difficulty":4,"kind":"mc","stem":"친구가 「예방 수칙은 외워만 두면 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「수칙을 감염 과정과 이어 이해하고, 생활 속에서 꾸준히 실천해야 해.」","correct":true},{"t":"「맞아, 외우면 감염병에 안 걸려.」","mis":"SC3-2-u4-X32"},{"t":"「하루만 지키면 충분해.」","mis":"SC3-2-u4-X35"},{"t":"「못 지키는 친구를 혼내면 돼.」","mis":"SC3-2-u4-X34"}],"explanation":["수칙은 실천이에요.","꾸준히 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_b#25','sci',3,2,'u4','','g3_2_sci_u4_review_b','unit_review','SC3-2-u4-C16',4,'essay','teacher','다솜반 일지 ⑦을 보고 이 모둠의 실천에서 잘한 점과 반성할 점을 하나씩 쓰고, 반성할 점을 고칠 방법과 친구에게 줄 응원 댓글을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-2-u4-C16","difficulty":4,"kind":"essay","stem":"다솜반 일지 ⑦을 보고 이 모둠의 실천에서 잘한 점과 반성할 점을 하나씩 쓰고, 반성할 점을 고칠 방법과 친구에게 줄 응원 댓글을 쓰세요.","answer_guide":{"answer":"예: 잘한 점은 열흘 동안 하교 전에 매일 기록한 것이다. 반성할 점은 수요일에 시간이 없어 손을 대충 씻은 것이다. 쉬는 시간이 시작되면 먼저 손을 씻으러 가서 30초 이상 씻는다. 「끝까지 기록한 게 멋져, 내일도 함께 하자!」","scoring_points":["잘한 점을 썼는가","반성할 점과 고칠 방법을 썼는가","비난하지 않고 격려하는 댓글을 썼는가"]},"explanation":["일지를 읽어요.","잘한 점부터 써요.","응원 댓글을 써요."],"asset":{"type":"passage","lines":["수칙 — 흐르는 물에 비누로 30초 이상 손 씻기","기록 — 열흘 동안 하교 전에 매일 적었다.","반성 — 수요일에 시간이 없어 대충 씻었다.","응원 댓글 — 「까닭을 찾았으니 내일은 잘할 거야!」"],"title":"다솜반 일지 ⑦ 실천 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#1','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C1',1,'ox','auto','다솜반 일지 ①처럼 먼저 다 칠한 친구는 정답을 말하지 않고 기다려요.',ARRAY['SC3-2-u4-X03']::text[],false,'{"seq":1,"concept":"SC3-2-u4-C1","difficulty":1,"kind":"ox","stem":"다솜반 일지 ①처럼 먼저 다 칠한 친구는 정답을 말하지 않고 기다려요.","answer":"O","reason_options":[{"t":"다른 친구가 스스로 찾도록 해야 하기 때문에","correct":true},{"t":"정답을 먼저 외쳐야 이기기 때문에","mis":"SC3-2-u4-X03"}],"mis":"SC3-2-u4-X03","explanation":["둘째 줄을 읽어요.","스스로 찾게 해요.","그래서 O예요."],"asset":{"type":"passage","lines":["숫자에 맞게 칠했더니 볼이 붉고 콧물이 나는 친구가 나타났다.","먼저 다 칠한 친구는 정답을 말하지 않고 기다렸다.","경험 나누기 — 동생에게서 감기가 옮은 적이 있다."],"title":"다솜반 일지 ① 색칠 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#2','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C4',1,'ox','auto','다솜반 일지 ②의 선생님 말씀처럼 감기와 독감은 서로 다른 질병이에요.',ARRAY['SC3-2-u4-X08']::text[],false,'{"seq":2,"concept":"SC3-2-u4-C4","difficulty":1,"kind":"ox","stem":"다솜반 일지 ②의 선생님 말씀처럼 감기와 독감은 서로 다른 질병이에요.","answer":"O","reason_options":[{"t":"감기가 심해진다고 독감이 되는 것이 아니기 때문에","correct":true},{"t":"독감은 감기가 심해진 것이기 때문에","mis":"SC3-2-u4-X08"}],"mis":"SC3-2-u4-X08","explanation":["넷째 줄을 읽어요.","서로 달라요.","그래서 O예요."],"asset":{"type":"passage","lines":["감기, 독감, 수두는 병원체에 감염되어 생기는 병이다.","친구 가 — 「지난주에 넘어져 팔이 부러졌어.」","친구 나 — 「감기가 심해지면 독감이 되는 거야?」","선생님 — 「감기와 독감은 서로 다른 질병이에요.」"],"title":"다솜반 일지 ② 감염병 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#3','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C7',1,'ox','auto','다솜반 일지 ③의 토의처럼 감염병은 많은 사람에게 퍼질 수 있어요.',ARRAY['SC3-2-u4-X13']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C7","difficulty":1,"kind":"ox","stem":"다솜반 일지 ③의 토의처럼 감염병은 많은 사람에게 퍼질 수 있어요.","answer":"O","reason_options":[{"t":"다른 사람에게 옮을 수 있기 때문에","correct":true},{"t":"한 사람만 걸리고 끝나기 때문에","mis":"SC3-2-u4-X13"}],"mis":"SC3-2-u4-X13","explanation":["토의 줄을 읽어요.","옮을 수 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["이름 — 수족구병","증상 — 입안, 손과 발에 물집이 생긴다.","특징 — 분비물 등을 통해 옮는다.","토의 — 누구나 걸릴 수 있고 많은 사람에게 퍼질 수 있다."],"title":"다솜반 일지 ③ 감염병 카드와 토의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#4','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C9',1,'ox','auto','다솜반 일지 ④처럼 과학자들은 감염병의 원인을 밝히고 예방하는 방법을 연구해요.',ARRAY['SC3-2-u4-X20']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C9","difficulty":1,"kind":"ox","stem":"다솜반 일지 ④처럼 과학자들은 감염병의 원인을 밝히고 예방하는 방법을 연구해요.","answer":"O","reason_options":[{"t":"과학 기술로 안전한 사회를 만드는 데 힘쓰기 때문에","correct":true},{"t":"과학자들은 감염병과 상관없는 일만 하기 때문에","mis":"SC3-2-u4-X20"}],"mis":"SC3-2-u4-X20","explanation":["넷째 줄을 읽어요.","연구해요.","그래서 O예요."],"asset":{"type":"passage","lines":["할머니 말씀 — 「크게 유행했을 때 사람들이 모이지 않았단다.」","놀이터 — 사람이 없어 텅 비었다.","도서관 — 문을 닫아 책을 빌리기 어려웠다.","과학자 — 원인을 밝히고 예방하는 방법을 연구했다."],"title":"다솜반 일지 ④ 크게 유행했던 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#5','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C11',1,'ox','auto','다솜반 일지 ⑤의 ㉡처럼 아픈데도 사람이 많은 곳에 가면 감염병을 유행시킬 수 있어요.',ARRAY['SC3-2-u4-X24']::text[],false,'{"seq":5,"concept":"SC3-2-u4-C11","difficulty":1,"kind":"ox","stem":"다솜반 일지 ⑤의 ㉡처럼 아픈데도 사람이 많은 곳에 가면 감염병을 유행시킬 수 있어요.","answer":"O","reason_options":[{"t":"같은 공간의 다른 사람에게 옮을 수 있기 때문에","correct":true},{"t":"사람이 많은 곳에서는 감염병이 사라지기 때문에","mis":"SC3-2-u4-X24"}],"mis":"SC3-2-u4-X24","explanation":["㉡을 읽어요.","열이 났어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 운동장에서 놀고 손을 씻지 않은 채 간식을 먹었다.","㉡ 열이 나는데도 사람이 많은 놀이공원에 갔다.","㉢ 기침이 나서 옷소매로 입과 코를 가렸다.","㉣ 여행 중에 확인하지 않은 물을 마셨다."],"title":"다솜반 일지 ⑤ 생활 습관 돌아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#6','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C13',1,'ox','auto','다솜반 일지 ⑥에 더 넣을 수칙처럼 음식은 익혀 먹고 깨끗한 물을 마셔요.',ARRAY['SC3-2-u4-X29']::text[],false,'{"seq":6,"concept":"SC3-2-u4-C13","difficulty":1,"kind":"ox","stem":"다솜반 일지 ⑥에 더 넣을 수칙처럼 음식은 익혀 먹고 깨끗한 물을 마셔요.","answer":"O","reason_options":[{"t":"오염된 물이나 음식을 통한 감염을 막기 때문에","correct":true},{"t":"음식은 익히면 맛이 없기 때문에","mis":"SC3-2-u4-X29"}],"mis":"SC3-2-u4-X29","explanation":["셋째 줄을 읽어요.","익혀 먹어요.","그래서 O예요."],"asset":{"type":"passage","lines":["노랫말 — 「소매로 가려요, 콜록콜록 기침할 때」","조사 — 믿을 수 있는 누리집에서 찾고 출처를 적었다.","더 넣을 수칙 — 음식은 익혀 먹고 깨끗한 물 마시기"],"title":"다솜반 일지 ⑥ 예방 수칙 노래"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#7','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C16',1,'ox','auto','다솜반 일지 ⑦의 응원 댓글처럼 못 지킨 친구를 격려해요.',ARRAY['SC3-2-u4-X34']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C16","difficulty":1,"kind":"ox","stem":"다솜반 일지 ⑦의 응원 댓글처럼 못 지킨 친구를 격려해요.","answer":"O","reason_options":[{"t":"까닭을 찾고 고쳐 나가도록 돕는 것이 중요하기 때문에","correct":true},{"t":"못 지킨 친구는 혼나야 하기 때문에","mis":"SC3-2-u4-X34"}],"mis":"SC3-2-u4-X34","explanation":["넷째 줄을 읽어요.","응원해요.","그래서 O예요."],"asset":{"type":"passage","lines":["수칙 — 흐르는 물에 비누로 30초 이상 손 씻기","기록 — 열흘 동안 하교 전에 매일 적었다.","반성 — 수요일에 시간이 없어 대충 씻었다.","응원 댓글 — 「까닭을 찾았으니 내일은 잘할 거야!」"],"title":"다솜반 일지 ⑦ 실천 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#8','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C17',1,'ox','auto','다솜반 일지 ⑧의 다짐처럼 손 씻기는 매일 실천해요.',ARRAY['SC3-2-u4-X37']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C17","difficulty":1,"kind":"ox","stem":"다솜반 일지 ⑧의 다짐처럼 손 씻기는 매일 실천해요.","answer":"O","reason_options":[{"t":"손에는 언제든 병원체가 묻을 수 있기 때문에","correct":true},{"t":"세계 손 씻기의 날에만 씻으면 되기 때문에","mis":"SC3-2-u4-X37"}],"mis":"SC3-2-u4-X37","explanation":["셋째 줄을 읽어요.","이날만이 아니에요.","그래서 O예요."],"asset":{"type":"passage","lines":["10월 15일에 손 씻기 6단계를 함께 해 보았다.","친구 가는 손톱 밑 문지르기를 빠뜨렸다.","반 다짐 — 「이날만이 아니라 매일 올바르게 씻자.」"],"title":"다솜반 일지 ⑧ 세계 손 씻기의 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#9','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C5',2,'mc','auto','「감염병인가?」로 나누었을 때 ✕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X10']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C5","difficulty":2,"kind":"mc","stem":"「감염병인가?」로 나누었을 때 ✕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"꽃가루 때문에 나온 재채기, 뜨거운 물에 데인 손","correct":true},{"t":"수두, 꽃가루 때문에 나온 재채기","mis":"SC3-2-u4-X10"},{"t":"독감, 뜨거운 물에 데인 손","mis":"SC3-2-u4-X10"},{"t":"수두, 독감","mis":"SC3-2-u4-X10"}],"explanation":["감염되어 생긴 것을 빼요.","꽃가루와 화상이에요.","두 가지를 묶어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#10','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C7',2,'mc','auto','감염병 토의에서 친구 의견을 존중하는 말은 무엇인가요?',ARRAY['SC3-2-u4-X15']::text[],false,'{"seq":10,"concept":"SC3-2-u4-C7","difficulty":2,"kind":"mc","stem":"감염병 토의에서 친구 의견을 존중하는 말은 무엇인가요?","options":[{"t":"「네 생각도 들어 보니 그럴 수 있겠다.」","correct":true},{"t":"「그건 말도 안 돼.」","mis":"SC3-2-u4-X15"},{"t":"「내 말만 맞아.」","mis":"SC3-2-u4-X15"},{"t":"「말하지 마.」","mis":"SC3-2-u4-X15"}],"explanation":["존중하는 말이에요.","끝까지 들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#11','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C9',2,'mc','auto','안전한 사회를 위한 다짐으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X19']::text[],false,'{"seq":11,"concept":"SC3-2-u4-C9","difficulty":2,"kind":"mc","stem":"안전한 사회를 위한 다짐으로 알맞은 것은 무엇인가요?","options":[{"t":"건강을 잘 관리하고 안전한 사회를 만드는 데 관심을 가진다","correct":true},{"t":"감염병은 나와 상관없다고 생각한다","mis":"SC3-2-u4-X19"},{"t":"아파도 사람이 많은 곳에 간다","mis":"SC3-2-u4-X19"},{"t":"감염병 이야기는 듣지 않는다","mis":"SC3-2-u4-X19"}],"explanation":["유행을 막는 데 도움이 돼요.","관심을 가져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#12','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C12',2,'mc','auto','다솜반 일지 ⑤의 ㉡을 역할극으로 꾸밀 때 꼭 드러나야 하는 것은 무엇인가요?',ARRAY['SC3-2-u4-X25','SC3-2-u4-X26']::text[],false,'{"seq":12,"concept":"SC3-2-u4-C12","difficulty":2,"kind":"mc","stem":"다솜반 일지 ⑤의 ㉡을 역할극으로 꾸밀 때 꼭 드러나야 하는 것은 무엇인가요?","options":[{"t":"열이 나는데 사람이 많은 곳에 가서 공기를 통해 다른 사람에게 옮는 과정","correct":true},{"t":"놀이공원에서 재미있게 노는 모습만","mis":"SC3-2-u4-X25"},{"t":"가장 멋진 의상","mis":"SC3-2-u4-X25"},{"t":"한 친구가 모든 역할 맡기","mis":"SC3-2-u4-X26"}],"explanation":["습관과 감염 과정이에요.","어떻게 옮는지요.","첫 번째예요."],"asset":{"type":"passage","lines":["㉠ 운동장에서 놀고 손을 씻지 않은 채 간식을 먹었다.","㉡ 열이 나는데도 사람이 많은 놀이공원에 갔다.","㉢ 기침이 나서 옷소매로 입과 코를 가렸다.","㉣ 여행 중에 확인하지 않은 물을 마셨다."],"title":"다솜반 일지 ⑤ 생활 습관 돌아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#13','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C14',2,'mc','auto','「아무렇게나 기침해요」를 예방하는 습관으로 바꾼 것은 무엇인가요?',ARRAY['SC3-2-u4-X28']::text[],false,'{"seq":13,"concept":"SC3-2-u4-C14","difficulty":2,"kind":"mc","stem":"「아무렇게나 기침해요」를 예방하는 습관으로 바꾼 것은 무엇인가요?","options":[{"t":"기침할 때 옷소매로 입과 코를 가려요","correct":true},{"t":"기침할 때 친구 쪽을 봐요","mis":"SC3-2-u4-X28"},{"t":"기침할 때 크게 소리 내요","mis":"SC3-2-u4-X28"},{"t":"기침한 손으로 바로 악수해요","mis":"SC3-2-u4-X28"}],"explanation":["반대로 바꿔요.","비말이 퍼지지 않게요.","옷소매로 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#14','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C16',2,'mc','auto','실천 결과를 나눌 때 스스로 칭찬할 점으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X34','SC3-2-u4-X35']::text[],false,'{"seq":14,"concept":"SC3-2-u4-C16","difficulty":2,"kind":"mc","stem":"실천 결과를 나눌 때 스스로 칭찬할 점으로 알맞은 것은 무엇인가요?","options":[{"t":"「급식 먹기 전에 손을 잘 씻었어요.」","correct":true},{"t":"「친구가 못 지킨 걸 다 적었어요.」","mis":"SC3-2-u4-X34"},{"t":"「마지막 날 기록장을 한꺼번에 썼어요.」","mis":"SC3-2-u4-X35"},{"t":"「기록장을 가장 화려하게 꾸몄어요.」","mis":"SC3-2-u4-X35"}],"explanation":["잘 실천한 점이에요.","꾸밈은 아니에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#15','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C17',2,'mc','auto','다솜반 일지 ⑧의 반 다짐에 담긴 뜻으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X37']::text[],false,'{"seq":15,"concept":"SC3-2-u4-C17","difficulty":2,"kind":"mc","stem":"다솜반 일지 ⑧의 반 다짐에 담긴 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"세계 손 씻기의 날은 중요성을 알리는 날이고, 손 씻기는 매일 한다","correct":true},{"t":"이날에만 손을 씻으면 된다","mis":"SC3-2-u4-X37"},{"t":"이날은 비누를 많이 사는 날이다","mis":"SC3-2-u4-X37"},{"t":"이날에는 손을 쉬게 한다","mis":"SC3-2-u4-X37"}],"explanation":["셋째 줄을 읽어요.","매일이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["10월 15일에 손 씻기 6단계를 함께 해 보았다.","친구 가는 손톱 밑 문지르기를 빠뜨렸다.","반 다짐 — 「이날만이 아니라 매일 올바르게 씻자.」"],"title":"다솜반 일지 ⑧ 세계 손 씻기의 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#16','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C11',2,'mc','auto','단원에서 알게 된 것으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X23','SC3-2-u4-X10','SC3-2-u4-X07']::text[],false,'{"seq":16,"concept":"SC3-2-u4-C11","difficulty":2,"kind":"mc","stem":"단원에서 알게 된 것으로 알맞은 것은 무엇인가요?","options":[{"t":"감염병 유행은 생활 습관과 관련이 있다","correct":true},{"t":"감염병은 예방할 방법이 없다","mis":"SC3-2-u4-X23"},{"t":"뜨거운 물에 데인 것도 감염병이다","mis":"SC3-2-u4-X10"},{"t":"감염병은 옛날에만 있었다","mis":"SC3-2-u4-X07"}],"explanation":["단원 흐름을 떠올려요.","습관과 유행이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#17','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C3',3,'mc','auto','「감염병은 병을 일으키는 (    )에 감염되어 생기는 질병이에요.」 빈칸에 알맞은 말과 그 예를 바르게 짝지은 것은 무엇인가요?',ARRAY['SC3-2-u4-X05','SC3-2-u4-X06']::text[],false,'{"seq":17,"concept":"SC3-2-u4-C3","difficulty":3,"kind":"mc","stem":"「감염병은 병을 일으키는 (    )에 감염되어 생기는 질병이에요.」 빈칸에 알맞은 말과 그 예를 바르게 짝지은 것은 무엇인가요?","options":[{"t":"병원체 — 세균, 바이러스","correct":true},{"t":"상처 — 골절, 화상","mis":"SC3-2-u4-X05"},{"t":"햇빛 — 자외선, 열","mis":"SC3-2-u4-X06"},{"t":"꽃가루 — 재채기, 콧물","mis":"SC3-2-u4-X06"}],"explanation":["병의 원인이 되는 본체예요.","세균, 바이러스예요.","병원체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#18','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C7',3,'mc','auto','감염병이 위험한 까닭으로 알맞은 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X13']::text[],false,'{"seq":18,"concept":"SC3-2-u4-C7","difficulty":3,"kind":"mc","stem":"감염병이 위험한 까닭으로 알맞은 것끼리 묶은 것은 무엇인가요?","options":[{"t":"다양한 증상이 나타나 몸이 아프다, 치료 뒤에도 증상이 오래 남을 수 있다","correct":true},{"t":"증상이 다양해서 괜찮다, 아무에게도 옮지 않는다","mis":"SC3-2-u4-X13"},{"t":"다양한 증상이 나타나 몸이 아프다, 증상이 다양해서 괜찮다","mis":"SC3-2-u4-X13"},{"t":"아무에게도 옮지 않는다, 치료 뒤에도 증상이 오래 남을 수 있다","mis":"SC3-2-u4-X13"}],"explanation":["세 가지 위험성을 떠올려요.","괜찮다는 말은 빼요.","두 가지를 묶어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#19','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C8',3,'mc','auto','감염병이 크게 유행할 때 달라진 모습을 모두 바르게 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X17','SC3-2-u4-X18']::text[],false,'{"seq":19,"concept":"SC3-2-u4-C8","difficulty":3,"kind":"mc","stem":"감염병이 크게 유행할 때 달라진 모습을 모두 바르게 묶은 것은 무엇인가요?","options":[{"t":"공공시설을 이용하기 어렵다, 병원이 제 역할을 하기 어렵다, 여러 사람이 모여 생활하기 어렵다","correct":true},{"t":"공공시설을 이용하기 어렵다, 모든 가게가 손님으로 붐빈다","mis":"SC3-2-u4-X17"},{"t":"병원이 한가하다, 놀이터가 붐빈다","mis":"SC3-2-u4-X17"},{"t":"아무것도 달라지지 않는다","mis":"SC3-2-u4-X18"}],"explanation":["사람이 모이는 곳을 떠올려요.","붐비는 가게는 빼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#20','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C12',3,'mc','auto','역할극을 그림이나 책 만들기로 바꾸어 표현할 때도 꼭 지킬 것은 무엇인가요?',ARRAY['SC3-2-u4-X25','SC3-2-u4-X26']::text[],false,'{"seq":20,"concept":"SC3-2-u4-C12","difficulty":3,"kind":"mc","stem":"역할극을 그림이나 책 만들기로 바꾸어 표현할 때도 꼭 지킬 것은 무엇인가요?","options":[{"t":"생활 습관과 감염 과정의 관련이 드러나게 한다","correct":true},{"t":"재미있는 그림만 그린다","mis":"SC3-2-u4-X25"},{"t":"혼자서 모든 쪽을 만든다","mis":"SC3-2-u4-X26"},{"t":"감염 과정은 빼고 꾸민다","mis":"SC3-2-u4-X25"}],"explanation":["표현 방법만 달라요.","관련이 드러나야 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#21','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C14',3,'mc','auto','예방 수칙 홍보 노랫말로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X32','SC3-2-u4-X29','SC3-2-u4-X30']::text[],false,'{"seq":21,"concept":"SC3-2-u4-C14","difficulty":3,"kind":"mc","stem":"예방 수칙 홍보 노랫말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「밥 먹기 전 뽀득뽀득, 비누로 30초 손 씻어요」","correct":true},{"t":"「병원체를 조심하자, 조심하자」","mis":"SC3-2-u4-X32"},{"t":"「아무 때나 주사 맞자」","mis":"SC3-2-u4-X29"},{"t":"「먹던 빵도 나눠 먹자」","mis":"SC3-2-u4-X30"}],"explanation":["실천할 수 있는 수칙이에요.","무엇을 어떻게 할지요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#22','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C18',3,'mc','auto','다솜반 일지 ⑧에서 친구 가가 빠뜨린 단계를 넣어 손 씻기 6단계의 마지막 두 단계를 차례대로 쓴 것은 무엇인가요?',ARRAY['SC3-2-u4-X39','SC3-2-u4-X40']::text[],false,'{"seq":22,"concept":"SC3-2-u4-C18","difficulty":3,"kind":"mc","stem":"다솜반 일지 ⑧에서 친구 가가 빠뜨린 단계를 넣어 손 씻기 6단계의 마지막 두 단계를 차례대로 쓴 것은 무엇인가요?","options":[{"t":"엄지손가락 → 손톱 밑","correct":true},{"t":"손톱 밑 → 엄지손가락","mis":"SC3-2-u4-X39"},{"t":"손바닥 → 손등","mis":"SC3-2-u4-X39"},{"t":"두 손 모아 → 엄지손가락","mis":"SC3-2-u4-X40"}],"explanation":["5단계와 6단계예요.","마지막은 손톱 밑이에요.","엄지손가락 → 손톱 밑이에요."],"asset":{"type":"passage","lines":["10월 15일에 손 씻기 6단계를 함께 해 보았다.","친구 가는 손톱 밑 문지르기를 빠뜨렸다.","반 다짐 — 「이날만이 아니라 매일 올바르게 씻자.」"],"title":"다솜반 일지 ⑧ 세계 손 씻기의 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#23','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C8',4,'essay','teacher','다솜반 일지 ④를 보고 감염병이 크게 유행했을 때 사회가 어떻게 달라졌는지 두 가지 쓰고, 안전한 사회를 만들려고 우리가 할 수 있는 일을 한 가지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC3-2-u4-C8","difficulty":4,"kind":"essay","stem":"다솜반 일지 ④를 보고 감염병이 크게 유행했을 때 사회가 어떻게 달라졌는지 두 가지 쓰고, 안전한 사회를 만들려고 우리가 할 수 있는 일을 한 가지 쓰세요.","answer_guide":{"answer":"예: 크게 유행했을 때 놀이터에 사람이 없어 텅 비었고, 도서관이 문을 닫아 책을 빌리기 어려웠다. 우리는 건강을 잘 관리하고 안전한 사회를 만드는 데 관심을 가질 수 있다.","scoring_points":["달라진 모습 하나를 썼는가","달라진 모습 또 하나를 썼는가","안전한 사회를 위해 할 수 있는 일을 썼는가"]},"explanation":["일지를 읽어요.","달라진 모습을 써요.","할 일을 써요."],"asset":{"type":"passage","lines":["할머니 말씀 — 「크게 유행했을 때 사람들이 모이지 않았단다.」","놀이터 — 사람이 없어 텅 비었다.","도서관 — 문을 닫아 책을 빌리기 어려웠다.","과학자 — 원인을 밝히고 예방하는 방법을 연구했다."],"title":"다솜반 일지 ④ 크게 유행했던 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#24','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C16',4,'mc','auto','다솜반 일지 ⑦을 보고 이 모둠의 다음 실천을 가장 알맞게 계획한 것은 무엇인가요?',ARRAY['SC3-2-u4-X35','SC3-2-u4-X34','SC3-2-u4-X33']::text[],false,'{"seq":24,"concept":"SC3-2-u4-C16","difficulty":4,"kind":"mc","stem":"다솜반 일지 ⑦을 보고 이 모둠의 다음 실천을 가장 알맞게 계획한 것은 무엇인가요?","options":[{"t":"시간이 없던 까닭을 찾아 쉬는 시간이 시작되면 먼저 손을 씻고, 매일 기록하며 서로 격려한다","correct":true},{"t":"수요일처럼 바쁜 날은 기록하지 않는다","mis":"SC3-2-u4-X35"},{"t":"대충 씻은 친구를 반 친구들에게 알린다","mis":"SC3-2-u4-X34"},{"t":"어려우니 수칙을 「손 조심하기」로 바꾼다","mis":"SC3-2-u4-X33"}],"explanation":["반성 줄을 봐요.","고쳐 나가요.","첫 번째예요."],"asset":{"type":"passage","lines":["수칙 — 흐르는 물에 비누로 30초 이상 손 씻기","기록 — 열흘 동안 하교 전에 매일 적었다.","반성 — 수요일에 시간이 없어 대충 씻었다.","응원 댓글 — 「까닭을 찾았으니 내일은 잘할 거야!」"],"title":"다솜반 일지 ⑦ 실천 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_c#25','sci',3,2,'u4','','g3_2_sci_u4_review_c','unit_review','SC3-2-u4-C17',4,'essay','teacher','다솜반 일지 ⑧을 보고 세계 손 씻기의 날을 정한 까닭과 반 다짐의 뜻을 쓰고, 손 씻기 6단계를 차례대로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-2-u4-C17","difficulty":4,"kind":"essay","stem":"다솜반 일지 ⑧을 보고 세계 손 씻기의 날을 정한 까닭과 반 다짐의 뜻을 쓰고, 손 씻기 6단계를 차례대로 쓰세요.","answer_guide":{"answer":"예: 세계 손 씻기의 날은 손 씻기의 중요성을 알리려고 정한 날이다. 반 다짐은 이날만이 아니라 매일 올바르게 손을 씻자는 뜻이다. 손 씻기 6단계는 손바닥, 손등, 손가락 사이, 두 손 모아, 엄지손가락, 손톱 밑 차례이다.","scoring_points":["세계 손 씻기의 날을 정한 까닭을 썼는가","반 다짐의 뜻을 썼는가","6단계를 차례대로 썼는가"]},"explanation":["일지를 읽어요.","까닭과 뜻을 써요.","6단계를 써요."],"asset":{"type":"passage","lines":["10월 15일에 손 씻기 6단계를 함께 해 보았다.","친구 가는 손톱 밑 문지르기를 빠뜨렸다.","반 다짐 — 「이날만이 아니라 매일 올바르게 씻자.」"],"title":"다솜반 일지 ⑧ 세계 손 씻기의 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#1','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C2',1,'mc','auto','감기와 관련된 경험은 무엇인가요?',ARRAY['SC3-2-u4-X04']::text[],false,'{"seq":1,"concept":"SC3-2-u4-C2","difficulty":1,"kind":"mc","stem":"감기와 관련된 경험은 무엇인가요?","options":[{"t":"친구와 놀다가 감기가 옮았다","correct":true},{"t":"넘어져 무릎을 다쳤다","mis":"SC3-2-u4-X04"},{"t":"약속을 잊어 놀이터에 못 갔다","mis":"SC3-2-u4-X04"},{"t":"생일 잔치에 다녀왔다","mis":"SC3-2-u4-X04"}],"explanation":["감기를 찾아요.","옮은 일도 돼요.","감기가 옮은 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#2','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C4',1,'mc','auto','생활 속 감염병이 아닌 것은 무엇인가요?',ARRAY['SC3-2-u4-X07']::text[],false,'{"seq":2,"concept":"SC3-2-u4-C4","difficulty":1,"kind":"mc","stem":"생활 속 감염병이 아닌 것은 무엇인가요?","options":[{"t":"화상","correct":true},{"t":"수족구병","mis":"SC3-2-u4-X07"},{"t":"독감","mis":"SC3-2-u4-X07"},{"t":"유행성 눈병","mis":"SC3-2-u4-X07"}],"explanation":["감염되어 생긴 것을 빼요.","데인 것이에요.","화상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#3','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C7',1,'mc','auto','감염병의 위험성을 토의할 때 가장 중요한 것은 무엇인가요?',ARRAY['SC3-2-u4-X14','SC3-2-u4-X15']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C7","difficulty":1,"kind":"mc","stem":"감염병의 위험성을 토의할 때 가장 중요한 것은 무엇인가요?","options":[{"t":"조사한 내용으로 위험한 까닭을 이야기하기","correct":true},{"t":"증상을 모두 외우기","mis":"SC3-2-u4-X14"},{"t":"친구 의견 비웃기","mis":"SC3-2-u4-X15"},{"t":"내 말만 하기","mis":"SC3-2-u4-X15"}],"explanation":["외우기보다 토의예요.","까닭을 이야기해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#4','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C9',1,'mc','auto','감염병으로부터 안전한 사회에서 볼 수 있는 모습은 무엇인가요?',ARRAY['SC3-2-u4-X17']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C9","difficulty":1,"kind":"mc","stem":"감염병으로부터 안전한 사회에서 볼 수 있는 모습은 무엇인가요?","options":[{"t":"여러 사람이 함께 음식을 먹는다","correct":true},{"t":"식당에 모여 먹을 수 없다","mis":"SC3-2-u4-X17"},{"t":"공공시설이 문을 닫는다","mis":"SC3-2-u4-X17"},{"t":"집에서만 지낸다","mis":"SC3-2-u4-X17"}],"explanation":["함께 모일 수 있어요.","식당을 떠올려요.","함께 먹어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#5','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C11',1,'mc','auto','다솜반 일지 ⑤에서 감염병 유행을 막는 데 도움이 되는 습관은 무엇인가요?',ARRAY['SC3-2-u4-X24']::text[],false,'{"seq":5,"concept":"SC3-2-u4-C11","difficulty":1,"kind":"mc","stem":"다솜반 일지 ⑤에서 감염병 유행을 막는 데 도움이 되는 습관은 무엇인가요?","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"SC3-2-u4-X24"},{"t":"㉡","mis":"SC3-2-u4-X24"},{"t":"㉣","mis":"SC3-2-u4-X24"}],"explanation":["올바른 습관을 찾아요.","옷소매로 가렸어요.","㉢이에요."],"asset":{"type":"passage","lines":["㉠ 운동장에서 놀고 손을 씻지 않은 채 간식을 먹었다.","㉡ 열이 나는데도 사람이 많은 놀이공원에 갔다.","㉢ 기침이 나서 옷소매로 입과 코를 가렸다.","㉣ 여행 중에 확인하지 않은 물을 마셨다."],"title":"다솜반 일지 ⑤ 생활 습관 돌아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#6','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C13',1,'mc','auto','예방접종은 언제 하나요?',ARRAY['SC3-2-u4-X29']::text[],false,'{"seq":6,"concept":"SC3-2-u4-C13","difficulty":1,"kind":"mc","stem":"예방접종은 언제 하나요?","options":[{"t":"정해진 시기에","correct":true},{"t":"아무 때나","mis":"SC3-2-u4-X29"},{"t":"아플 때만","mis":"SC3-2-u4-X29"},{"t":"하지 않아도 된다","mis":"SC3-2-u4-X29"}],"explanation":["예방 수칙 ④예요.","시기가 있어요.","정해진 시기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#7','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C15',1,'mc','auto','실천 계획에 담을 내용이 아닌 것은 무엇인가요?',ARRAY['SC3-2-u4-X33']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C15","difficulty":1,"kind":"mc","stem":"실천 계획에 담을 내용이 아닌 것은 무엇인가요?","options":[{"t":"못 지킨 친구 이름","correct":true},{"t":"실천 장소","mis":"SC3-2-u4-X33"},{"t":"실천할 수칙","mis":"SC3-2-u4-X33"},{"t":"실천을 돕는 방법","mis":"SC3-2-u4-X33"}],"explanation":["계획 칸을 떠올려요.","비난은 돕는 방법이 아니에요.","친구 이름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#8','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C18',1,'mc','auto','손 씻기 6단계의 첫 단계는 무엇인가요?',ARRAY['SC3-2-u4-X39']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C18","difficulty":1,"kind":"mc","stem":"손 씻기 6단계의 첫 단계는 무엇인가요?","options":[{"t":"손바닥을 마주 대고 문지르기","correct":true},{"t":"손톱 밑 문지르기","mis":"SC3-2-u4-X39"},{"t":"엄지손가락 돌려 문지르기","mis":"SC3-2-u4-X39"},{"t":"손등 문지르기","mis":"SC3-2-u4-X39"}],"explanation":["처음 단계예요.","손바닥이에요.","손바닥 문지르기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#9','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C3',2,'ox','auto','감염병은 햇빛에 감염되어 생기는 질병이에요.',ARRAY['SC3-2-u4-X06']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C3","difficulty":2,"kind":"ox","stem":"감염병은 햇빛에 감염되어 생기는 질병이에요.","answer":"X","reason_options":[{"t":"감염병은 세균, 바이러스 같은 병원체에 감염되어 생기기 때문에","correct":true},{"t":"햇빛이 병의 원인이 되는 본체이기 때문에","mis":"SC3-2-u4-X06"}],"mis":"SC3-2-u4-X06","explanation":["병원체를 떠올려요.","세균, 바이러스예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#10','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C6',2,'ox','auto','감염병 카드를 만들 때는 어디에서 찾았는지 출처를 밝혀요.',ARRAY['SC3-2-u4-X12']::text[],false,'{"seq":10,"concept":"SC3-2-u4-C6","difficulty":2,"kind":"ox","stem":"감염병 카드를 만들 때는 어디에서 찾았는지 출처를 밝혀요.","answer":"O","reason_options":[{"t":"올바른 정보인지 확인할 수 있게 하기 때문에","correct":true},{"t":"출처를 쓰면 카드가 지저분해지기 때문에","mis":"SC3-2-u4-X12"}],"mis":"SC3-2-u4-X12","explanation":["조사 방법을 떠올려요.","어디서 찾았는지요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#11','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C8',2,'ox','auto','다솜반 일지 ④처럼 놀이터가 텅 빈 것은 감염병이 크게 유행했을 때의 모습이에요.',ARRAY['SC3-2-u4-X18']::text[],false,'{"seq":11,"concept":"SC3-2-u4-C8","difficulty":2,"kind":"ox","stem":"다솜반 일지 ④처럼 놀이터가 텅 빈 것은 감염병이 크게 유행했을 때의 모습이에요.","answer":"O","reason_options":[{"t":"크게 유행할 때는 사람들이 모여 생활하기 어렵기 때문에","correct":true},{"t":"놀이터는 원래 늘 비어 있기 때문에","mis":"SC3-2-u4-X18"}],"mis":"SC3-2-u4-X18","explanation":["할머니 말씀을 봐요.","크게 유행했을 때예요.","그래서 O예요."],"asset":{"type":"passage","lines":["할머니 말씀 — 「크게 유행했을 때 사람들이 모이지 않았단다.」","놀이터 — 사람이 없어 텅 비었다.","도서관 — 문을 닫아 책을 빌리기 어려웠다.","과학자 — 원인을 밝히고 예방하는 방법을 연구했다."],"title":"다솜반 일지 ④ 크게 유행했던 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#12','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C11',2,'ox','auto','생활 습관은 감염병 유행과 아무 관련이 없어요.',ARRAY['SC3-2-u4-X23']::text[],false,'{"seq":12,"concept":"SC3-2-u4-C11","difficulty":2,"kind":"ox","stem":"생활 습관은 감염병 유행과 아무 관련이 없어요.","answer":"X","reason_options":[{"t":"손 씻기나 기침 예절 같은 습관에 따라 감염병이 옮거나 막히기 때문에","correct":true},{"t":"감염병은 날씨만 영향을 미치기 때문에","mis":"SC3-2-u4-X23"}],"mis":"SC3-2-u4-X23","explanation":["다솜반 일지 ⑤를 떠올려요.","습관 때문에 옮아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#13','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C14',2,'ox','auto','다솜반 일지 ⑥처럼 예방 수칙은 믿을 수 있는 곳에서 조사하고 출처를 밝혀 공유해요.',ARRAY['SC3-2-u4-X32']::text[],false,'{"seq":13,"concept":"SC3-2-u4-C14","difficulty":2,"kind":"ox","stem":"다솜반 일지 ⑥처럼 예방 수칙은 믿을 수 있는 곳에서 조사하고 출처를 밝혀 공유해요.","answer":"O","reason_options":[{"t":"바른 정보를 함께 나누어야 실천에 도움이 되기 때문에","correct":true},{"t":"출처를 밝히면 친구들이 따라 하지 않기 때문에","mis":"SC3-2-u4-X32"}],"mis":"SC3-2-u4-X32","explanation":["둘째 줄을 읽어요.","출처를 적었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["노랫말 — 「소매로 가려요, 콜록콜록 기침할 때」","조사 — 믿을 수 있는 누리집에서 찾고 출처를 적었다.","더 넣을 수칙 — 음식은 익혀 먹고 깨끗한 물 마시기"],"title":"다솜반 일지 ⑥ 예방 수칙 노래"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#14','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C15',2,'ox','auto','실천할 수칙은 「손 씻기」처럼 짧게만 정하는 것이 좋아요.',ARRAY['SC3-2-u4-X33']::text[],false,'{"seq":14,"concept":"SC3-2-u4-C15","difficulty":2,"kind":"ox","stem":"실천할 수칙은 「손 씻기」처럼 짧게만 정하는 것이 좋아요.","answer":"X","reason_options":[{"t":"무엇을 어떻게 할지 드러나게 구체적으로 정해야 실천하기 쉽기 때문에","correct":true},{"t":"짧을수록 저절로 잘 지켜지기 때문에","mis":"SC3-2-u4-X33"}],"mis":"SC3-2-u4-X33","explanation":["구체적인 수칙을 떠올려요.","30초, 비누가 들어가요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#15','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C18',2,'ox','auto','손 씻기 6단계에서 엄지손가락은 돌려 가며 문질러요.',ARRAY['SC3-2-u4-X40']::text[],false,'{"seq":15,"concept":"SC3-2-u4-C18","difficulty":2,"kind":"ox","stem":"손 씻기 6단계에서 엄지손가락은 돌려 가며 문질러요.","answer":"O","reason_options":[{"t":"엄지손가락도 빠뜨리지 않고 꼼꼼히 씻어야 하기 때문에","correct":true},{"t":"엄지손가락은 씻지 않아도 되기 때문에","mis":"SC3-2-u4-X40"}],"mis":"SC3-2-u4-X40","explanation":["5단계를 떠올려요.","돌려 가며 문질러요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#16','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C7',2,'ox','auto','감염병은 예방할 수 없어서 위험해요.',ARRAY['SC3-2-u4-X13']::text[],false,'{"seq":16,"concept":"SC3-2-u4-C7","difficulty":2,"kind":"ox","stem":"감염병은 예방할 수 없어서 위험해요.","answer":"X","reason_options":[{"t":"감염병은 다른 사람에게 옮길 수 있어 위험하지만, 예방 수칙으로 예방할 수 있기 때문에","correct":true},{"t":"어떤 방법으로도 막을 수 없기 때문에","mis":"SC3-2-u4-X13"}],"mis":"SC3-2-u4-X13","explanation":["위험한 까닭을 떠올려요.","예방 수칙이 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#17','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C4',3,'mc','auto','독감에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC3-2-u4-X08','SC3-2-u4-X05','SC3-2-u4-X09']::text[],false,'{"seq":17,"concept":"SC3-2-u4-C4","difficulty":3,"kind":"mc","stem":"독감에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"주로 겨울철에 걸리고 예방접종으로 어느 정도 예방할 수 있는 감염병이다","correct":true},{"t":"감기가 심해진 것이라 따로 예방할 수 없다","mis":"SC3-2-u4-X08"},{"t":"다쳐서 생기는 병이다","mis":"SC3-2-u4-X05"},{"t":"예방접종은 독감과 관련 없다","mis":"SC3-2-u4-X09"}],"explanation":["독감을 떠올려요.","예방접종이 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#18','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C7',3,'mc','auto','감염병 토의에서 친구가 「여름에도 감염병에 걸려.」라고 했을 때 나와 생각이 다르다면 알맞은 행동은 무엇인가요?',ARRAY['SC3-2-u4-X15','SC3-2-u4-X14']::text[],false,'{"seq":18,"concept":"SC3-2-u4-C7","difficulty":3,"kind":"mc","stem":"감염병 토의에서 친구가 「여름에도 감염병에 걸려.」라고 했을 때 나와 생각이 다르다면 알맞은 행동은 무엇인가요?","options":[{"t":"끝까지 듣고 조사한 자료를 보여 주며 내 생각을 말한다","correct":true},{"t":"「그런 말은 이상해.」라며 비웃는다","mis":"SC3-2-u4-X15"},{"t":"친구 말을 끊고 내 말만 한다","mis":"SC3-2-u4-X15"},{"t":"증상 목록을 외워 보라고 한다","mis":"SC3-2-u4-X14"}],"explanation":["존중하며 토의해요.","근거를 보여 줘요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#19','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C9',3,'mc','auto','과학 기술로 감염병으로부터 안전한 사회를 만드는 방법을 바르게 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X20']::text[],false,'{"seq":19,"concept":"SC3-2-u4-C9","difficulty":3,"kind":"mc","stem":"과학 기술로 감염병으로부터 안전한 사회를 만드는 방법을 바르게 묶은 것은 무엇인가요?","options":[{"t":"감염병의 원인을 밝힌다, 진단하고 치료한다, 예방하는 방법을 찾는다","correct":true},{"t":"원인을 모른 채 둔다, 연구를 멈춘다","mis":"SC3-2-u4-X20"},{"t":"사람들을 영원히 집에만 있게 한다","mis":"SC3-2-u4-X20"},{"t":"병원을 모두 없앤다","mis":"SC3-2-u4-X20"}],"explanation":["과학자들이 하는 일이에요.","원인·치료·예방이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#20','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C11',3,'mc','auto','다솜반 일지 ⑤의 ㉡을 바르게 고친 행동은 무엇인가요?',ARRAY['SC3-2-u4-X24','SC3-2-u4-X21','SC3-2-u4-X23']::text[],false,'{"seq":20,"concept":"SC3-2-u4-C11","difficulty":3,"kind":"mc","stem":"다솜반 일지 ⑤의 ㉡을 바르게 고친 행동은 무엇인가요?","options":[{"t":"열이 날 때는 놀이공원에 가지 않고 집에서 쉰다","correct":true},{"t":"열이 나도 마스크 없이 놀이공원에 간다","mis":"SC3-2-u4-X24"},{"t":"놀이공원에서 친구들과 음식을 나눠 먹는다","mis":"SC3-2-u4-X21"},{"t":"생활 습관은 상관없으니 그대로 간다","mis":"SC3-2-u4-X23"}],"explanation":["아플 때를 떠올려요.","사람이 많은 곳이에요.","집에서 쉬어요."],"asset":{"type":"passage","lines":["㉠ 운동장에서 놀고 손을 씻지 않은 채 간식을 먹었다.","㉡ 열이 나는데도 사람이 많은 놀이공원에 갔다.","㉢ 기침이 나서 옷소매로 입과 코를 가렸다.","㉣ 여행 중에 확인하지 않은 물을 마셨다."],"title":"다솜반 일지 ⑤ 생활 습관 돌아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#21','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C13',3,'mc','auto','기침이 심한 날 학교에서 할 행동으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X28','SC3-2-u4-X27']::text[],false,'{"seq":21,"concept":"SC3-2-u4-C13","difficulty":3,"kind":"mc","stem":"기침이 심한 날 학교에서 할 행동으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"마스크를 쓰고 기침할 때 옷소매로 입과 코를 가린다","correct":true},{"t":"손바닥으로 가린 뒤 그 손으로 친구 연필을 빌린다","mis":"SC3-2-u4-X28"},{"t":"친구 얼굴 쪽으로 기침한다","mis":"SC3-2-u4-X28"},{"t":"기침한 뒤 물로만 손을 살짝 헹군다","mis":"SC3-2-u4-X27"}],"explanation":["기침 예절이에요.","비말을 막아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#22','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C17',3,'mc','auto','손 씻기를 「가장 간단하면서도 효과적인 예방 방법」이라고 하는 까닭은 무엇인가요?',ARRAY['SC3-2-u4-X37','SC3-2-u4-X38','SC3-2-u4-X27']::text[],false,'{"seq":22,"concept":"SC3-2-u4-C17","difficulty":3,"kind":"mc","stem":"손 씻기를 「가장 간단하면서도 효과적인 예방 방법」이라고 하는 까닭은 무엇인가요?","options":[{"t":"누구나 쉽게 할 수 있고, 올바르게 씻기만 해도 많은 감염병을 예방할 수 있어서","correct":true},{"t":"세계 손 씻기의 날에만 하면 돼서","mis":"SC3-2-u4-X37"},{"t":"손이 깨끗해 보이면 안 해도 돼서","mis":"SC3-2-u4-X38"},{"t":"물만 묻혀도 돼서","mis":"SC3-2-u4-X27"}],"explanation":["간단하고 효과적이에요.","많은 감염병을 막아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#23','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C10',4,'essay','teacher','다솜반 일지 ⑤의 ㉠, ㉡, ㉣ 가운데 두 가지를 골라 무엇을 통해 감염될 수 있는지 쓰고, 각각 감염병을 막는 습관으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC3-2-u4-C10","difficulty":4,"kind":"essay","stem":"다솜반 일지 ⑤의 ㉠, ㉡, ㉣ 가운데 두 가지를 골라 무엇을 통해 감염될 수 있는지 쓰고, 각각 감염병을 막는 습관으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: ㉠은 손을 씻지 않은 채 간식을 먹어 손을 통해 감염될 수 있으니, 간식을 먹기 전에 비누로 흐르는 물에 30초 이상 손을 씻는다. ㉣은 확인하지 않은 물을 마셔 오염된 물을 통해 감염될 수 있으니, 깨끗한 물인지 확인하고 마신다.","scoring_points":["한 습관의 감염 과정을 썼는가","다른 습관의 감염 과정을 썼는가","두 습관을 막는 습관으로 바르게 바꾸었는가"]},"explanation":["두 가지를 골라요.","감염 과정을 써요.","습관을 바꿔요."],"asset":{"type":"passage","lines":["㉠ 운동장에서 놀고 손을 씻지 않은 채 간식을 먹었다.","㉡ 열이 나는데도 사람이 많은 놀이공원에 갔다.","㉢ 기침이 나서 옷소매로 입과 코를 가렸다.","㉣ 여행 중에 확인하지 않은 물을 마셨다."],"title":"다솜반 일지 ⑤ 생활 습관 돌아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#24','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C18',4,'mc','auto','다솜반 일지 ⑧의 친구 가가 다음에 손을 씻을 때 가장 알맞은 방법은 무엇인가요?',ARRAY['SC3-2-u4-X40','SC3-2-u4-X27','SC3-2-u4-X39']::text[],false,'{"seq":24,"concept":"SC3-2-u4-C18","difficulty":4,"kind":"mc","stem":"다솜반 일지 ⑧의 친구 가가 다음에 손을 씻을 때 가장 알맞은 방법은 무엇인가요?","options":[{"t":"비누를 쓰고 흐르는 물에 30초 이상, 손바닥부터 손톱 밑까지 6단계를 모두 한다","correct":true},{"t":"손톱 밑만 오래 문지르고 나머지는 뺀다","mis":"SC3-2-u4-X40"},{"t":"물만 묻히고 손톱 밑을 한 번 본다","mis":"SC3-2-u4-X27"},{"t":"6단계를 거꾸로 손톱 밑부터 손바닥 하나만 한다","mis":"SC3-2-u4-X39"}],"explanation":["빠뜨린 단계를 넣어요.","여섯 단계 모두예요.","첫 번째예요."],"asset":{"type":"passage","lines":["10월 15일에 손 씻기 6단계를 함께 해 보았다.","친구 가는 손톱 밑 문지르기를 빠뜨렸다.","반 다짐 — 「이날만이 아니라 매일 올바르게 씻자.」"],"title":"다솜반 일지 ⑧ 세계 손 씻기의 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u4_review_d#25','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C11',4,'essay','teacher','「감염병과 건강한 생활」 단원에서 배운 감염병의 뜻, 감염병의 위험성, 생활 습관과 감염병 유행, 감염병 예방 수칙 가운데 세 가지를 골라 각각 한 문장으로 설명하고, 내가 생활 속에서 실천할 예방 수칙을 구체적으로 한 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-2-u4-C11","difficulty":4,"kind":"essay","stem":"「감염병과 건강한 생활」 단원에서 배운 감염병의 뜻, 감염병의 위험성, 생활 습관과 감염병 유행, 감염병 예방 수칙 가운데 세 가지를 골라 각각 한 문장으로 설명하고, 내가 생활 속에서 실천할 예방 수칙을 구체적으로 한 가지 쓰세요.","answer_guide":{"answer":"예: 감염병은 병원체에 감염되어 생기는 질병이다. 감염병은 누구나 걸릴 수 있고 다른 사람에게 옮아 많은 사람에게 퍼질 수 있다. 생활 습관은 감염병 유행에 영향을 미친다. 나는 기침할 때 옷소매로 입과 코를 가리겠다.","scoring_points":["세 가지를 골랐는가","세 가지를 배운 내용에 맞게 설명했는가","실천할 예방 수칙을 구체적으로 썼는가"]},"explanation":["배운 것을 떠올려요.","세 가지를 골라요.","실천할 수칙을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
